(window.GIM_TS=window.GIM_TS||{})["Sanhedrin.0"]={"from":0,"a":[["\u0003דיני ממונות\u0004 נידונים על ידי \u0003שלשה\u0004 דיינים. דיני \u0003גזילות וחבלות\u0004 — \u0003בשלושה\u0004. תשלומי \u0003נזק\u0004 שמשלם אדם אם הוא מזיק או שבהמתו המועדה לכך הזיקה, \u0003ו\u0004כן \u0003חצי נזק\u0004 שמשלם עבור נזקי נגיחה (קרן) של שור תם (שעדיין לא העידו בו שנגח יותר מפעמיים, ככתוב: \"וכי יגוף שור איש את שור רעהו ומת ומכרו את השור החי וחצו את כספו וגם את המת יחצון\". שמות כא, לה), וכן \u0003תשלומי כפל\u0004 שמשלם גנב שנתפס בגניבה (\"אם המצא תמצא בידו הגניבה משור עד חמור עד שה חיים שנים ישלם\". שמות כב, ג), \u0003ותשלומי ארבעה וחמשה\u0004 שמשלם מי שגנב וטבח שור או שה (\"כי יגנוב איש שור או שה וטבחו או מכרו חמישה בקר ישלם תחת השור וארבע צאן תחת השה\". שמות כא, לז) — אף אלה נידונים \u0003בשלשה.\u0004","דין \u0003האונס\u0004 בתולה (\"כי ימצא איש נערה בתולה אשר לא אורשה ותפשה ושכב עמה ונמצאו. ונתן האיש השוכב עמה לאבי הנערה חמישים כסף\". דברים כב, כט), \u0003ו\u0004כן דין \u0003המפתה\u0004 בתולה שצריך לשלם לה כמוהר בתוליה (\"וכי יפתה איש בתולה אשר לא אורשה ושכב עמה כסף ישקול כמוהר הבתולות\". שמות כב, טו). \u0003ו\u0004כן \u0003המוציא שם רע\u0004 על אשתו שטוען שכאשר נשאה לא היתה בתולה, ומאשימה שזנתה בהיותה מאורסת לו, (\"כי יקח איש אשה... ושם לה עלילות דברים והוציא עליה שם רע... ולא מצאתי לה בתולים... וענשו אותו מאה כסף ונתנו לאבי הנערה...\". דברים כב, יג–יט) — \u0003בשלשה,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: מוציא שם רע\u0004 נידון \u0003ב\u0004בית דין של \u0003עשרים ושלשה\u0004 דיינים המוסמך לדון גם בדיני נפשות \u0003מפני שיש בו\u0004 בדין זה גם \u0003דיני נפשות\u0004, כי אם מביא הבעל עדים שהאשה זנתה בהיותה מאורסת — תתחייב מיתה, או לחילופין יתחייבו מיתה העדים שהעלילו עליה עלילת שווא.","חובת \u0003מכות\u0004 שמלקים אדם שעבר על מצוות לא תעשה — נידונת \u0003בשלשה, משום\u0004 (בשם) \u0003ר' ישמעאל אמרו:\u0004 אף מכות \u0003בעשרים ושלשה.\u0004","\u0003עיבור החדש\u0004 שצריך לקבוע מתי ראש החודש — \u0003בשלשה. עיבור השנה,\u0004 שהוא הוספת חודש לשנה כאשר יש צורך בכך — \u0003בשלשה,\u0004 אלו \u0003דברי ר' מאיר. רבן שמעון בן גמליאל אומר: בשלשה מתחילין\u0004 לדון בענין, \u0003ובחמשה נושאין ונותנין\u0004 בו, \u0003וגומרין בשבעה\u0004 דיינים מפני חשיבות הדין. ואולם מודה הוא ש\u0003אם גמרו בשלשה\u0004 בלבד — השנה \u0003מעוברת\u0004.","\u0003סמיכת זקנים, ועריפת עגלה,\u0004 כשנהרג אדם ואין יודעים מי הרגו (דברים כא, א–ט) — \u0003בשלשה,\u0004 אלו \u0003דברי ר' שמעון. ר' יהודה אומר: בחמשה. החליצה\u0004 שחולץ היבם לאשת אחיו שמת בלא בנים כאשר אינו רוצה לשאת אותה (דברים כה, ה–י), \u0003והמיאונין\u0004 שילדה קטנה יתומה מאב שהשיאוה אמה או אחיה, כשהיא ממאנת להמשיך לחיות עם בעלה, ונישואיה מתבטלים, נעשה דבר זה בפני בית דין של \u0003שלשה.\u0004","\u0003נטע רבעי,\u0004 שהם פירות עצים בשנה הרביעית לנטיעתם שמותר לאכלם לאחר שפדאום והביאו תמורתם הכספית לירושלים, \u0003ומעשר שני\u0004 כשאינו יכול להביאו ולאוכלו בירושלים וצריך לפדותו אלא \u0003שאין דמיו ידועין\u0004 — \u0003בשלשה.\u0004 הערכתם של \u0003ההקדשות בשלשה, הערכין\u0004 שאף הם ממיני ההקדשות (ויקרא כז, א–ח) \u0003המטלטלים\u0004 — מוערכים \u0003בשלשה. ר' יהודה אומר:\u0004 צריך שיהיה \u0003אחד מהן כהן.\u0004","\u0003והקרקעות\u0004 המוקדשות נערכות ב\u0003תשעה\u0004 דיינים \u0003ו\u0004עוד \u0003כהן\u0004 אחד. \u0003ואדם\u0004 שיש להעריך את דמיו לצורך הקדש \u0003כיוצא בהן\u0004 בדומה לקרקעות.","\u0003דיני נפשות\u0004 בכללם נדונים \u0003בעשרים ושלשה\u0004 דיינים. \u0003הרובע והנרבע,\u0004 כלומר, בהמה שרבעה אשה, או שנרבעה על ידי גבר — דינם \u0003בעשרים ושלשה, שנאמר:\u0004 \"ואשה אשר תקרב אל כל בהמה לרבעה אותה \u0003והרגת את האשה ואת הבהמה\"\u0004 (ויקרא כ, טז), \u0003ואומר \"\u0004ואיש אשר יתן שכבתו בבהמה מות יומת \u0003ואת הבהמה תהרגו\"\u0004 (ויקרא כ, טו), שהשווה הכתוב המתת הבהמה למיתת אדם לענין הדין והדיינים.","\u0003שור\u0004 \u0003הנסקל\u0004 משום שהרג נפש אדם דינו אף הוא \u0003בעשרים ושלשה, שנאמר: \"\u0004ואם שור נגח הוא מתמול שלשום והועד בבעליו ולא ישמרנו והמית איש או אשה \u0003השור יסקל וגם בעליו יומת\"\u0004 (שמות כא, כט), ולמדנו מכאן: \u0003כמיתת בעלים כך מיתת השור.\u0004 הכתוב מדבר אמנם בשור אבל גם \u0003הזאב והארי, הדוב והנמר והברדלס והנחש\u0004 שהמיתו — \u0003מיתתן בעשרים ושלשה. ר' אליעזר אומר\u0004 אלה אינם צריכים בית דין, אלא \u0003כל הקודם להורגן זכה. ר' עקיבא אומר: מיתתן בעשרים ושלשה.\u0004","\u0003אין דנין לא את השבט\u0004 שחטא \u0003ולא את נביא השקר, ולא את כהן גדול\u0004 שחטא בחטא שעונשו מוות, \u0003אלא על פי בית דין של שבעים ואחד. ואין מוציאין\u0004 את העם \u0003למלחמת הרשות\u0004 (שאינה מלחמת מצוה שבתורה או מלחמת הגנה), \u0003אלא על פי בית דין של שבעים ואחד. אין מוסיפין על העיר\u0004 ירושלים \u0003ועל העזרות\u0004 של בית המקדש, \u0003אלא על פי בית דין של שבעים ואחד.\u0004 וכן \u0003אין עושין סנהדריו‍ת\u0004 (בתי דין) של עשרים ושלושה \u0003לשבטים, אלא על פי בית דין של שבעים ואחד.\u0004","\u0003אין עושין עיר הנדחת\u0004 כאשר כל בני העיר חטאו בעבודה זרה, ועל פי מצוות התורה הורגים את כל אנשיה ומחריבים אותה (דברים יג, יג–יט), \u0003אלא על פי בית דין של שבעים ואחד. אין עושין עיר הנדחת בספר\u0004 סמוך לגבולות הארץ, \u0003ולא\u0004 עושים \u0003שלש\u0004 ערים נדחות, \u0003אבל עושין אחת או שתים\u0004 בתוך הארץ.","בענין מספר הדיינים בבתי הדין השונים מביאים מדרש הלכה: \u0003סנהדרין גדולה היתה של שבעים ואחד\u0004 דיינים, \u0003וקטנה של עשרים ושלשה. מנין לגדו‍לה שהיא של שבעים ואחד\u0004 — \u0003שנאמר: \"אספה לי שבעים איש מזקני ישראל\u0004 אשר ידעת כי הם זקני העם ושוטריו ולקחת אותם אל אהל מועד והתיצבו שם עמך\u0003\"\u0004 (במדבר יא, טז), \u0003ומשה על גביהן\u0004 — הרי יחד שבעים ואחד. \u0003ר' יהודה אמר:\u0004 משה אינו מן המנין, ולפיכך סנהדרין גדולה מניינה \u0003שבעים.\u0004","\u0003ומנין ל\u0004סנהדרין \u0003קטנה שהיא של עשרים ושלשה\u0004 — \u0003שנאמר: \"ושפטו העדה\u0004 בין המכה ובין גואל הדם על המשפטים האלה\u0003\"\u0004 (במדבר לה, כד) \u0003\"והצילו העדה\u0004 את הרוצח מיד גואל הדם\u0003\"\u0004 (במדבר לה, כה), ואם כן יש \u0003עדה\u0004 שהיא לפחות עשרה אנשים שהיא \u0003שו‍פטת,\u0004 כלומר, כנוטה לחובה, \u0003ועדה\u0004 (עשרה לפחות) שהיא \u0003מצלת\u0004 את הנאשם — \u0003הרי כאן עשרים.\u0004","\u0003ומנין לעדה שהיא עשרה\u0004 אנשים לכל הפחות — \u0003שנאמר\u0004 על המרגלים: \u0003\"עד מתי לעדה הרעה הזאת\u0004 אשר המה מלינים עלי\u0003\"\u0004 (במדבר יד, כז) והם היו שנים עשר איש, \u0003יצאו\u0004 מהם \u0003יהושע וכלב\u0004 שלא הוציאו דיבת הארץ רעה, הרי שלעשרת האנשים הנשארים קורא הכתוב עדה. הרי למדנו מכאן לענין דיני נפשות שהם בעשרים דיינים.","\u0003ומנין להביא עוד שלשה\u0004 דיינים לבית דין זה? מן הכתוב \"לא תהיה אחרי רבים לרעת ולא תענה על ריב לנטות אחרי רבים להטות\" (שמות כג, ב), \u0003ממשמע שנאמר: \"לא תהיה אחרי רבים לרעת\"\u0004 נלמד שאין הולכים אחר הרוב כשיש בכך צד של גרימת מוות וכיוצא בו. \u0003שומע אני\u0004 מכאן \u0003שאהיה עמהם\u0004 עם הרבים \u0003לטובה,\u0004 ואכריע כדעתם. \u0003אם כן למה נאמר\u0004 באותו פסוק \u0003\"אחרי רבים להטת\",\u0004 שממנו אפשר להבין כי יש לקבל בכל מקרה את הכרעת הרוב? כדי לישב את הסתירה יש להסביר כך: \u0003לא כהטייתך לטובה הטייתך לרעה; הטייתך לטובה\u0004 יכולה להיעשות \u0003על פי\u0004 רוב של דיין \u0003אחד,\u0004 שכיון שיש רוב של איש אחד בלבד — עושים כן. ואילו \u0003הטייתך לרעה על פי שנים\u0004 לפחות, כי לכך צריך רוב ניכר יותר, ואם כן יש צורך שיהיו בבית הדין עשרים ושנים איש כדי שאפשר יהיה שתהא עדה שופטת שהיא עשרה אנשים הדנים לחובה, ועדה מצלת שהיא עשרה הדנים לזכות, ועוד שנים שיוכלו להכריע את הכף גם לחובה."],["\u0003ואין בית דין שקול\u0004 שאין עושים לכתחילה בית דין זוגי, שלא יוכל להגיע לידי הכרעה, לכן \u0003מוסיפין עליהם עוד אחד\u0004 להכריע, \u0003הרי כאן עשרים ושלשה\u0004 דיינים.","\u0003וכמה\u0004 תושבים \u0003יהא בעיר ותהא\u0004 העיר \u0003ראויה לסנהדרין\u0004 קטנה? \u0003מאה ועשרים\u0004 איש, כפי שיבואר בגמרא שבמספר כזה אפשר למצוא כל האנשים הנחוצים לדיון. \u0003ר' נחמיה אומר: מאתים ושלשים, כנגד שרי עשרות,\u0004 כלומר, שכל אחד מחברי הסנהדרין יחשב כממונה על עשרה, שבפחות מכן אין זה כבוד שיהיו חברי סנהדרין במקום שאינם יכולים להיחשב כממונים לפחות על עשרה בני אדם.","במשנה נאמר כי דיני ממונות נידונים בשלושה, וכן דיני גזילות וחבלות. ושואלים: וכי אלה שני דברים נבדלים? \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003גזילות וחבלות לאו\u0004 \u0005[לא]\u0006 \u0003דיני ממונות נינהו\u0004 \u0005[הם]?\u0006 ודי היה לומר שדיני ממונות בשלושה! \u0003אמר ר' אבהו:\u0004 בלשון \u0003\"מה הן\" קתני\u0004 \u0005[שנה],\u0006 ולא פירוט הוא זה אלא הגדרה וכך יש להבין: \u0003מה הן דיני ממונות\u0004 שנאמרו כאן — דיני \u0003גזילות וחבלות, אבל\u0004 דיני \u0003הודאות\u0004 שמודה אדם שהוא חייב כסף לחבירו, \u0003והלואות\u0004 שלא נפרעו — \u0003לא\u0004 נכנסו בכלל זה.","\u0003וצריכא\u0004 \u0005[ונצרכה]\u0006 לשון זו, שתיאמר גם בכלל וגם בביאור, \u0003דאי תנא\u0004 \u0005[שאילו היה שונה]\u0006 רק \u0003דיני ממונות\u0004 בשלושה \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 ש\u0003אפילו הודאות והלואות\u0004 בכלל זה, על כן \u0003תנא\u0004 \u0005[שנה]\u0006 ובאר: \u0003גזילות וחבלות\u0004 שרק הם בכלל. \u0003ואי תנא\u0004 \u0005[ואילו היה שונה]\u0006 רק \u0003גזילות וחבלות, ולא קתני\u0004 \u0005[היה שונה]\u0006 \u0003דיני ממונות הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הוא הדין\u0004 ש\u0003אפילו הודאות והלואות\u0004 בשלושה, \u0003והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 במשנה רק \u0003גזילות וחבלות\u0004 הייתי מבין אותו כדוגמא בלבד, והייתי אומר כי \u0003משום\u0004 ש\u0003עיקר\u0004 הדין שיש צורך ב\u0003שלשה\u0004 דיינים \u0003דכתיבי\u0004 \u0005[\u0006\u0005שכתובים],\u0006 \u0003בגזילות וחבלות כתיבי\u0004 \u0005[כתובים].\u0006","והראיה לדבר, בענין \u0003גזילות\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 כאשר מפקידים דבר בידי אדם וההוא טוען כי נגנב: \u0003\"ונקרב בעל הבית אל האלהים\u0004 אם לא שלח ידו במלאכת רעהו\u0003\"\u0004 (שמות כב, ז) ו\"אלוהים\" משמעו — דיינים. וכן בדין \u0003חבלות\u0004 ברור לנו שהן כגזילות, כי \u0003מה לי חבל\u0004 והזיק \u0003בגופו, מה לי חבל בממונו.\u0004 ומשום שנצרכו שני דינים אלה \u0003תנא\u0004 \u0005[שנה\u0006 במשנה\u0005]:\u0006 \u0003מה הן דיני ממונות\u0004 — \u0003גזלות וחבלות, אבל הודאות והלואות\u0004 — \u0003לא.\u0004","ושואלים: \u0003ולמאי\u0004 \u0005[ולמה,\u0006 לאיזה ענין\u0005]\u0006 אין הודאות והלוואות כגזילות? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 לענין זה ש\u0003לא בעינן\u0004 \u0005[צריכים אנו]\u0006 לדון את ההודאות וההלוואות בבית דין של \u0003שלשה\u0004 — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבהו\u0004 עצמו: \u0003שנים שדנו דיני ממונות\u0004 מכל סוג, ואפילו הודאות \u0003לדברי הכל אין דיניהם דין,\u0004 שאין בית דין פחות משלושה.","\u0003אלא\u0004 לא בזה ההבדל, כי אם ש\u0003לא בעינן\u0004 \u0005[צריכים אנו]\u0006 לדיני הודאות והלוואות שיהיו חברי בית הדין \u0003מומחין,\u0004 שלמדו תורה הרבה ובקיאים בדינים וקיבלו רשות להורות, אלא כל שלושה אנשים יכולים לשמש בית דין בענייני ממון אלה.","ואולם יש לברר: \u0003מאי קסבר\u0004 \u0005[מה\u0006 בעצם \u0005סבר]\u0006 התנא ששנה חלוקה זו? \u0003אי קסבר\u0004 \u0005[אם סבר]\u0006 ש\u0003עירוב פרשיות כתוב כאן,\u0004 שהפרשה הקטנה שממנה מוצא דין זה (שמות כב, ו–ח) דנה בכמה עניינים המעורבים זה בזה ונלמדים זה מזה, וממילא דיני גזילה ודיני הודאה או הלוואה המצויים בה נידונים כיחידה אחת, אם כן \u0003ליבעי נמי\u0004 \u0005[שיצטרכו גם כן]\u0006 בהודאות והלוואות שיהיו נדונים ב\u0003מומחין\u0004 כמו בדיני גזילות. \u0003ואי קסבר\u0004 \u0005[ואם סבר]\u0006 \u0003אין עירוב פרשיות כתוב כאן\u0004 אלא דין גזל לעצמו ודין הודאה לעצמו, אם כן \u0003שלשה\u0004 דיינים \u0003למה לי?\u0004 שמנין זה של הדיינים נלמד מן החזרה על המלה \"אלהים\" שלוש פעמים בפרשה זו ולא נאמר בדין הלוואות!","ומשיבים: \u0003לעולם קסבר\u0004 \u0005[סבר]\u0006 כי \u0003עירוב פרשיות כתוב כאן, ובדין הוא דליבעי נמי\u0004 \u0005[שיצטרכו גם כן]\u0006 בדיני הלוואות שלושה \u0003מומחין, והאי\u0004 \u0005[וזה]\u0006 ש\u0003לא בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003מומחין,\u0004 הרי זה \u0003משום\u0004 טעמו של \u0003ר' חנינא.\u0004 ש\u0003אמר ר' חנינא: דבר תורה\u0004 (על פי דין התורה) \u0003אחד דיני ממונות ואחד דיני נפשות\u0004 העדים נחקרים \u0003בדרישה ובחקירה\u0004 חמורה של קביעת הזמן, המקום והתנאים, שבודקים כל פרט בעדות, למצוא בה סתירות אפשריות,"],["\u0003שנאמר: \"משפט אחד יהיה לכם\"\u0004 (ויקרא כד, כב), שכל הדיינים ידונו באותה דרך, ונתפרש כי בדיני נפשות יש צורך בדרישה וחקירה (\"ודרשת וחקרת ושאלת היטב...\". דברים יג, טו). \u0003ומה טעם אמרו\u0004 חכמים כי ב\u0003דיני ממונות לא בעינן\u0004 \u0005[צריכים אנו]\u0006 בהם \u0003דרישה וחקירה?\u0004 תיקנו תקנה זו \u0003כדי שלא תנעול דלת בפני לווין,\u0004 שאם יצטרכו בדיון בגבייתה של הלוואה גם כן חקירה ודרישה של עדים, על כל קשיי ההוכחה שבדבר לא ירצו עוד המלוים להלוות לעניים, ומטעם זה עצמו גם ויתרו על הצורך בדיינים מומחים בדינים אלה.","ושואלים: \u0003אלא מעתה\u0004 שעשו חכמים תקנה זו למעט בדרישות בדיני ממונות, אם כן כיון שדי להם בדיינים הדיוטות (שאינם מומחים), אם כן, אם \u0003טעו\u0004 ההדיוטות בדונם דיני ממונות \u0003לא ישלמו,\u0004 וכאילו היו מומחים! ודוחים: \u0003כל שכן אתה נועל דלת בפני לווין,\u0004 שלא ירצו המלוים להלוות מחשש שבית דין טועה לא יפסוק כהלכה בעניינם.","על שיטת ההסבר של ר' אבהו למשנה, מקשים: \u0003אי הכי תרתי קתני\u0004 \u0005[אם כך\u0006 אתה מבין, הרי \u0005שני\u0006 דברים \u0005שנינו],\u0006 ובמקום לדחוק כפי שאמרנו נוח יותר להבין את משנתנו, שכאשר אמר \u0003דיני ממונות\u0004 סתם היתה הכוונה להודאות והלוואות ואלה נידונים \u0003בשלשה הדיוטות, גזילות וחבלות\u0004 — \u0003בשלשה מומחין.\u0004","\u0003ועוד\u0004 יש להקשות על ביאורו של ר' אבהו: אם המילים \"גזילות וחבלות\" הן רק כפירוט של \"דיני ממונות\" \u0003\"שלשה\" \"שלשה\" למה לי?\u0004 על כרחך, מזה שנאמר גם אחד דיני ממונות שהם בשלושה, וגם אחד גזילות וחבלות בשלושה, משמע שאלו הם שני דברים נפרדים!","\u0003אלא אמר רבא: תרתי קתני\u0004 \u0005[שני\u0006 דברים \u0005שנינו]\u0006 ושני דינים הם, והטעם הוא \u0003משום\u0004 שיטתו של \u0003ר' חנינא\u0004 להקל בכמה דברים בדיני ממונות, וכך יש להבין את משנתנו: דיני ממונות שהם הודאות והלוואות — בשלושה הדיוטות, וגזילות וחבלות — בשלושה מומחים. \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא אמר: מדאורייתא\u0004 \u0005[מן התורה]\u0006 ומעיקר הדין \u0003חד נמי\u0004 \u0005[\u0006דיין \u0005אחד גם כן]\u0006 \u0003כשר\u0004 לדיני הודאות והלוואות, \u0003שנאמר: \"בצדק תשפט עמיתך\"\u0004 (ויקרא יט, טו), שמתוך שנאמר \"תשפוט עמיתך\" בלשון יחיד — משמע שיש פעמים שיחיד רשאי לדון, \u0003אלא\u0004 תיקנו שידונו דיני ממונות בשלושה \u0003משום\u0004 \u0003יושבי קרנות\u0004 — אנשים בטלים שלא למדו ואינם עוסקים במשא ומתן, שמא יבואו הם לדון. וכדי להימנע שיהיה דיין אחד מיושבי קרנות עמדו על כך שיהא בית דין של שלושה.","ומקשים: \u0003אטו בתלתא מי לא הוו\u0004 \u0005[וכי בשלושה האם אינם יכולים להיות]\u0006 \u0003יושבי קרנות?\u0004 ומה תועלת בתוספת מספר! ומשיבים: בכל זאת, \u0003אי אפשר,\u0004 קשה להניח \u0003דלית בהו חד דגמיר\u0004 \u0005[שאין בהם אחד שלמד],\u0006 אבל אם יקחו רק דיין יחיד — שמא יזדמן להם אדם שלא קרא ולא שנה. ושואלים: \u0003אלא מעתה,\u0004 שלפי דין תורה דיינים הדיוטות כשרים הם, אם כן כאשר \u0003טעו\u0004 בדינם \u0003לא ישלמו!\u0004 ומשיבים: \u0003כל שכן דנפישי\u0004 \u0005[שירבו]\u0006 אז \u0003יושבי קרנות\u0004 שיכניסו עצמם לדין ולא יחששו לטעות.","ושואלים: \u0003מאי איכא\u0004 \u0005[מה\u0006 הבדל \u0005יש]\u0006 \u0003בין\u0004 שיטת \u0003רבא\u0004 האומר שדיני ממונות הם בשלושה הדיוטות משום טעמו של ר' חנינא, \u0003ל\u0004שיטת \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא\u0004 הסבור שמן התורה די בדיין אחד? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 לענין מה ש\u0003אמר שמואל: שנים שדנו\u0004 — \u0003דיניהן דין, אלא שנקראו בית דין חצוף. ל\u0004שיטת \u0003רבא לית ליה\u0004 \u0005[אינו מקבל]\u0006 את דעת \u0003שמואל,\u0004 ולדעתו בית דין של שלושה הוא הכרחי, ולא הקלו אלא שלא יצטרכו שלושה מומחים. \u0003לרב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא אית ליה\u0004 \u0005[יש לו,\u0006 הוא מקבל\u0005]\u0006 את שיטתו של \u0003שמואל,\u0004 שהרי לדעתו אפילו דיין אחד היה מספיק, והדיינים הנוספים אינם מעיקר הדין.","שנינו במשנה כי תשלומי \u0003נזק וחצי נזק\u0004 נידונים בשלושה. ושואלים: \u0003נזק היינו\u0004 \u0005[הריהו]\u0006 \u0003חבלות,\u0004 שהמלה \"חבלה\" כוללת כל מיני נזקים שגורם אדם או בהמתו לאחרים! ומשיבים: \u0003משום דקא בעי למיתנא\u0004 \u0005[שרצה לשנות\u0006 בהמשך\u0005]\u0006 \u0003חצי נזק\u0004 שהוא דין מיוחד, \u0003תני נמי\u0004 \u0005[שנה גם כן]\u0006 דין \u0003נזק שלם\u0004 (כלומר, נזק סתם שמשלם כל מה שהזיק).","ומקשים: \u0003חצי נזק נמי\u0004 \u0005[גם כן]\u0006 אין צורך בו, \u0003היינו\u0004 \u0005[הרי זה]\u0006 בדיוק כשאר \u0003חבלות,\u0004 שהרי גם הוא בכלל חבלות שגורמים נכסיו! ומשיבים כי יש הבדל: \u0003תנא ממונא\u0004 \u0005[שנה\u0006 התנא תשלומי \u0005ממון]\u0006 שמשלם המזיק בשיעור ממון שהזיק, \u0003וקתני קנסא\u0004 \u0005[ושנה\u0006 גם דיני \u0005קנסות],\u0006 שכן \"חצי נזק\" אינו נחשב כממון שחייב המזיק לשלם אלא כקנס שהטילה עליו התורה.","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006דבר \u0005זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003פלגא ניזקא קנסא\u0004 \u0005[\u0006תשלום \u0005חצי נזק קנס]\u0006 הוא, ואינו מחוייב מעיקר הדין, ואינו כתשלום חוב של ממון, ואינו אלא קנס להתרות בו שיזהר בעתיד, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003פלגא ניזקא ממונא\u0004 \u0005[\u0006תשלום \u0005חצי נזק ממון\u0006 הוא\u0005],\u0006 אלא שויתרה התורה למזיק על מחצית התשלום משום שאין לבעלים אחריות מלאה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שכן לשיטה זו נזק וחצי נזק שווים!","\u0003אלא\u0004 יש לדחות הסבר זה ולומר: \u0003איידי דקא בעי למיתנא\u0004 \u0005[מתוך שרצה לשנות\u0006 הלאה\u0005]\u0006 \u0003תשלומי כפל ותשלומי ארבעה וחמשה\u0004 שהם \u0003ממון\u0004"],["\u0003שאינו משתלם בראש הוא,\u0004 כלומר, שמשלם שלא בדיוק כפי שהזיק אלא יתר על כן, \u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 דין \u0003חצי נזק\u0004 שאף הוא \u0003ממון שאינו משתלם בראש הוא\u0004 שמשלם פחות ממה שהזיק, \u0003ואיידי דקא בעי למיתנא\u0004 \u0005[ומתוך שרצה לשנות]\u0006 \u0003חצי נזק, תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003נזק\u0004 שלם.","ושואלים: לגופה של ההלכה שיש צורך ב\u0003שלשה\u0004 דיינים, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? ומשיבים, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים],\u0006 נאמר: \u0003\"ונקרב בעל הבית אל האלהים\"\u0004 (שמות כב, ז): \"אלהים\" — דיין הוא, \u0003הרי כאן\u0004 דיין \u0003אחד,\u0004 ונאמר עוד: \u0003\"עד האלהים יבא דבר שניהם\"\u0004 (שמות כב, ח) — \u0003הרי כאן שנים, \"אשר ירשיען אלהים\"\u0004 (שמות כב, ח) — \u0003הרי כאן שלשה,\u0004 זוהי שיטת לימוד אחת ומ\u0003דברי ר' יאשיה\u0004 היא.","\u0003ר' יונתן אומר:\u0004 לא כך לומדים, כי \"אלהים\" \u0003ראשון\u0004 — \u0003תחילה נאמר\u0004 לגופו, שנדע שיש בכלל צורך בדיין, \u0003ואין דורשין\u0004 לצורך המספר את ה\u0003תחילות\u0004 (תוספות), \u0003אלא\u0004 כך נאמר: \u0003\"עד האלהים יבא דבר שניהם\"\u0004 — \u0003הרי כאן\u0004 דיין \u0003אחד, \"אשר ירשיען אלהים\"\u0004 — \u0003הרי כאן שנים, ו\u0004כיון ש\u0003אין\u0004 עושים \u0003בית דין שקול\u0004 (במספר זוגי) \u0003מוסיפין עליהן עוד אחד, הרי כאן שלשה.\u0004","ושואלים: \u0003נימא\u0004 \u0005[האם לומר]\u0006 כי \u0003ב\u0004שאלה אם \u0003דורשין תחילות קמיפלגי\u0004 \u0005[נחלקו]\u0006 ר' יאשיה ור' יונתן? \u0003דמר\u0004 \u0005[שחכם זה,\u0006 ר' יאשיה\u0005]\u0006 \u0003סבר:\u0004 \u0003דורשין תחילות\u0004 ומחשיבים כמניין גם מלה שנזכרה ראשונה, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' יונתן\u0005]\u0006 \u0003סבר:\u0004 \u0003אין דורשין תחילות!\u0004 ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אין דורשין תחילות\u0004 למניין, אלא כאן יש מקרה מיוחד. כי \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003ר' יאשיה: אם כן\u0004 שאין לימוד נוסף בא מן המלה, \u0003נימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"ונקרב בעל הבית אל השופט\", מאי\u0004 \u0005[מה]\u0006 משמע הביטוי המיוחד \u0003\"אל האלהים\"\u0004 — \u0003שמע מינה למניינא\u0004 \u0005[למד מכאן\u0006 כי \u0005ל\u0006צורך \u0005מנין]\u0006 נאמר, שאף מלה זו נמנית.","ושואלים: \u0003ור' יונתן,\u0004 מה אומר כנגד נימוק זה? ומשיבים: לדעתו \u0003לישנא דעלמא נקט\u0004 \u0005[לשון העולם,\u0006 הבריות, \u0005אחז]\u0006 הפסוק, \u0003כדאמרי אינשי\u0004 \u0005[כמו שאומרים הבריות]:\u0006 \u0003מאן דאית ליה דינא\u0004 \u0005[מי שיש לו דין]\u0006 — \u0003ליקרב לגבי דיינא\u0004 \u0005[שילך אצל הדיין],\u0006 ואין ללמוד מכאן הלכה מיוחדת.","ושואלים: \u0003ו\u0004כי \u0003ר' יאשיה לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את העקרון שיהיה \u0003בית דין נוטה,\u0004 כלומר, בית דין שאיננו שקול? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר בנו של ר' יוסי הגלילי אומר: מה תלמוד לומר \"לנטת אחרי רבים להטת\"\u0004 (שמות כג, ב) — מכאן נבין כי \u0003התורה אמרה: עשה לך בית דין נוטה\u0004 שתוכל תמיד להטות אחרי רבים!","ודוחים: אין זו דעת הכל, כי \u0003סבר לה\u0004 ר' יאשיה \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 ש\u0003אמר:\u0004 בית דין הגדול של \u0003שבעים\u0004 דיינים היה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003סנהדרי גדולה היתה של שבעים ואחד, ר' יהודה אומר:\u0004 של \u0003שבעים,\u0004 משמע שלדעת ר' יהודה אין חובה לעשות בית דין נוטה.","ומקשים: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את \u0003ר' יהודה\u0004 שאומר הלכה זו \u0003ב\u0004ענין \u0003סנהדרי גדולה, דכתיבי קראי\u0004 \u0005[שנאמרו כתובים]\u0006 מיוחדים ומהם הוא למד דבר זה, והרי זו כגזירת הכתוב שיהיו בה רק שבעים, אולם \u0003בשאר בי דינא\u0004 \u0005[בתי דין]\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 שיש בית דין שקול?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 ואין ר' יהודה מחלק בדבר, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003סמיכת זקנים ועריפת עגלה בשלשה,\u0004 אלו \u0003דברי ר' שמעון. ר' יהודה אומר: בחמשה.\u0004","\u0003ואמרינן\u0004 \u0005[ואמרנו]\u0006 בביאור הענין הזה: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 — שנאמר בכתוב \"וסמכו זקני העדה את ידיהם על ראש הפר לפני ה' \" (ויקרא ד, טו), ודרשו: \u0003\"וסמכו\"\u0004 הוא לשון רבים — הרי כאן לפחות \u0003שנים, \"זקני\"\u0004 אף הוא \u0003שנים\u0004 — הרי ארבעה, \u0003ואין בית דין שקול, מוסיפין עליהן עוד אחד\u0004 — \u0003הרי כאן חמשה.\u0004 הרי שר' יהודה עצמו משתמש בכלל שאין בית דין שקול!","ודוחים: אמנם ר' יהודה סבור שאין בית דין שקול, אלא שיטתו של \u0003ר' יאשיה עדיפא\u0004 \u0005[עדיפה,\u0006 קיצונית\u0005]\u0006 \u0003מ\u0004שיטתו של \u0003ר' יהודה.\u0004 ש\u0003אילו ר' יהודה בסנהדרי גדולה הוא דלית ליה\u0004 \u0005[שאין לו],\u0006 שאינו מחייב שיהא בית דין נוטה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בשאר בי דינא אית ליה\u0004 \u0005[בתי דינים יש לו]\u0006 עקרון זה. \u0003ור' יאשיה בשאר בי דינא נמי לית ליה\u0004 \u0005[גם כן אין לו,\u0006 אינו מקבל\u0005]\u0006 עקרון זה. שואלים: \u0003ואלא האי\u0004 \u0005[\u0006מקרא \u0005זה]\u0006 \u0003\"לנטת\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]\u0006 וכיצד הוא מפרשו? ומשיבים: ר' יאשיה \u0003מוקים לה\u0004 \u0005[מעמיד אותה],\u0006 מסביר את הכתוב הזה, \u0003בדיני נפשות,\u0004 שבהם יש צורך בבית דין נוטה,","\u0003אבל בדיני ממונות\u0004 — \u0003לא.\u0004 ושואלים: \u0003אלא הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 אם נחלקו הדיינים, \u0003שנים אומרים \"זכאי\" ואחד אומר \"חייב\"\u0004 — הרי הוא \u0003זכאי, שנים אומרים \"חייב\" ואחד אומר \"זכאי\"\u0004 — \u0003חייב. נימא\u0004 \u0005[האם נאמר]\u0006 שמשנה זו ש\u0003לא כ\u0004דעת \u0003ר' יאשיה,\u0004 שלכאורה ר' יאשיה אינו מקבל הכרעת הרוב בדיני ממונות, ויהא צורך בהסכמה פה אחד של כל הדיינים!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שדבר זה הוא כשיטת \u0003ר' יאשיה\u0004 אלא \u0003מייתי לה\u0004 \u0005[מביא\u0006 הוא \u0005אותה,\u0006 לומד הוא\u0005]\u0006 את הדין הזה שיש לקבל דעת הרוב \u0003בקל וחומר מדיני נפשות: ומה דיני נפשות דחמירי\u0004 \u0005[ש\u0006הם \u0005חמורים],\u0006 \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]:\u0006 \u0003זיל בתר רובא\u0004 \u0005[לך אחר הרוב]\u0006 ואינך צריך הסכמת כל הדיינים כולם, \u0003דיני ממונות\u0004 שהם קלים יותר, \u0003לא כל שכן\u0004 שהכרעת הרוב מספקת?!","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003דיני ממונות\u0004 נידונים \u0003בשלשה\u0004 דיינים, \u0003רבי אומר: בחמשה\u0004 דיינים, \u0003כדי שיגמר הדין בשלשה.\u0004 ושואלים: \u0003אטו בתלתא מי\u0004 \u0005[וכי בשלושה האם]\u0006 \u0003לא גמר דינא בתרי\u0004 \u0005[בשנים]\u0006 שהם רוב? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: \u0003מפני שגמר דין בשלשה,\u0004 כלומר, לדעת רבי, דרוש שמספר רוב הדיינים שיגמרו ויחליטו לצד מסויים יהא ראוי להיות בית דין בפני עצמו. \u0003אלמא קסבר\u0004 \u0005[מכאן שסבר]\u0006 רבי: \u0003תלתא כי כתיבי\u0004 \u0005[שלושה\u0006 דיינים אלה \u0005כאשר כתובים\u0006 במקרא\u0005]\u0006 — \u0003בגמר דינא כתיבי\u0004 \u0005[ב\u0006ענין \u0005גמר הדין\u0006 הם \u0005כתובים],\u0006 כלומר, שבשעת ההכרעה צריכה להיות הכרעה על פי שלושה דיינים, ורוב כזה קיים רק כשיש חמישה דיינים המתחילים בדיון.","\u0003מגדף בה\u0004 \u0005[מקשה על כך]\u0006 בלשון קשה \u0003ר' אבהו: אלא מעתה,\u0004 אם זו היא הסברה שבדבר, אם כן, \u0003תהא סנהדרי גדולה צריכה מאה וארבעים ואחד\u0004 חברים, \u0003כדי שיגמר\u0004 בה \u0003הדין בשבעים ואחד! ו\u0004כן \u0003תהא סנהדרי קטנה צריכה ארבעים וחמשה\u0004 איש \u0003כדי שיגמר הדין בשלשה ועשרים,\u0004 והרי הדבר בניגוד לכתובים!","\u0003אלא \"אספה לי שבעים איש\u0004 מזקני ישראל\u0003\"\u0004 (במדבר יא, טז) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 ודיו בכך, ונלמד: \u0003משעת אסיפה\u0004 צריכים להיות \u0003שבעים.\u0004 וכן \u0003\"ושפטו העדה\" \"והצילו העדה\"\u0004 הנאמר בבית דין הדן בדיני נפשות, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003משעת שפיטת העדה\u0004 צריכים להיות עשרים ושלושה, ולא בשעת גמר דין, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 בבית דין הדן דיני ממונות, \u0003\"ונקרב בעל הבית אל האלהים\"\u0004 (שמות כב, ז), משמעו — \u0003משעת קריבה\u0004 לדון צריכים \u0003שלשה\u0004 ולא בגמר דין.","\u0003אלא\u0004 יש לדחות את ההסבר הקודם, ולומר: \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003רבי:\u0004 נאמר באותה פרשה \u0003\"אשר ירשיען אלהים\"\u0004 (שמות כב, ז ח) בלשון רבים — הרי \u0003תרי\u0004 \u0005[שנים],\u0006 \u0003נאמר \"אלהים\" למטה ונאמר \"אלהים\" למעלה\u0004 (שמות כב, ז ח), \u0003מה למטה\u0004 הכוונה היא ל\u0003שנים, אף למעלה\u0004 הכוונה היא ל\u0003שנים\u0004 — הרי ארבעה דיינים, \u0003ואין בית דין שקול\u0004 — \u0003מוסיפין עליהם עוד אחד, הרי כאן חמשה.\u0004"],["\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אומרים שאין מכאן ראיה גמורה כי \u0003\"ירשיען\" כתיב\u0004 \u0005[נאמר],\u0006 שאמנם קוראים אנו \"ירשיעון\" בלשון רבים, אבל הכתיב הוא \"ירשיען\" בלשון יחיד, ואין למדים מכאן אלא דיין אחד.","המחלוקת בין רבי וחכמים הוסברה איפוא כמבוססת על השאלה האם יש לסמוך על דרך הכתיבה או על הקריאה המקובלת של מילים בתורה. בענין זה \u0003אמר ר' יצחק בר יוסי אמר ר' יוחנן: רבי, ור' יהודה בן רועץ, ובית שמאי, ור' שמעון, ור' עקיבא, כולהו סבירא להו\u0004 \u0005[כולם סבורים הם]:\u0006 \u0003יש אם למקרא.\u0004 כלומר, יש בסיס ויסוד חזק לאופן שבו קוראים את התורה, וצורת המלה כפי שהיא נקראת חשובה יותר מאשר נוסח הכתיב.","ומפרטים: דברי \u0003רבי\u0004 בענין זה — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 שהרי הוא דורש \"ירשיען\" בלשון רבים דווקא — \"ירשיעון\".","\u0003ור' יהודה בן רועץ, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שאלו תלמידים את ר' יהודה בן רועץ:\u0004 נאמר \"ואם נקבה תלד וטמאה שבעים כנדתה ושישים יום וששת ימים תשב על דמי טהרה\" (ויקרא יב, ה) \u0003אקרא אני \"שבעים\"\u0004 ולא \"שבעים\", \u0003יכול תהא יולדת נקבה טמאה שבעים\u0004 יום!","\u0003אמר להן:\u0004 אפשר להוכיח שאין הדבר כן, \u0003טימא וטיהר ב\u0004יולדת \u0003זכר\u0004 שמיד אחרי הלידה היא טמאה ואחר כך באים ימי \"דמי טהרה\", \u0003וטימא וטיהר בנקבה. מה כשטיהר בזכר\u0004 שיש לה להמתין שלושים ושלושה יום — טיהר \u0003בנקבה כפלים\u0004 (שישים ושישה), \u0003אף כשטימא בזכר\u0004 ואמר \"וטמאה שבעת ימים כימי נדת דוותה תטמא\" (ויקרא יב, ב) \u0003בנקבה\u0004 הזמן הוא \u0003כפלים,\u0004 ואם כן יש לקרוא כאן \"שבעים\".","\u0003לאחר שיצאו\u0004 ממנו \u0003יצא ומחזיר אחריהם\u0004 ובקש מהם שישובו, ו\u0003אמר להן: אי\u0004 (אין) \u0003אתם זקוקים לכך\u0004 לראיה זו שבאה על ידי ההשוואה, אלא \u0003\"שבועיים\" קרינן\u0004 \u0005[קוראים אנו]\u0006 במסורת המקובלת, \u0003ויש אם למקרא\u0004 ואין צורך בראיות אחרות.","\u0003בית שמאי\u0004 מנין שסבורים שיש אם למקרא — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003בית שמאי אומרים: כל\u0004 מיני דם הקרבנות \u0003הניתנין על מזבח החיצון, שנתנן במתנה אחת\u0004 בזריקה אחת בלבד, אף שמעיקר הדין צריכים לתת את דמם בשתי נתינות או יותר — \u0003כיפר\u0004 ויצא ידי חובת הקרבן. \u0003שנאמר:\u0004 \"ועשית עולותיך... \u0003ודם זבחיך ישפך\u0004 על מזבח ה' אלהיך\" (דברים יב, כז), שאף לקרבן עולה, שצריך נתינות אחדות, די בשפיכת דם אחת לצאת בדיעבד ידי חובה. \u0003ו\u0004אילו \u0003ב\u0004קרבן \u0003חטאת\u0004 צריך שיתן לפחות \u0003שתי מתנות. ובית הלל אומרים: אף בחטאת,\u0004 בדיעבד, אם \u0003נתנן במתנה אחת\u0004 — \u0003כיפר.\u0004","\u0003ואמר רב הונא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003בית שמאי\u0004 — שנאמר בחטאת שלוקח מן הדם באצבעו \"ונתן על קרנת מזבח העלה\", וענין זה נזכר שלוש פעמים, הרי מצרפים את המקרים שמוזכר בהם \u0003\"קרנת\" \"קרנת\" \"קרנת\"\u0004 (ויקרא ד,כה,ל,לד), ולפי הכלל שמיעוט רבים שנים, \u0003הרי כאן שש\u0004 קרנות. \u0003ארבע\u0004 מהן נמנו \u0003למצוה\u0004 שלכתחילה עליו לתת דם על ארבע קרנות המזבח, \u0003ושתים\u0004 אחרות נמנו \u0003לעכב,\u0004 שאם לא נתן על שתי קרנות לפחות — לא יצא.","\u0003ובית הלל אומרים\u0004 כי יש להבין את הדברים כפי הכתיב. נאמר \u0003\"קרנות\"\u0004 פעם אחת מלא, ונאמר פעמיים \u0003\"קרנת\" \"קרנת\"\u0004 חסר, ולפי הכתיב \"קרנת\" משמעו קרן אחת בלבד — \u0003הרי כאן\u0004 בסך הכל \u0003ארבע.\u0004 ונאמר כי נותנים את דם החטאת על ארבע קרנות — \u0003שלש\u0004 מהן \u0003למצוה\u0004 בלבד, \u0003ואחת לעכב.\u0004","ושואלים: לפי הסבר זה לשיטת בית הלל \u0003ואימא כולהו\u0004 \u0005[ואמור שכולן]\u0006 \u0003למצוה,\u0004 וגם אם לא נתן כלל — כיפר. ודוחים: \u0003כפרה בכדי\u0004 \u0005[לריק,\u0006 בלא דבר\u0005]\u0006 בלא נתינת דם כלל — \u0003לא אשכחן\u0004 \u0005[מצאנו]\u0006 בכתובים.","וכן \u0003ר' שמעון\u0004 סבר שיש אם למקרא, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 שנחלקו חכמים בענין מספר הדפנות ההכרחי בסוכה של מצוה, יש מי שאומר ש\u0003שתים\u0004 צריכות להיות \u0003כהלכתן,\u0004 כלומר, דפנות בשיעור הראוי לסוכה, \u0003ושלישית אפילו\u0004 רחבה רק \u0003טפח\u0004 אחד. \u0003ר' שמעון אומר\u0004 שצריך \u0003שלש\u0004 דפנות גמורות \u0003כהלכתן, ורביעית אפילו טפח.\u0004 ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005הם נחלקו]?\u0006 ומסבירים: \u0003רבנן סברי\u0004 \u0005[סבורים]\u0006 ש\u0003יש אם למסורת\u0004 שדורשים מצורת המילים בכתיבתן, \u0003ור' שמעון סבר\u0004 ש\u0003יש אם למקרא.\u0004 כיצד?","\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003יש אם למסורת,\u0004 ובענין סוכות נאמר \u0003\"בסכת\" \"בסכת\" \"בסכות\"\u0004 (ויקרא כג, מב–מג) \u0003הרי כאן ארבע,\u0004 כי \"בסכת\" נדרש בלשון יחיד, ו\"בסכות\" הוא לשון רבים, ומיעוט רבים שניים. \u0003דל חד קרא לגופיה\u0004 \u0005[הסר מקרא אחד לגופו],\u0006 כלומר, ללמדנו לעצם החובה לשבת בסוכה — \u0003פשו להו תלת\u0004 \u0005[נשארו להם\u0006 איפוא \u0005שלוש],\u0006 כלומר, שלושה מקראות נוספים שמהם אנו לומדים ברמז לענין מנין הדפנות בסוכה, שצריך בה שלוש דפנות. \u0003אתאי הלכתא\u0004 \u0005[באה ההלכה\u0006 המקובלת בידינו\u0005]\u0006 שדופן אחת של הסוכה יכולה להיות בלתי שלמה \u0003גרעתא\u0004 \u0005[גרעה]\u0006 את הדופן ה\u0003שלישית\u0004 של הסוכה, \u0003ואוקימתא\u0004 \u0005[והעמידה אותה]\u0006 על \u0003טפח\u0004 בלבד.","ולכן: שתים כהלכתן והשלישית אפילו טפח. \u0003ור' שמעון סבר\u0004 שמבינים את הכתובים כדרך קריאתם והקרי הוא \u0003\"בסכת\" \"בסכת\" \"בסכות\"\u0004 כל אחד בלשון רבים, \u0003הרי כאן\u0004 לפחות \u0003שש, דל חד קרא לגופיה\u0004 \u0005[הסר מקרא אחד לגופו]\u0006 שיש צורך בסוכה כלל, ויש איפוא רק שני מקראות שנאמר בהם \"בסכות\", \u0003פשו להו\u0004 \u0005[נשארו להן]\u0006 \u0003ארבע\u0004 לצורך הדרשה. \u0003אתאי הלכתא גרעתא\u0004 \u0005[באה ההלכה\u0006 ו\u0005גרעה]\u0006 את הדופן ה\u0003רביעית ואוקמיה\u0004 \u0005[והעמידה אותה]\u0006 על \u0003טפח\u0004 וזהו המקור לשיטתו.","\u0003ר' עקיבא\u0004 סבור שיש אם למקרא, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' עקיבא אומר:\u0004 יודעים אנו שרביעית דם שיצאה ממת אחד מטמאה באהל, ורצה ר' עקיבא להוכיח כי אם יצא דם בשיעור זה מכמה אנשים יחד — מטמא, ו\u0003מניין לרביעית דם שיצאה משני מתים\u0004 יחד \u0003ש\u0004אף היא \u0003מטמא באהל?\u0004 — \u0003שנאמר: \"\u0004ו\u0003על כל נפשת מת לא יבא\"\u0004 (ויקרא, כא יא) ובלשון המקרא \"הדם הוא הנפש\", ומן הצורה \"נפשות\" ברבים, נלמד שגם אם היו \u0003שתי נפשות ושיעור אחד\u0004 הרי זה מטמא. \u0003ורבנן\u0004 אומרים: \u0003\"נפשת\" כתיב\u0004 ואפשר להבינו בלשון יחיד. ולמדים מכאן לטומאת דם היוצא ממת אחד בלבד.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על דרך סברה זו כולה \u0003רב אחא בר יעקב: מי איכא דלית ליה\u0004 \u0005[האם יש\u0006 חכם \u0005שאין לו,\u0006 שאינו מקבל את ההנחה\u0005]\u0006 ש\u0003יש אם למקרא,\u0004 וסבור שאין סומכים על הקריאה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \u0003\"\u0004לא תבשל גדי \u0003בחלב אמו\"\u0004 (שמות כג, יט) \u0003יכול\u0004 הכוונה \u0003בחלב,\u0004 ויהא האיסור בבישול לא בחלב כי אם על חלב?"],["\u0003אמרת\u0004 \u0005[אומר אתה]\u0006 כתשובה לכך: \u0003יש אם למקרא,\u0004 והקריאה המקובלת בידינו היא חלב. משמע שאין מערער שסומכים על דרך הקריאה המקובלת בידינו.","\u0003אלא\u0004 יש לדחות כל מה שאמרנו, ולומר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003יש אם\u0004 \u0003למקרא.\u0004 ואם כן, כל המחלוקת שהבאנו ופירשנו עלינו לחזור ולפרש באופן אחר. \u0003ורבי ורבנן\u0004 \u0005[וחכמים]\u0006 שנחלקו בענין מספר הדיינים, \u0003בהא קמיפלגי\u0004 \u0005[ב\u0006ענין \u0005זה הם נחלקו];\u0006 \u0003רבי סבר\u0004 שמה שנאמר \u0003\"ירשיען אלהים\"\u0004 כוונתו לדיינים \u0003אחריני\u0004 \u0005[אחרים],\u0006 נוספים לאלה המנויים קודם ולכן עליהם ביחד להיות חמישה, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי \u0003\"ירשיען\"\u0004 כוונתו — \u0003דהאיך והאי\u0004 \u0005[של אלה ואלה],\u0006 כלומר, אותם דיינים הנזכרים כבר, שהם שלושה.","\u0003ור' יהודה בן רועץ\u0004 המדבר מענין מספר ימי טומאה ללידת נקבה, אין להבין מתוך הדברים שרק הוא לבדו סבור שיש אם למקרא אלא \u0003לא פליגי רבנן עליה\u0004 \u0005[נחלקו חכמים עליו],\u0006 והכל מקבלים את שיטתו.","ו\u0003בית הלל,\u0004 הסבורים שיוצאים אפילו בחטאת במתנת דמים אחת, טעם אחר להם בדבר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר בחטאת \u0003\"וכפר\" \"וכפר\" \"וכפר\"\u0004 (ויקרא ד, כו. ויקרא ד, לא. ויקרא ד, לה) שלוש פעמים והיה צורך בחזרה זו \u0003מפני הדין.\u0004 כלומר, משום שהיתה אפשרות לעשות השוואה בדרך ההגיון והסברה (\"דין\") ולהגיע למסקנה אחרת. כיצד?","\u0003והלא דין הוא: נאמר\u0004 לשון \u0003\"דמים\" למטה\u0004 בדין חטאת העוף (\"והנשאר בדם ימצה אל יסוד המזבח\". ויקרא ה, ט), \u0003ונאמר\u0004 לשון \u0003\"דמים\" למעלה\u0004 בדין חטאת הבהמה (\"ולקח הכהן המשיח מדם הפר\". ויקרא ד, ועוד). \u0003מה דמים האמורים למטה\u0004 בחטאת העוף כ\u0003שנתנן במתנה אחת כיפר\u0004 (שהרי נאמרה בה רק נתינת דם אחת), \u0003אף דמים האמורים למעלה\u0004 כ\u0003שנתנן במתנה אחת\u0004 בדיעבד — \u0003כיפר.\u0004","\u0003או כלך\u0004 \u0005[לך]\u0006 \u0003לדרך זו\u0004 ותציע הצעה אחרת: כי \u0003נאמר \"דמים\" בחוץ\u0004 בקרבן חטאת של כל אדם שהוא מוקרב על מזבח החיצון שבעזרה, \u0003ונאמר \"דמים\" בפנים\u0004 על חטאות הקהל והכהן הגדול שזורקים מדמן על מזבח הקטורת שבפנים בהיכל. \u0003מה דמים האמורים בפנים,\u0004 אם \u0003חיסר אחת ממתנות\u0004 — \u0003לא עשה ולא כלום\u0004 ואין הקרבן עולה לו, \u0003אף דמים האמורים בחוץ\u0004 אם \u0003חיסר אחת ממתנות\u0004 — \u0003לא עשה כלום.\u0004","ומעתה נדון: \u0003נראה למי דומה\u0004 יותר דין חטאות החיצוניות ולמה צריך להשוות? ואפשר לטעון: \u0003דנין חוץ מחוץ,\u0004 קרבן חטאת המוקרב על מזבח החיצון מחטאת העוף המוקרב אף הוא על מזבח החיצון, \u0003ואין דנין חוץ מפנים.\u0004","\u0003או כלך לדרך זו\u0004 שמא אפשר לטעון להיפך: \u0003דנין\u0004 דבר שהוא \u0003חטאת, ו\u0004שלכתחילה צריך לזרוק את דמו על \u0003ארבע קרנות\u0004 המזבח, \u0003מחטאת\u0004 הפנימית שאף היא קרויה חטאת \u0003ו\u0004אף היא נזרקת על \u0003ארבע קרנות\u0004 המזבח, \u0003ואל יוכיח זה,\u0004 קרבן העוף, \u0003שאין\u0004 הוא \u0003חטאת וארבע קרנות\u0004 יחד, אלא קרבן המוקרב בצורה שונה לגמרי.","וכיון שאין להכריע על ידי הסברה לבד, \u0003תלמוד לומר: \"וכפר\" \"וכפר\" \"וכפר\"\u0004 — \u0003מפני הדין,\u0004 מפני סברה זו. וכך נאמר: \u0003\"כיפר\"\u0004 כוונתו מכל מקום — \u0003אף על פי שלא נתן אלא שלשה\u0004 מתנות, \u0003\"כיפר\"\u0004 — \u0003אף על פי שלא נתן אלא שתים, \"כיפר\"\u0004 — \u0003אף על פי שלא נתן אלא אחת.\u0004 ודרשה זו היא המקור לשיטת בית הלל.","\u0003ור' שמעון ורבנן\u0004 שנחלקו בענין סוכה \u0003בהא פליגי\u0004 \u0005[ב\u0006נושא \u0005זה נחלקו],\u0006 ש\u0003ר' שמעון סבר\u0004 \u0005[סבור]\u0006 ש\u0003סככא לא בעי קרא\u0004 \u0005[\u0006חובת \u0005הסכך\u0006 לסוכה \u0005אינה צריכה מקרא\u0006 מיוחד\u0005]\u0006 ללמד עליו שהוא נדרש, שהרי דבר זה מובן מעצם המלה, ולכן נשארו שתי פעמים \"בסוכות\" מלא, ולמדים מכאן לארבע דפנות הסוכה, וההלכה ממעטת דופן אחת עד כדי טפח. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 שאף \u0003סככא בעי קרא\u0004 \u0005[\u0006חובת \u0005הסכך צריך מקרא\u0006 מיוחד\u0005],\u0006 ולכן סבורים חכמים שמארבע הפעמים שנזכרו סוכות (ומהם למדו לדפנות הסוכה) יש ליטול אחת לענין הסכך, הרי נשארו רק שלוש דפנות.","\u0003ור' עקיבא ורבנן\u0004 \u0005[וחכמים]\u0006 המדברים מענין טומאת רביעית דם משני מתים, \u0003בהא פליגי\u0004 \u0005[ב\u0006דבר \u0005זה נחלקו],\u0006 ש\u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 ש\u0003\"נפשת\"\u0004 — \u0003תרתי משמע\u0004 \u0005[שתים משמעו],\u0006 ולכן רביעית דם הבאה משני מתים אף היא מטמאה, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 \u0003\"נפשת\"\u0004 — \u0003דעלמא משמע\u0004 \u0005[בכלל משמעו],\u0006 שמדובר בדין כללי ולכן נזכר בלשון רבים, ואין לדייק מכאן לגבי שתי נפשות, ובשל כך יכול איפוא להתפרש שהכל מודים שיש אם למקרא.","ושואלים: \u0003ודכולי עלמא\u0004 \u0005[ו\u0006האם באמת \u0005לדעת הכל]\u0006 \u0003יש אם למקרא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 נאמר בענין תפילין \"והיו לטוטפות בין עיניך\" (שמות יג, טז), ונזכר בתורה שלוש פעמים: \u0003\"\u0004ו\u0003לטוטפות\"\u0004 (שמות יג, טז), \u0003\"לטוטפת\"\u0004 (דברים ו, ח), \u0003\"לטוטפת\"\u0004 (דברים יא, יח), \"טוטפת\" הוא לשון יחיד, \"טוטפות\" לשון רבים — \u0003הרי כאן ארבע\u0004 טוטפות, ומכאן למדנו שמספר הבתים (הטוטפות) בתפילין של ראש יהיה ארבעה, אלו \u0003דברי ר' ישמעאל.\u0004","\u0003ר' עקיבא אומר: אינו צריך\u0004 לראיה זו אלא המלה \"טוטפת\" עצמה משמעה ארבע. כיצד? \u0003\"טט\" ב\u0004לשון \u0003כתפי\u0004 היא \u0003שתים,\u0004 המלה \u0003\"פת\" ב\u0004לשון בני \u0003אפריקי\u0004 היא \u0003שתים\u0004 — הרי \"טוטפות\" משמעה ארבע. וברור מדברי ר' ישמעאל שהוא למד דווקא ממסורת הכתיבה ולא מן הקרי.","\u0003אלא\u0004 עלינו לדחות שוב את מה שאמרנו, ולחזור להסבר הראשון: \u0003לעולם\u0004 יש לך לפרש כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 חכמים אם סומכים על הכתיבה או על הקריאה. \u0003והני מילי\u0004 \u0005[ודברים אלה],\u0006 מה שהיה קושי ללא פתרון קודם, ממה שלא מצאנו שנחלקו בענין גדי בחלב אמו, יש לומר: \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — הרי זה \u0003היכא דשני קרא\u0004 \u0005[במקום ששונה הקריאה]\u0006 \u0003מ\u0004ה\u0003מסורת\u0004 של הכתיב, שלפי הקרי היה צורך לכתוב את המלה בצורה אחרת, ואז נחלקו מה היא הצורה העיקרית. \u0003אבל האי\u0004 \u0005[זה]\u0006 \u0003\"חלב\" ו\"חלב\" דכי הדדי נינהו\u0004 \u0005[שזה כמו זה הם]\u0006 ואין כל אפשרות לכתוב אחרת, \u0003יש\u0004 לכל הדעות \u0003אם למקרא.\u0004","על הסבר זה מקשים: \u0003והרי\u0004 המילים \u0003\"יראה\" \"יראה\" דכי הדדי נינהו\u0004 \u0005[שהם זו כמו זו\u0006 בכתיבתם\u0005],\u0006 \u0003ו\u0004בכל זאת \u0003פליגי\u0004 \u0005[נחלקו]\u0006 חכמים על מה יש לסמוך יותר. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יוחנן בן דהבאי אומר משום\u0004 (בשם) \u0003ר' יהודה בן תימא: הסומא\u0004 (עיוור) \u0003באחת מעיניו פטור מן הראיה,\u0004 כלומר, פטור מלעלות לרגל, \u0003שנאמר:\u0004 \"שלוש פעמים בשנה יראה כל זכורך אל פני האדון ה' \" (שמות כג, יז), וניתן הדבר להיקרא \u0003\"יראה\"\u0004 ונקרא \u0003\"יראה\"\u0004 והוא דורש: \u0003כדרך שבא לראות כך בא ליראות\u0004 לפני ה'. \u0003מה לראות\u0004 כוונתו ראיה שלמה \u0003בשתי עיניו, אף ליראות בשתי עיניו,\u0004 ומי שאין שתי עיניו רואות איננו בין המחוייבים לעלות לרגל. משמע שאף כשאין הבדל באותיות יש הדורשים את המילים שלא כדרך קריאתן המקובלת!","\u0003אלא אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא:\u0004 בדין גדי בחלב אמו שהכל מסכימים לו, יש טעם אחר להוכיח שמדובר בחלב ולא בחלב, כי \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"לא תבשל גדי\"\u0004 (שמות כג, יט), משמע — \u0003דרך בישול אסרה תורה,\u0004 ובישול יתכן רק בחלב נוזל ולא בדבר המוצק כחלב.","ושוב חוזרים אנו לנושא העיקרי. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003דיני ממונות בשלשה\u0004 דיינים"],["\u0003ואם היה\u0004 הדיין \u0003מומחה לרבים\u0004 הריהו \u0003דן אפילו\u0004 בהיותו \u0003יחידי.\u0004 מסופר, \u0003אמר רב נחמן: כגון אנא\u0004 \u0005[אני]\u0006 אדם כמוני \u0003דן דיני ממונות ביחידי. וכן אמר ר' חייא: כגון אנא\u0004 \u0005[אני]\u0006 \u0003דן דיני ממונות ביחידי.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 מה פירוש \u0003\"כגון אנא\"\u0004 \u0005[אני],\u0006 בדברי חכמים אלה? האם משמעו: \u0003דגמירנא וסבירנא ונקיטנא רשותא\u0004 \u0005[שלמדתי\u0006 וקיבלתי מרבותי \u0005ו\u0006הגעתי לדרגה \u0005להבין מדעתי וקיבלתי רשות]\u0006 מראש הגולה שהוא הרשות המוסמכת לכך, זה הרשאי לדון ביחיד, \u0003אבל\u0004 מי ש\u0003לא נקיט רשותא\u0004 \u0005[קיבל רשות]\u0006 מראש הגולה — \u0003דיניה\u0004 \u0005[דינו]\u0006 ביחיד \u0003לא דינא\u0004 \u0005[דין].\u0006 \u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא נקיט רשותא\u0004 \u0005[קיבל רשות]\u0006 — \u0003דיניה דינא\u0004 \u0005[דינו דין]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ש\u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן דן דינא\u0004 \u0005[דין]\u0006 מסויים \u0003וטעה\u0004 בו, \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב יוסף\u0004 לשאול מה עליו לעשות. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם\u0004 בעלי הדין \u0003קיבלוך עלייהו\u0004 \u0005[עליהם],\u0006 והסכימו שניהם שאתה לבדך תדון אותם — \u0003לא תשלם,\u0004 אין אתה חייב לשלם, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 קיבלוך אלא כפאום לידון בפניך — \u0003זיל שלים\u0004 \u0005[לך ושלם].\u0006 על כל פנים \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שגם \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא נקיט רשותא\u0004 \u0005[קיבל רשות\u0006 מראש הגולה\u0005]\u0006 — \u0003דיניה דינא\u0004 \u0005[דינו דין],\u0006 שכן גם במקרה שעליו לחזור ולשלם אומרים אנו שדינו דין, ואין אנו אומרים שבטלה הכרעתו מעיקרה ויחזירו המתדיינים את הכסף וידונו שוב בפני בית דין אחר, הרי שיחיד מלומד ומומחה רשאי לדון ביחיד. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא הדין.","\u0003אמר רב: האי מאן דבעי למידן דינא\u0004 \u0003ואי טעה מיבעי למיפטרא\u0004 \u0005[מי שרוצה לדון דין, ואם יטעה רוצה\u0006 הוא \u0005להיפטר]\u0006 ולא יצטרך לשלם למי שחייבו בטעות — \u0003לישקול רשותא מבי ריש גלותא\u0004 \u0005[שיקבל רשות\u0006 לדון \u0005מבית ראש הגולה].\u0006 \u0003וכן אמר שמואל:\u0004 במקרה כזה \u0003לשקול רשותא מבי ריש גלותא\u0004 \u0005[שיקבל רשות מבית ראש הגולה],\u0006 שכיון שקיבל רשות לדון, הרי גם הכרעה מוטעית שלו אין לבטלה, וכאילו לא טעה. כיון שנתבררה החשיבות שיש בקבלת רשות מראש הגולה, דנים בדבר היקפה של סמכותו.","\u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא, כי \u0003מהכא להכא\u0004 \u0005[מכאן לכאן],\u0006 כלומר, רשות מראש הגולה שבבבל לדון בבבל, \u0003ומהתם להתם\u0004 \u0005[ומשם לשם],\u0006 רשות מהנשיא שבארץ ישראל עבור בני ארץ ישראל — \u0003מהני\u0004 \u0005[מועילה]\u0006 רשות זו, \u0003ומהכא להתם\u0004 \u0005[ומכאן לשם]\u0006 — \u0003נמי מהני\u0004 \u0005[גם כן מועילה],\u0006 משום שסמכות ראש הגולה גדולה משל הנשיא. \u0003דהכא\u0004 \u0005[שכאן]\u0006 בבבל הוא \u0003שבט\u0004 מושלים, שיש בידו שלטון ממשי, \u0003והתם\u0004 \u0005[ושם]\u0006 הנשיא בארץ ישראל הוא \u0003מחוקק\u0004 בלבד.","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 על הכתוב: \"לא יסור שבט מיהודה ומחוקק מבין רגליו עד כי יבא שילה\" (בראשית מט, י), ופירושו שאף בזמן הגלות לפני ביאת המשיח (\"שילה\") \u0003\"לא יסור שבט מיהודה\"\u0004 — \u0003אלו ראשי גליות שבבבל שרודין את ישראל בשבט\u0004 וכח בידם. \u0003\"ומחקק מבין רגליו\"\u0004 — \u0003אלו בני בניו של הלל\u0004 הזקן שהם הנשיאים בארץ \u0003שמלמדין תורה ברבים,\u0004 אבל אין להם סמכות רבה כל כך מטעם השלטונות לשפוט את העם.","ואולם השאלה היא: \u0003מהתם להכא מאי\u0004 \u0005[משם לכאן מה\u0006 הדין\u0005],\u0006 האם מתן רשות בארץ ישראל מועיל גם לגבי בבל? ומשיבים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003רבה בר חנה דן דינא\u0004 \u0005[דין\u0006 בבבל\u0005]\u0006 \u0003וטעה, אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' חייא\u0004 לשאול מה יעשה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003קיבלוך עלייהו\u0004 \u0005[עליהם]\u0006 בעלי הדין — \u0003לא תשלם,\u0004 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003זיל שלים\u0004 \u0005[לך ושלם].\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה בר חנה רשותא הוה נקיט\u0004 \u0005[רשות קבל]\u0006 מהנשיא שבארץ ישראל כאשר יבואר, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003מהתם להכא\u0004 \u0005[משם,\u0006 מארץ ישראל, \u0005לכאן\u0006 לבבל\u0005]\u0006 — \u0003לא מהני\u0004 \u0005[אינה מועילה]\u0006 נתינת הרשות. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ותוהים: \u0003ו\u0004כי \u0003לא מהני\u0004 \u0005[מועילה]\u0006 רשות זו? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה בר רב הונא כי הוה מינצי בהדי דבי ריש גלותא\u0004 \u0005[כאשר היה רב עם\u0006 אנשי \u0005בית ראש הגולה]\u0006 \u0003אמר: לאו מינייכו נקיטנא רשותא\u0004 \u0005[לא מכם קבלתי רשות\u0006 לדון\u0005],\u0006 \u0003נקיטנא רשותא מאבא מרי\u0004 \u0005[קבלתי רשות מאבי מורי,\u0006 רב הונא\u0005],\u0006 \u0003ואבא מרי\u0004 \u0005[ואבי מורי]\u0006 קבל \u0003מרב, ורב מר' חייא, ור' חייא מרבי\u0004 יהודה הנשיא שבארץ ישראל. משמע שקבלת רשות מארץ ישראל מועילה לבבל! ודוחים: מכאן אין ראיה, \u0003במילתא דעלמא\u0004 \u0005[בדברים בלבד]\u0006 \u0003הוא דאוקים להו\u0004 \u0005[שהעמיד אותם],\u0006 שאמר זאת כאיום בלבד, ואין להביא מכאן ראיה.","ושואלים: \u0003וכי מאחר דלא מהני\u0004 \u0005[שאין\u0006 קבלת הרשות בארץ \u0005מועילה]\u0006 לבבל, \u0003רבה בר חנה רשותא דנקט למה לי\u0004 \u0005[אותה רשות שקיבל למה לו],\u0006 ומה תועלת היתה לו בקבלת רשות עם יציאתו לבבל? ומשיבים: רשות זו מועילה \u0003לעיירות העומדים על הגבולין\u0004 שאינן לגמרי בתחום השיפוט של בבל, ורשות מארץ ישראל יפה כוחה לגביהם.","ושואלים: \u0003מאי רשותא\u0004 \u0005[מה רשות\u0006 זו\u0005]\u0006 שרמזנו לה בדברינו? מסופר: \u0003כי הוה נחית\u0004 \u0005[כאשר ירד]\u0006 \u0003רבה בר חנה לבבל, אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא לרבי: בן אחי יורד לבבל,\u0004 האם \u0003יורה?\u0004 כלומר, האם נותן אתה לו רשות להורות בדיני איסור והיתר? אמר לו: \u0003יורה.\u0004 והוסיף לשאול: האם גם \u0003ידין?\u0004 האם נותן אתה לו רשות לדון שייפטר מתשלום גם אם טעה? אמר לו: \u0003ידין.\u0004 האם נותן אתה לו רשות ש\u0003יתיר בכורות?\u0004 שבכור בהמה טהורה שנפל בו מום מביאים אותו לחכם, והוא מחליט אם מום קבוע הוא, ומותר לאכול אותו. אמר לו: \u0003יתיר.\u0004","בדומה לכך מסופר: \u0003כי הוה נחית\u0004 \u0005[כאשר ירד]\u0006 \u0003רב לבבל, אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא לרבי: בן אחותי יורד לבבל,\u0004 האם \u0003יורה?\u0004 אמר לו: \u0003יורה.\u0004 האם \u0003ידין?\u0004 — \u0003ידין,\u0004 האם \u0003יתיר בכורות?\u0004 אמר לו: \u0003אל יתיר.\u0004","בסיפור זה יש כמה דברים תמוהים, ושואלים: \u0003מאי שנא למר דקא קרי\u0004 \u0005[במה שונה שלחכם זה,\u0006 לרבה בר חנה, \u0005שהוא קורא אותו,\u0006 את ר' חייא\u0005]\u0006 \u0003\"בן אחי\",\u0004 \u0003ומאי שנא למר דקא קרי\u0004 \u0005[ובמה שונה שלחכם זה,\u0006 לרב \u0005שהוא קורא אותו]\u0006 \u0003\"בן אחותי\", וכי תימא הכי הוה\u0004 \u0005[ואם תאמר\u0006 ש\u0005כך היה]\u0006 ה\u0003מעשה,\u0004 שזה היה בן אחיו וזה היה בן אחותו, \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]\u0006 במסורת: \u0003איבו\u0004 (אבי רב), \u0003וחנה\u0004 (אבי רבה בר חנה), \u0003ושילא, ומרתא, ור' חייא\u0004 — \u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003בני אבא בר אחא כרסלא מ\u0004המקום \u0003כפרי הוו\u0004 \u0005[היו].\u0006 ואם כן הרי גם רב היה בן אחיו של ר' חייא? ומשיבים: \u0003רב\u0004 היה \u0003בר אחוה דהוה בר אחתיה\u0004 \u0005[בן אחיו שהיה\u0006 גם \u0005בן אחותו],\u0006 ואילו \u0003רבה בר חנה בר אחוה דלאו בר אחתיה\u0004 \u0005[בן אחיו שאינו בן אחותו],\u0006 ולכן הדגיש שיש לו קירבה נוספת אליו.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 מפני טעם אחר קראו \"בן אחותי\" —"],["\u0003על שם חכמתו\u0004 שהיה רב חכם ביותר, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"אמר לחכמה אחתי את\"\u0004 (משלי ז, ד), וכשקרא לו בן אחותו רמז לחכמתו.","אמרנו ששאלו האם \u0003יתיר בכורות?\u0004 ואמר לו: \u0003אל יתיר.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום\u0004 שהוא \u0003לא חכים\u0004 \u0005[חכם]\u0006 ולמדן דיו, \u0003הא קא אמרינן דחכים טובא\u0004 \u0005[הרי\u0006 כבר \u0005אמרנו ש\u0006הוא \u0005חכם ביותר],\u0006 \u0003אלא\u0004 תאמר \u0003משום\u0004 שהוא \u0003לא בקיע במומי\u0004 \u0005[בקי במומים],\u0006 ואף שידע את ההלכה אינו יודע בטיבם של המומים,","\u0003וה\u0004\u0003אמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: שמונה עשר חדשים גדלתי,\u0004 כלומר, שימשתי והסתכלתי \u0003אצל רועה בהמה, לידע איזה\u0004 הוא \u0003מום קבוע\u0004 בבהמה \u0003ואיזה\u0004 הוא \u0003מום עובר.\u0004 הרי שהיה בקי ביותר במומים! \u0003אלא\u0004 טעם הדבר היה \u0003לחלק לו כבוד לרבה בר חנה,\u0004 שרצה רבי לתת לו מינוי מיוחד כדי שינהגו בו כבוד. כי רב, מפני חכמתו ואישיותו, היו נוהגים בו כבוד גם בלא תוספת זו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003משום הא גופיה\u0004 \u0005[\u0006דבר \u0005זה עצמו]\u0006 ש\u0003רב בקיע במומי טפי\u0004 \u0005[\u0006היה \u0005בקי במומים ביותר],\u0006 \u0003ושרי מומי\u0004 \u0005[ומתיר מומים]\u0006 כאלה ש\u0003לא ידעי אינשי\u0004 \u0005[יודעים\u0006 בהם סתם \u0005אנשים],\u0006 \u0003ואמרי\u0004 \u0005[והיו אומרים]\u0006 בטעות על מום אחר: \u0003כי האי גוונא שרא\u0004 \u0005[כגון זה התיר]\u0006 \u0003רב, ואתו למשרי\u0004 \u0005[ויבואו להתיר]\u0006 \u0003מום עובר\u0004 הדומה קצת למום שהתיר רב. ומפני חשש זה לא נתן לו רבי רשות להתיר מומים.","במעשה על מינויים של רבה בר חנה ורב, הוזכר שנתן להם רבי רשות להורות באיסור והיתר. ושואלים: לשם מה היה צריך לתת לו רשות ש\u0003יורה? יורה\u0004 אף בלא נטילת רשות! שכן \u0003אי גמיר\u0004 \u0005[אם למד\u0006 ויודע\u0005]\u0006 — \u0003רשותא למה לי למישקל\u0004 \u0005[רשות למה לו לקבל],\u0006 הלא הכל תלוי בידיעת התורה בלבד?! שאין מתן רשות שייך אלא בדיני ממונות! ומסבירים שתיקנו שיקבל אדם רשות להורות אפילו בדיני איסור והיתר \u0003משום מעשה שהיה.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פעם אחת הלך רבי למקום אחד, וראה בני אדם שמגבלין\u0004 (לשים) \u0003עיסותיהם בטומאה,\u0004 שלא היו מקפידים בטהרת עצמם בשעת לישה, וסבורים היו שבכל זאת העיסה טהורה. \u0003אמר להם: מפני מה אתם מגבלין עיסותיכם בטומאה? אמרו לו: תלמיד אחד בא לכאן והורה לנו\u0004 כי \u0003מי בצעים\u0004 (ביצות) \u0003אין מכשירין\u0004 לקבל טומאה, והיו לוקחים מים מהביצות ובהם היו לשים, וסברו שהקמח הנילוש בהם אינו מקבל טומאה. \u0003ו\u0004באמת \u0003הוא,\u0004 אותו תלמיד, בדין \u0003מי ביצים,\u0004 כלומר, הנוזלים של הביצים \u0003דרש להו\u0004 \u0005[להם],\u0006 שאם לש אדם עיסה בביצים חיות בלבד — אין העיסה מקבלת טומאה, שאין מי הביצים נחשבים מים. \u0003ואינהו סבור\u0004 \u0005[והם סברו]\u0006 כי \u0003מי בצעים קאמר\u0004 \u0005[אמר].\u0006","\u0003וטעו\u0004 אנשי אותו מקום \u0003נמי בהא\u0004 \u0005[גם כן ב\u0006דבר \u0005זה]\u0006 שהיה גורם לטעותם, ששנינו: \u0003מי קרמיון ומי פיגה\u0004 (שמות שני נהרות) \u0003פסולין\u0004 לעשות מהם מי חטאת לטהרה, \u0003מפני שהן מי בצעים. ואינהו סבור\u0004 \u0005[והם,\u0006 אנשי המקום, \u0005סברו]:\u0006 \u0003מדלגבי\u0004 \u0005[מכיון שאצל,\u0006 לענין\u0005]\u0006 \u0003חטאת פסילי\u0004 \u0005[\u0006הם \u0005פסולים]\u0006 ואינם נחשבים למים — \u0003אכשורי נמי\u0004 \u0005[להכשיר\u0006 לקבל טומאה הם \u0005גם כן]\u0006 \u0003לא מכשרי\u0004 \u0005[מכשירים],\u0006 שאינם נחשבים מים. \u0003ו\u0004אולם \u0003לא היא,\u0004 אי אפשר להשוות את הדברים, כי \u0003התם\u0004 \u0005[שם]\u0006 \u0003לענין חטאת\u0004 — \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003מים חיים\u0004 (כפי שנאמר: \"ונתן עליו מים חיים אל כלי\". במדבר יט, יז), ומי ביצות אינם מים חיים. ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 לגבי הכשרה — \u0003אכשורי כל דהו מכשרי\u0004 \u0005[כל\u0006 מים \u0005שהם מכשירים],\u0006 וכיון שאותה טעות נגרמה מפני תלמיד שלא דקדק יפה בלשונו,","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003באותה שעה גזרו: תלמיד אל יורה אלא אם כן נוטל\u0004 תחילה \u0003רשות מרבו,\u0004 והרב אינו נותן לו רשות אם אינו יודע לדייק בדבריו כראוי.","אגב מעשה זה של הוראה מסופר: \u0003תנחום בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אמי איקלע\u0004 \u0005[נזדמן]\u0006 \u0003ל\u0004מקום הקרוי \u0003חתר, דרש להו\u0004 \u0005[להם,\u0006 לבני המקום\u0005]:\u0006 \u0003מותר ללתות\u0004 (לשרות מעט במים להקל על הקליפה בשעת טחינה) \u0003חיטין בפסח,\u0004 ואין לחשוש שמא יחמיצו בינתיים. \u0003אמרו לו: לאו\u0004 \u0005[האם לא]\u0006 \u0003ר' מני\u0004 ש\u0003מן צור איכא הכא\u0004 \u0005[ישנו כאן]\u0006 סמוך למקומנו. \u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003תלמיד אל יורה הלכה במקום רבו, אלא אם כן היה רחוק ממנו\u0004 \u0003שלש פרסאות\u0004 שהוא \u0003כנגד מחנה ישראל.\u0004 שבתוך המחנה אין אדם רשאי לדון בפני משה רבינו. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לאו אדעתאי\u0004 \u0005[לא\u0006 היה הדבר \u0005בדעתי],\u0006 כלומר, לא ידעתי שרבי מצוי במקום סמוך.","מסופר: \u0003ר' חייא חזייה לההוא גברא דהוה קאי\u0004 \u0005[ראה אדם אחד שהיה עומד]\u0006 \u0003בבית הקברות, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003בן איש פלוני כהן אתה?\u0004 ומה לכהן בבית הקברות? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם: \u0003אין\u0004 \u0005[כן],\u0006 ואולם \u0003אבוה דההוא גברא\u0004 \u0005[אביו של אותו אדם,\u0006 כלומר, אבי\u0005]\u0006 \u0003גבה עינים הוה\u0004 \u0005[היה]\u0006 החושק במה שאינו ראוי לו, \u0003נתן עיניו בגרושה\u0004 ונשאה והוליד ממנה בן, הוא האיש שהיה שם \u0003וחללו\u0004 על ידי כך מקדושת כהונה, שבן כהן הנולד מגרושה אין לו קדושת כהונה כלל. כיון שדובר כאן אודות נטילת רשות להורות, דנים עוד בדבר היקפה של רשות זו.","\u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 כי נתינת רשות \u0003לפלגא\u0004 \u0005[למחצה],\u0006 לחלק מן הדברים, \u0003הא קאמר דמהני\u0004 \u0005[הרי\u0006 כבר \u0005אמר ש\u0006היא \u0005מועילה].\u0006 ואולם נתינת רשות \u0003על תנאי מאי\u0004 \u0005[מה\u0006 דינה\u0005]?\u0006 האם אפשר לתת רשות לזמן מסויים, או למקום מסויים? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003אמר ר' יוחנן לרב שמן:\u0004\u0003 הרי אתה ברשותנו\u0004, כלומר, הרי לך רשות להורות ולדון \u0003עד שתבוא\u0004 (תחזור) \u0003אצלנו.\u0004 ומשמע שאפשר לתת רשות להורות למשך זמן מוגבל.","\u0003גופא\u0004 \u0005[לגופו]\u0006 של הענין שכבר הוזכר קודם לגבי בית דין של שנים, \u0003אמר שמואל: שנים שדנו\u0004 — \u0003דיניהם דין, אלא שנקרא \"בית דין חצוף\",\u0004 אבל אין הדבר פוגע בסמכותו. \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב נחמן\u0004 בין תלמידיו \u0003וקאמר להא שמעתא\u0004 \u0005[ואמר את ההלכה הזו],\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו במשנה: \u0003אפילו שנים\u0004 בתוך בית הדין \u0003מזכין או שנים מחייבין ואחד אומר \"איני יודע\"\u0004 — \u0003יוסיפו הדיינין\u0004 עוד אחד, משום שהנמנע נחשב כאילו לא היה במנין, ואין כאן בית דין. \u0003ואי איתא\u0004 \u0005[ואם יש]\u0006 בסיס להלכתו זו של שמואל, אם כן \u0003להוו\u0004 \u0005[שיהיו]\u0006 אותם דיינים שכבר הגיעו לידי החלטה \u0003כשנים שדנו,\u0004 ולא יצטרכו להוסיף, שגם אם השלישי איננו — יכולים הם לפסוק לבדם.","ענה לו רב נחמן: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דמעיקרא אדעתא דתלתא יתיבי\u0004 \u0005[שמתחילה על דעת שיהיו שלושה היו יושבים]\u0006 והחליטו שבשלושה יהוו בית דין שלם, ולכן אם נמנע אחד מהם — צריכים הם להשלים את המספר. ואילו \u0003הכא לאו אדעתא דתלתא יתיבי\u0004 \u0005[כאן לא על דעת של שלושה ישבו],\u0006 שמתחילה ישבו רק שניים לדון.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 עוד ממה ששנינו במקום אחר, \u0003רבן שמעון בן גמליאל אומר: הדין\u0004 נעשה \u0003בשלשה\u0004 דיינים, \u0003ופשרה\u0004 בין המתדיינים נעשית גם \u0003בשנים. ויפה כח פשרה מכח הדין, ששנים שדנו\u0004 — \u0003בעלי דינין יכולין לחזור בהן\u0004 ולומר שרצונם בבית דין שלם. \u0003ו\u0004אילו \u0003שנים שעשו פשרה\u0004 ונתרצו שני הצדדים שיפשרו ביניהם — \u0003אין בעלי דינין יכולין לחזור בהן.\u0004"],["\u0003וכי תימא פליגי רבנן עליה\u0004 \u0005[ואם תאמר חלוקים חכמים עליו],\u0006 על \u0003רבן שמעון בן גמליאל,\u0004 והם סבורים ששנים שדנו דיניהם דין, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבהו: שנים שדנו\u0004 — \u0003לדברי הכל אין דיניהם דין!\u0004 קושיה זו דוחים מיד: וכי \u0003גברא אגברא קא רמית\u0004 \u0005[מאדם על אדם אתה משליך,\u0006 מראה סתירה\u0005]?!\u0006 אמנם ר' אבהו סבר ששנים שדנו אין דיניהם דין לדברי הכל, ואולם שמואל סבר שזו היא רק דעת יחיד, וכי רוב החכמים סבורים שדיניהם דין.","ודנים ב\u0003גופא\u0004 (גוף) הדברים שנאמרו למעלה. \u0003אמר ר' אבהו: שנים שדנו דיני ממונות\u0004 — \u0003לדברי הכל אין דיניהם דין. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' אבא לר' אבהו\u0004 ממה ששנינו: דיין ש\u0003דן את הדין,\u0004 וטעה \u0003וזיכה את החייב\u0004 או ש\u0003חייב את הזכאי,\u0004 וכן אם \u0003טימא את הטהור,\u0004 או ש\u0003טיהר את הטמא\u0004 — \u0003מה שעשה עשוי,\u0004 ואין אומרים שהדין בטל ויחזרו וידונו בו, \u0003ומשלם מביתו\u0004 את כל הנזק שגרם. משמע שאפילו יחיד שדן דינו דין.","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 ש\u0003קיבלוהו עלייהו\u0004 \u0005[עליהם]\u0006 המתדיינים קודם לכן, שהסכימו לקבל את הכרעתו. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שקיבלוהו עליהם, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003משלם מביתו?\u0004 והלא קיבלו על עצמם לעשות כדבריו בכל מקרה! ומשיבים שמדובר כגון ש\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003דיינת לן\u0004 \u0005[דון לנו]\u0006 \u0003דין תורה,\u0004 ואם טעה ולא דן דין תורה — משלם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא לר' אבא:\u0004 הלכה זו בדיין שטעה, ש\u0003טעה במאי\u0004 \u0005[במה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003טעה בדבר משנה\u0004 שיש הלכה מפורשת שלא כדבריו, וטעה ופסק בניגוד להלכה, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב ששת אמר ר' אמי: טעה בדבר משנה\u0004 — \u0003חוזר,\u0004 שגם בית דין מומחה אם פסק בניגוד לדבר משנה, בטל דינו מעיקרו וכל הדין חוזר, ואין הזכאי יכול לומר שאיננו רוצה לחזור ולדון. \u0003אלא\u0004 מדובר כאן ש\u0003טעה בשיקול הדעת.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד היא בדיוק]\u0006 טעות \u0003בשיקול הדעת,\u0004 שהדיין יכול אחר כך לדעת בוודאות שטעה בהלכה. כי מה עדיפות יש לשיקול דעת שני על שיקולו הראשון? \u0003אמר רב פפא: כגון תרי תנאי ותרי אמוראי דפליגי אהדדי\u0004 \u0005[שני תנאים או שני אמוראים שחולקים זה על זה],\u0006 \u0003ולא איתמר הלכתא\u0004 \u0005[נאמרה הלכה]\u0006 \u0003לא כמר\u0004 \u0005[כחכם זה]\u0006 \u0003ולא כמר\u0004 \u0005[כחכם זה],\u0006 \u0003וסוגיין דעלמא אליבא דחד מינייהו\u0004 \u0005[ומהלך העולם,\u0006 כלומר, מקובל בין הדיינים, לפסוק \u0005כשיטת אחד מהם],\u0006 \u0003ואזל איהו ועבד כאידך\u0004 \u0005[והלך הוא ועשה כאחר]\u0006 — \u0003היינו\u0004 \u0005[זוהי]\u0006 טעות ב\u0003שיקול הדעת,\u0004 שלאחר זמן מתברר לו שהפסק המקובל אינו כהכרעתו שלו.","על מחלוקתם של שמואל ור' אבהו, בדבר מעמדו של בית דין של שנים, מעירים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 ש\u0005כ\u0006מחלוקת \u0005תנאים\u0006 אחרת\u0005]\u0006 היא בעיה זו, ששנינו: \u0003\"ביצוע\u0004 (פשרה) נעשית \u0003בשלשה\u0004 דיינים, אלו \u0003דברי ר' מאיר, וחכמים אומרים: פשרה ביחיד\".\u0004 ומסבירים כי \u0003סברוה\u0004 \u0005[סברו אותה]\u0006 האמוראים שרצו לדון בדבר כמה הנחות יסוד, והן: \u0003לכולי עלמא מקשינן\u0004 \u0005[ל\u0006דעת \u0005הכל אנו משווים]\u0006 \u0003פשרה לדין,\u0004 ושניהם נידונים באותו מספר של דיינים.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003בהא קמיפלגי\u0004 \u0005[ב\u0006דבר \u0005זה נחלקו],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' מאיר, \u0005סבור]\u0006 ש\u0003דין\u0004 נערך \u0003בשלשה\u0004 דיינים ולא בפחות וכן גם פשרה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבורים]\u0006 ש\u0003דין\u0004 נערך אפילו \u0003בשנים?\u0004 ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[ל\u0006דעת \u0005הכל]\u0006 \u0003דין בשלשה, והכא בהא קמיפלגי\u0004 \u0005[וכאן ב\u0006דבר \u0005זה\u0006 עצמו \u0005נחלקו],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 ש\u0003מקשינן\u0004 \u0005[משוים אנו]\u0006 \u0003פשרה לדין, ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבורים]\u0006 ש\u0003לא מקשינן\u0004 \u0005[אין אנו משווים]\u0006 \u0003פשרה לדין,\u0004","ומציעים עוד: \u0003לימא תלתא תנאי\u0004 \u0005[האם לומר ש\u0006מחלוקת \u0005שלושה תנאים,\u0006 שלוש דעות\u0005]\u0006 \u0003בפשרה, דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' מאיר, \u0005סבור]\u0006 שפשרה \u0003בשלשה\u0004 בלבד, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]:\u0006 \u0003בשנים, ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים כאן \u0005סבורים]\u0006 שהיא אפילו \u0003ביחיד!\u0004 ודוחים: \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' יימר בר שלמיא: מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שפשרה ב\u0003תרי\u0004 \u0005[\u0006ב\u0005שנים]\u0006 \u0003אפילו חד נמי\u0004 \u0005[\u0006ב\u0005אחד גם כן]\u0006 הוא מכשיר שאין יתרון שנים על אחד, \u0003והאי דקאמר תרי\u0004 \u0005[וזה שאמר שנים]\u0006 אינו כדי לחזק את מעמדם אלא כעצה טובה — \u0003כי היכי דליהוו עליה סהדי\u0004 \u0005[כדי שיהיו עליו עדים]\u0006 ולא יוכל צד אחד לחזור בו, ולומר שלא כך היתה הפשרה.","\u0003אמר רב אשי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 מסברה זו כי \u0003פשרה אינה צריכה קנין,\u0004 שאין צורך לעשות בסופה קנין, שהקנין הוא דרך חוקית להעברת הנכסים סופית מאדם לחבירו, שאם עושים קנין הרי מסקנת המפשרים תקבל תיכף ומיד תוקף מוחלט, שהרכוש יחשב כמועבר לבעליו. \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר שכל פשרה \u0003צריכה קנין,\u0004 אם כן \u0003למאן ד\u0004\u0003אמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שפשרה \u0003צריכה\u0004 קנין, אם כן \u0003תלתא\u0004 \u0005[שלושה]\u0006 \u0003למה לי,\u0004 ולשם מה שלושה? \u0003תסגי בתרי\u0004 \u0005[יהיה די בשנים]\u0006 \u0003וליקני מיניה\u0004 \u0005[ושיקנו ממנו]\u0006 שישלם החייב, ויהא זה גמר דין שאין אפשרות לחזור בו, וכמוהו כפסק של בית דין גמור? ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003פשרה צריכה קנין,\u0004 אפילו כאשר היא נעשית בשלושה.","כיון שהבאנו אגב הדיון ענין פשרה, מביאים מדברי התנאים הדנים באריכות בתוספתא בנושא זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כשם שהדין בשלשה כך ביצוע\u0004 (פשרה) \u0003בשלשה.\u0004"],["\u0003נגמר הדין\u0004 — \u0003אי\u0004 (אין) \u0003אתה רשאי לבצוע\u0004 (לפשר) אחרי שיודע אתה מי חייב ומי זכאי.","\u0003(סרמ\"ש בנק\"ש סימן.)\u0004 ואילו \u0003ר' אליעזר בנו של ר' יוסי הגלילי אומר: אסור\u0004 \u0003לבצוע, וכל הבוצע\u0004 — \u0003הרי זה חוטא.\u0004 שכן הפשרה מעוותת את הדין, שלפי האמת צד אחד צריך להיות זכאי או חייב, ואחרי הפשרה נמצא שצד אחד מקופח. ויותר מזה, \u0003וכל המברך את הבוצע\u0004 ואומר שעושה שלום בין הבריות — \u0003הרי זה מנאץ. ועל זה נאמר: \"\u0004כי הלל רשע על תאות נפשו ו\u0003בצע ברך נאץ ה' \"\u0004(תהלים י, ג),","\u0003אלא יקוב הדין את ההר,\u0004 כלומר, יש ללכת לפי דין האמת עד מיצויו, \u0003שנאמר: \"\u0004לא תגורו מפני איש כי \u0003כי המשפט לאלהים הוא\"\u0004 (דברים א, יז), וצריך המשפט להיעשות כחובה כלפי שמים. ומעירים: \u0003וכן משה\u0004 רבינו שהיה דן את ישראל על פי התורה \u0003היה אומר \"יקוב הדין את ההר\", אבל אהרן\u0004 אחיו שלא היה דיין, היה \u0003אוהב שלום ורודף שלום, ומשים שלום בין אדם לחבירו,\u0004 לפני שבאו הדברים לידי דין תורה, \u0003שנאמר\u0004 בשבחו של הכהן: \u0003\"תורת אמת היתה בפיהו ועולה לא נמצא בשפתיו בשלום ובמישור הלך אתי ורבים השיב מעון\"\u0004 (מלאכי ב, ו). אבל כאשר מגיעים הדברים לדין תורה שם אין מקום לפשרה. אחר שהובאה משמעות אחת לדברי הכתוב \"ובוצע ברך נאץ ה' \", מביאים לפרשו בפנים אחרות על ידי חכמים אחרים.","\u0003ר' אליעזר אומר: הרי שגזל\u0004 אדם מחבירו \u0003סאה של חטים, וטחנה ואפאה והפריש ממנה חלה, כיצד מברך\u0004 זה על מצות הפרשת חלה? — \u0003אין זה מברך\u0004 את ה' בברכה זו \u0003אלא מנאץ, ועל זה נאמר: \"ובצע ברך נאץ ה' \",\u0004 כלומר, הבוצע מקצת מן העיסה להפרישה חלה, ומברך על כך — ניאץ ה'.","\u0003ר' מאיר אומר: לא נאמר\u0004 פסוק זה ב\u0003\"בוצע\" אלא כנגד יהודה, שנאמר\u0004 במכירת יוסף: \u0003\"ויאמר יהודה אל אחיו מה בצע כי נהרג את אחינו\u0004 וכסינו את דמו. לכו ונמכרנו לישמעאלים\u0003\"\u0004 (בראשית לז כו –כז), \u0003וכל המברך את יהודה\u0004 ואומר שעשה מעשה טוב — \u0003הרי זה מנאץ\u0004 שהרי יכול היה, אילו רצה, להצילו לגמרי, \u0003ועל זה נאמר: \"ובצע ברך נאץ ה' \".\u0004","שיטה אחרת בענין פשרה היתה בידי \u0003ר' יהושע בן קרחה\u0004 ה\u0003אומר: מצוה לבצוע, שנאמר: \"אמת ומשפט שלום שפטו בשעריכם\"\u0004 (זכריה ח, טז). \u0003והלא במקום שיש משפט\u0004 ועומדים על הדין — \u0003אין שלום, ובמקום שיש שלום\u0004 — \u0003אין משפט?! אלא איזהו משפט שיש בו\u0004 גם \u0003שלום\u0004 — \u0003הוי אומר: זה ביצוע,\u0004 ששני הצדדים מתרצים בדבר.","\u0003וכן בדוד הוא אומר \"ויהי דוד עושה משפט וצדקה\u0004 לכל עמו\u0003\"\u0004 (שמואל ב' ח, טו), \u0003והלא כל מקום שיש משפט\u0004 — \u0003אין צדקה,\u0004 שהרי משפט דין הוא, \u0003ו\u0004במקום שיש \u0003צדקה\u0004 — \u0003אין משפט. אלא איזהו משפט שיש בו צדקה\u0004 — \u0003הוי אומר: זה ביצוע.\u0004","ומעירים: במשפט זה \u0003אתאן\u0004 \u0005[באנו,\u0006 חזרנו\u0005]\u0006 \u0003ל\u0004שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 המתיר את הפשרה. ועוד פירוש אחר נאמר ל\"משפט וצדקה\": \u0003דן\u0004 הדיין \u0003את הדין, זיכה את הזכאי וחייב את החייב, וראה שנתחייב עני\u0004 לשלם \u0003ממון ושלם לו\u0004 הדיין לזכאי \u0003מתוך ביתו\u0004 שלו — \u0003זה משפט וצדקה,\u0004 שיש בו","\u0003משפט לזה וצדקה לזה. משפט לזה\u0004 — \u0003שהחזיר לו ממון\u0004 שמגיע לו ודין ומשפט אמת דן, \u0003וצדקה לזה\u0004 — \u0003ששילם לו\u0004 הדיין \u0003מתוך ביתו\u0004 שאינו יכול לשלם משל עצמו. \u0003וכן בדוד הוא אומר: \"ויהי דוד עשה משפט וצדקה לכל עמו\",\u0004 יש להבין שהיה עושה \u0003משפט לזה\u0004 — \u0003שהחזיר לו את ממונו, וצדקה לזה\u0004 — \u0003ששילם לו\u0004 לענין שנתחייב \u0003מתוך ביתו\u0004 שלו.","\u0003קשיא ליה\u0004 \u0005[קשה היה לו]\u0006 \u0003לרבי\u0004 על פירוש זה: \u0003האי\u0004 \u0005[זה,\u0006 הביטוי\u0005]\u0006 \u0003\"לכל עמו\"\u0004 אינו מדוייק במקרה זה, כי \u0003\"לעניים\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שבמקרה זה היה דוד עושה משפט לכולם, וצדקה רק לעניים, שלהם שילם מה שנתחייבו. \u0003אלא, רבי אומר: אף על פי שלא שילם\u0004 לעני \u0003מתוך ביתו\u0004 ודן את הדין בצדק \u0003זהו משפט וצדקה, משפט לזה וצדקה לזה. משפט לזה\u0004 — \u0003שהחזיר לו ממונו, וצדקה לזה\u0004 — \u0003שהוציא\u0004 את ה\u0003גזילה מתחת ידו.\u0004 ואם כן, עכשיו הוא צדיק בדין שמים.","\u0003ר' שמעון בן מנסיא אומר\u0004 בענין פשרה: \u0003שנים שבאו לפניך\u0004 הדיין \u0003לדין, עד שלא תשמע\u0004 את \u0003דבריהן\u0004 (טענותיהם), \u0003או משתשמע דבריהן ואי\u0004 (אין) \u0003אתה יודע\u0004 עדיין \u0003להיכן\u0004 ה\u0003דין נוטה\u0004 ומי מהם צודק — \u0003אתה רשאי לומר להן: צאו ובצעו\u0004 (עשו פשרה) ביניכם. \u0003משתשמע דבריהן ואתה יודע להיכן הדין נוטה\u0004 — \u0003אי אתה רשאי לומר להן\u0004 עוד: \u0003צאו ובצעו, שנאמר: \"פוטר מים ראשית מדון ולפני התגלע הריב נטוש\"\u0004 (משלי יז, יד), \u0003קודם שנתגלע\u0004 (נגלה ונתברר) דבר \u0003הריב\u0004 — \u0003אתה יכול לנטשו\u0004 (לעזבו) וליעץ לבעלי הדין להתפשר. \u0003משנתגלע הריב\u0004 — \u0003אי אתה יכול\u0004 עוד \u0003לנטשו.\u0004","\u0003וריש לקיש אמר\u0004 באותו ענין: \u0003שנים שבאו\u0004 לפניך הדיין \u0003לדין, אחד\u0004 מהם \u0003רך,\u0004 כלומר, אדם שאינו תקיף ואינו אלים, \u0003ואחד\u0004 מהם \u0003קשה, עד שלא תשמע דבריהן, או משתשמע דבריהן ואין אתה יודע\u0004 עדיין \u0003להיכן דין נוטה\u0004 — \u0003אתה רשאי לומר להם: אין אני נזקק לכם\u0004 לדון בדין זה והתדיינו בפני אחר, שחושש הדיין \u0003שמא\u0004 יתברר לבסוף ש\u0003נתחייב חזק\u0004 שבהם, \u0003ונמצא חזק רודפו\u0004 על שחייבו. ואולם \u0003משתשמע דבריהן ואתה יודע להיכן הדין נוטה,\u0004 ויודע אתה שהחזק בהם הוא החייב, \u0003אי אתה יכול לומר להן: איני נזקק לכם, שנאמר\u0004 בכגון זה: \u0003\"לא תגורו מפני איש\"\u0004 (דברים א, יז), שאסור לו לדיין להתיירא מפני הבריות.","\u0003ר' יהושע בן קרחה אומר: מניין לתלמיד שיושב לפני רבו\u0004 בשעה שרבו דן בין שני אנשים \u0003וראה זכות לעני וחובה לעשיר,\u0004 ורבו לא שם לב לצד זה, \u0003מניין שלא ישתוק\u0004 מפני כבוד רבו ומפני החשש לעורר עליו חמתו של העשיר — \u0003שנאמר: \"לא תגורו מפני איש\". ר' חנין אומר\u0004 בביאור הדברים: \u0003לא תכניס דבריך מפני איש,\u0004 כלומר, אל תצמצם את עצמך שלא לומר דברים מפני שאתה חושש מאדם, ועוד אמר: \u0003ויהו עדים יודעים את מי הן מעידין, ולפני מי הן מעידין, ומי עתיד ליפרע מהן, שנאמר: \"ועמדו שני האנשים אשר להם הריב לפני ה'\u0004 לפני הכהנים והשופטים אשר יהיו בימים ההם\u0003\"\u0004 (דברים, יט, יז), והסבירו חכמינו שמדובר כאן בעדים, החייבים לדעת שהם מעידים לא רק לפני השופטים אלא לפני ה'.","\u0003ו\u0004כן \u0003יהו הדיינין יודעין את מי הן דנין, ולפני מי הן דנין, ומי עתיד ליפרע מהן\u0004 אם לא ידונו דין אמת, \u0003שנאמר: \"אלהים נצב בעדת אל\u0004 בקרב אלהים ישפוט\u0003\"\u0004 (תהלים פב, א), כלומר, ה' עומד בין הדיינים (\"בקרב אלהים\") ושופט עמהם. \u0003וכן ביהושפט הוא אומר: \"ויאמר אל השפטים ראו מה אתם עשים כי לא לאדם תשפטו כי אם לה'\u0004 ועמכם בדבר משפט\u0003\"\u0004 (דברי הימים ב יט, ו), \u0003שמא יאמר הדיין\u0004 אם כן \u0003מה לי בצער הזה\u0004 לקבל על עצמי תפקיד זה? \u0003תלמוד לומר: \"עמכם בדבר משפט\"\u0004 והכוונה — \u0003אין לו לדיין אלא מה שעיניו רואות,\u0004 ואין הדיין צריך לתהות שמא לא הגיע לידיעת האמת לאמיתה, אלא לפי ראות עיניו (\"עמכם\" — לפי מה שעם לבו) יהא ה' עמו לעזרו שיצא דין צדק.","בתוספתא זו הובאה הדעה, שלאחר גמר דין שוב אין הדיין רשאי להציע פשרה, ושואלים: \u0003היכי דמי\u0004 \u0005[מהו בדיוק]\u0006 \u0003גמר דין? אמר רב יהודה אמר רב:\u0004 כשהוא מגיע לומר: \u0003איש פלוני\u0004 — \u0003אתה חייב, איש פלוני\u0004 — \u0003אתה זכאי. אמר רב: הלכה כ\u0004שיטת \u0003ר' יהושע בן קרחה,\u0004 שמצוה לעשות פשרה. ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב הונא תלמידיה\u0004 \u0005[תלמידו\u0006 המובהק\u0005]\u0006 של \u0003רב הוה\u0004 \u0005[היה],\u0006 \u0003כי הוה אתו לקמיה\u0004 \u0005[כאשר היו באים\u0006 לדין \u0005לפני]\u0006 \u0003רב הונא,\u0004 \u0003אמר להו\u0004 \u0005[להם]\u0006 מתחילה: \u0003אי דינא בעיתו, אי\u0004 \u0005[האם דין אתם רוצים, או]\u0006 \u0003פשרה בעיתו\u0004 \u0005[אתם רוצים]?\u0006 הרי שעשיית פשרה אינה ממש מצוה! ומסבירים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003\"מצוה\" נמי\u0004 \u0005[גם כן]\u0006 \u0003דקאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' יהושע בן קרחה\u0004 — כוונתו היתה:"],["\u0003מצוה למימרא להו\u0004 \u0005[לומר להם]\u0006 תחילה: \u0003אי דינא בעיתו, אי\u0004 \u0005[האם דין אתם רוצים, או]\u0006 \u0003פשרה בעיתו\u0004 \u0005[אתם רוצים].\u0006 ומקשים: אם כן \u0003היינו\u0004 \u0005[זוהי]\u0006 שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 המתיר לעשות פשרה! ומסבירים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 לענין ה\u0003מצוה\u0004 שבדבר. \u0003ר' יהושע בן קרחה סבר:\u0004 עשיית פשרה היא \u0003מצוה,\u0004 שצריך להציע אפשרות זו. ו\u0003תנא קמא סבר:\u0004 אינה מצוה אלא \u0003רשות.\u0004","ומקשים: אם כן, הרי שיטה זו של האומר רשות \u0003היינו\u0004 \u0005[זוהי]\u0006 שיטתו של \u0003ר' שמעון בן מנסיא\u0004 האומר כי כל עוד לא שמע הדיין את טענות הצדדים או אפילו שכבר שמע אלא שאינו יודע להיכן הדין נוטה, הריהו רשאי לעשות פשרה ביניהם! ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005],\u0006 שלדעת ר' שמעון בן מנסיא \u0003משתשמע דבריהן ואתה יודע להיכן הדין נוטה, אי\u0004 (אין) \u0003אתה רשאי לומר להן צאו ובצעו,\u0004 ואילו לדעת התנא הראשון כל עוד לא נגמר הדין ממש יכול הדיין להציע פשרה אף שהוא יודע להיכן הדין נוטה.","למדנו שחכמים דרשו בדרכים שונות את הפסוק \"ובוצע ברך נאץ ה' \", ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעת כל אחד מהם על דרשתו של \u0003ר' תנחום בר חנילאי.\u0004 ש\u0003אמר ר' תנחום בר חנילאי: לא נאמר מקרא זה אלא כנגד מעשה העגל, שנאמר: \"וירא אהרן ויבן מזבח לפניו\u0004 ויקרא אהרן ויאמר חג לה' מחר\u0003\"\u0004 (שמות לב, ה) ושואלים: \u0003מה ראה\u0004 אהרן שהחליט לעשות את העגל? \u0003אמר ר' בנימין בר יפת אמר ר' אלעזר: ראה\u0004 את \u0003חור\u0004 שגם אותו הפקיד משה על העם (ראה שמות כד, יד) \u0003שזבוח לפניו,\u0004 שהתנגד לעשות את העגל והרגוהו.","\u0003אמר\u0004 אהרן בליבו: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא שמענא להו השתא\u0004 \u0005[אשמע להם עכשיו]\u0006 הרי הם \u0003עבדו\u0004 \u0005[יעשו]\u0006 \u0003לי כדעבדו\u0004 \u0005[כפי שעשו]\u0006 \u0003בחור,\u0004 \u0003ומיקיים\u0004 \u0005[ויתקיים]\u0006 אז \u0003בי,\u0004 בהריגתי \u0003\"אם יהרג במקדש ה' כהן ונביא\"\u0004 (איכה ב, כ), \u0003ו\u0004על חטא חמור כזה \u0003לא הויא להו תקנתא\u0004 \u0005[תהא להם תקנה]\u0006 \u0003לעולם. מוטב דליעבדו\u0004 \u0005[שיעבדו]\u0006 \u0003לעגל, אפשר הויא להו תקנתא\u0004 \u0005[שתהיה להם תקנה]\u0006 \u0003בתשובה.\u0004 ור' תנחום בן חנילאי אומר שלמרות זאת אסור לשבח את מעשהו של אהרן, והמשבח פשרה זו שעשה אהרן עם עצמו — הריהו כמנאץ ה'.","ושואלים: \u0003והני תנאי\u0004 \u0005[ואלו תנאים]\u0006 שלא דרשו את הכתוב \u0003\"פוטר מים ראשית מדון\u0004 ולפני התגלע הריב נטוש\u0003\"\u0004 (משלי יז, יד) לענין פשרה, \u0003מאי דרשי ביה\u0004 \u0005[מה דורשים\u0006 הם \u0005בו]?\u0006 ומשיבים: הם דורשים אותו \u0003כ\u0004שיטת \u0003רב המנונא.\u0004 ש\u0003אמר רב המנונא: אין תחילת דינו של אדם נידון\u0004 ביום הדין \u0003אלא על דברי תורה\u0004 אם למד או לא למד, \u0003שנאמר: \"פוטר מים ראשית מדון\",\u0004 שהשאלה האם עסק אדם ודבר (\"פוטר\") בדברי תורה (המשולה כמים) הוא ראשית הדין. מאותו כתוב \u0003אמר רב הונא\u0004 כי \u0003האי תיגרא דמיא לצינורא דבידקא דמיא\u0004 \u0005[תגרה זו\u0006 שבין אנשים \u0005דומה לצנור מים שנפרץ בו פרץ],\u0006 \u0003כיון דרווח\u0004 \u0005[שגדל]\u0006 — \u0003רווח\u0004 \u0005[גדל],\u0006 שהפירצה גדלה והולכת במהירות יתירה, והוא שנאמר \"פוטר מים\" כמי שפותח את המים — כך היא ראשית מדון, שהיא הולכת ונעשית לריב גדול.","\u0003אביי קשישא\u0004 \u0005[הזקן]\u0006 \u0003אמר:\u0004 תגרה \u0003דמי לגודא דגמלא\u0004 \u0005[דומה לקרש בגשר עץ],\u0006 \u0003כיון דקם\u0004 \u0005[ש\u0006הוא \u0005מתייצב]\u0006 — \u0003קם\u0004 \u0005[נעשה יציב]\u0006 ונשאר קבוע. וכן התגרה ככל שממשיכים בה היא נעשית יותר קבועה וחזקה.","אגב מדרש הכתוב הזה מביאים עוד פתגמים עממיים בנושאים שונים (לדברים האמורים להלן \u0003שמע\"י ושת\"י שב\"ע זמירו\"ת הו\"א סימן\u0004).","מסופר: \u0003ההוא דהוה קאמר ואזיל\u0004 \u0005[אדם אחד שהיה אומר והולך]:\u0006 \u0003טוביה דשמע ואדיש, חלפוה בישתיה\u0004 \u0005[טוב לו למי ששומע\u0006 דברים עליו \u0005ושותק, יחלפו ממנו רעות]\u0006 \u0003מאה.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה:\u0004 מה שאומר אדם זה \u0003קרא כתיב\u0004 \u0005[מקרא כתוב]\u0006 שנאמר \u0003\"פוטר מים ראשית מדון\".\u0004 ששמואל דרש \"ראשית מדון\" — \u0003ריש מאה דיני\u0004 \u0005[ראש מאה דינים],\u0006 ומי שפוטר, כלומר, נמנע מתגרה, חוסך מעצמו מאה רעות. וכיון שמובא סיפור זה מביאים עוד בכיוצא בו.","\u0003ההוא דהוה קאמר ואזיל\u0004 \u0005[אדם אחד שהיה אומר והולך]:\u0006 \u0003אתרתי תלת גנבא לא מיקטל\u0004 \u0005[על שתים שלוש\u0006 פעמים, \u0005הגנב אינו נהרג].\u0006 \u0003אמר ליה שמואל לרב יהודה: קרא כתיב\u0004 \u0005[מקרא כתוב]\u0006 כענין זה, שנאמר: \u0003\"כה אמר ה' על שלשה פשעי ישראל ועל ארבעה לא אשיבנו\"\u0004 (עמוס ב, ו), משמע בפחות מכן עדיין יש תקנה.","ועוד: \u0003ההוא דהוה קאמר ואזיל\u0004 \u0005[אדם אחד שהיה אומר והולך]:\u0006 \u0003שב בירי לשלמנא, וחדא לעביד ביש\u0004 \u0005[שבעה בורות לאיש שלום\u0006 וניצול מהם \u0005ואחת לעושה רע]\u0006 ולא יצא ממנו. \u0003אמר ליה שמואל לרב יהודה קרא כתיב\u0004 \u0005[מקרא כתוב]\u0006 כענין זה: \u0003\"כי שבע יפול צדיק וקם ורשע יפול באחת\"\u0004 (ראה משלי כד, טז)","ועוד \u0003ההוא דהוה קאמר ואזיל\u0004 \u0005[אדם אחד שהיה אומר והולך]\u0006: \u0003דאזיל מבי דינא שקל גלימא\u0004 \u0005[\u0006מי \u0005שיוצא מבית הדין נטול גלימה]\u0006 שהפסידה בדינו — \u0003ליזמר\u0004 \u0005[יזמר]\u0006 \u0003זמר וליזיל באורחא\u0004 \u0005[וילך בדרך],\u0006 שגם אם הפסיד בדין, הפסיד, ונגמר הענין בצדק. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: קרא כתיב\u0004 \u0005[מקרא כתוב]\u0006 בענין מינוי שופטים לעם כענין זה: \u0003\"וגם כל העם הזה על מקמו יבא בשלום\"\u0004 (שמות יח, כג), שלא רק הזוכים בדין, אלא גם אלה שהתחייבו יוצאים בשלום.","ועוד: \u0003ההוא דהוה קאמר ואזיל\u0004 \u0005[אדם אחד שהיה אומר והולך]:\u0006 \u0003היא ניימא, ודיקולא שפיל\u0004 \u0005[ישנה, וסל הנצרים\u0006 על ראשה \u0005נופל].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה,\u0004 \u0003קרא כתיב\u0004 \u0005[מקרא נאמר]:\u0006 \u0003\"בעצלתים ימך המקרה\u0004 ובשפלות ידים ידלוף הבית\u0003\"\u0004 (קהלת י, יח), כלומר, עצלות גורמת שהכל יתמוטט.","ועוד: \u0003ההוא דהוה קאמר ואזיל\u0004 \u0005[אדם אחד שהיה אומר והולך]:\u0006 \u0003גברא דרחיצנא עליה אדייה לגזיזיה\u0004 \u0005[האיש שבטחתי בו הרים את אגרופו\u0006 \u0003וקם\u0004 עלי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה,\u0004 \u0003קרא כתיב\u0004 \u0005[מקרא כתוב]:\u0006 \u0003\"גם איש שלומי אשר בטחתי בו\u0004 אוכל לחמי הגדיל עלי עקב\u0003\"\u0004 (תהילים מא, י).","ועוד: \u0003ההוא דהוה קאמר ואזיל\u0004 \u0005[אדם אחד שהיה אומר והולך]:\u0006 \u0003כי רחימתין הוה עזיזא\u0004 \u0005[כאשר אהבתנו היתה עזה]\u0006 — \u0003אפותיא דספסירא שכיבן\u0004 \u0005[על רוחב הסייף שכבנו],\u0006 והיה לנו מקום למדי, \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003לא עזיזא רחימתין\u0004 \u0005[עזה אהבתנו]\u0006 — \u0003פוריא בר שיתין גרמידי לא סגי לן\u0004 \u0005[מיטה בת ששים אמות אינה דיה לנו].\u0006 \u0003אמר רב הונא: קראי כתיבי\u0004 \u0005[כתובים נאמרו]\u0006 כעין רעיון זה, \u0003מעיקרא כתיב\u0004 \u0005[מתחילה נאמר]\u0006 במשכן \u0003\"ונועדתי לך שם ודברתי אתך מעל הכפרת\u0004 מבין שני הכרובים אשר על ארון העדות\u0003\"\u0004 (שמות כה, כב) \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 ה\u0003ארון\u0004 היה גבוה \u0003תשעה\u0004 טפחים \u0003ו\u0004ה\u0003כפורת\u0004 עצמה \u0003טפח הרי כאן עשרה,\u0004 ומתחילה כשהיתה חיבת ה' לישראל היתה שכינה מתגלה אף במקום מצומצם זה.","ובבית המקדש נאמר \u0003\"והבית אשר בנה המלך שלמה לה' ששים אמה ארכו ועשרים רחבו ושלשים אמה קומתו\"\u0004 (מלכים א' ו, ב), \u0003ולבסוף כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"כה אמר ה' השמים כסאי והארץ הדם רגלי אי זה בית אשר תבנו לי\u0004 ואיזה מקום מנוחתי\u0003\"\u0004 (ישעיה סו, א), שכאשר חטאו ישראל בית המקדש כולו אינו רחב למדי שתשרה בו שכינה.","ושבים לבאר דברים שהוזכרו באותה ברייתא \u0003מאי משמע\u0004 \u0005[מה המשמעות]\u0006 \u0003דהאי\u0004 \u0005[ש\u0006מלה \u0005זו]\u0006 \u0003\"לא תגורו\" לישנא דכנושי\u0004 \u0005[לשון כינוס\u0006 והתכנסות\u0005]\u0006 \u0003הוא,\u0004 שמכאן למדים שאין לו לדיין להסתיר דבריו ולהחביאם? \u0003אמר רב נחמן,\u0004 \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויין לא תשתה ולא תאגר\"\u0004 (דברים כח, לט) משמע ש\"אגירה\" היא לשון הכנסה פנימה. \u0003רב אחא בר יעקב אמר, מהכא\u0004 \u0005[מכאן]\u0006 לומדים זאת, שנאמר: \u0003\"תכין בקיץ לחמה אגרה בקציר מאכלה\"\u0004 (משלי ו, ח), כלומר, \"אגירה\" היא הכנסה בפנים, \u0003רב אחא בריה \u0004 \u0005[בנו]\u0006 של \u0003רב איקא אמר: מהכא\u0004 \u0005[מכאן]\u0006 לומדים זאת, שנאמר: \u0003\"אגר בקיץ בן משכיל\"\u0004 (משלי י, ה). כיון שנאמרו דברי ם בהגדרת תפקידם של הדיינים ובהבנת ערכם מביאים עוד דרשות חכמים באותו ענין.","\u0003(אמ\"ת ממו\"ן ירא\"ה סימן)\u0004 \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: כל דיין שדן דין אמת לאמיתו\u0004 — הריהו \u0003משרה שכינה בישראל, שנאמר: \"אלהים נצב בעדת אל בקרב אלהים ישפט\"\u0004 (תהלים פב, א), משמע שהשכינה שורה בתוך בית הדין. ולהיפך, \u0003כל דיין שאינו דן דין אמת לאמיתו\u0004 — \u0003גורם לשכינה שתסתלק מישראל, שנאמר: \"משד עניים מאנקת אביונים עתה אקום יאמר ה' \"\u0004(תהלים יב, ו), כלומר, ה' יקום ויסתלק משם.","\u0003ואמר ר' שמואל בר נחמן אמר ר' יונתן: כל דיין שנוטל מזה ונותן לזה שלא כדין, הקדוש ברוך הוא נוטל ממנו,\u0004 מן הדיין, את \u0003נפשו, שנאמר: \"אל תגזל דל כי דל הוא ואל תדכא עני בשער. כי ה' יריב ריבם וקבע את קבעיהם נפש\"\u0004 (משלי כב, כב–כג), כלומר, הגוזל מעניים בדין (\"בשער\"), הקדוש ברוך הוא יקח ממנו (\"קבע\") את נפשו.","\u0003ואמר ר' שמואל בר נחמני אמר ר' יונתן: לעולם יראה דיין\u0004 את \u0003עצמו כאילו חרב מונחת לו בין ירכותיו, וגיהנם פתוחה לו מתחתיו,\u0004 אם יסטה משורת הדין."],["\u0003שנאמר: \"הנה מטתו שלשלמה ששים גברים סביב לה מגברי ישראל. כלם אחזי חרב מלמדי מלחמה איש חרבו על ירכו מפחד בלילות\"\u0004 (שיר השירים ג, ז–ח), ודרשו, שתלמידי חכמים העוסקים בדין תורה, שהשכינה (\"שלמה\") שרויה לידם, צריכים לראות עצמם כאילו חרב מונחת על ירכם והם מפחדים \u0003מפחדה של גיהנם שדומה ללילה.\u0004","\u0003דרש ר' יאשיה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב נחמן בר יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"בית דוד כה אמר ה' דינו לבקר משפט והצילו גזול מיד עושק\"\u0004 (ירמיה כא, יב), \u0003וכי בבקר דנין וכל היום אין דנין?\u0004 ואם כן מהו \"לבוקר\"? \u0003אלא: אם ברור לך הדבר כבקר\u0004 שהוא מאיר — \u0003אמרהו, ואם לאו\u0004 (לא) — \u0003אל תאמרהו. ר' חייא בר אבא אמר\u0004 בשם \u0003ר' יונתן:\u0004 דבר זה נלמד \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"אמר לחכמה אחתי את\"\u0004 (משלי ז, ד), ללמדנו: \u0003אם ברור לך הדבר כאחותך שהיא אסורה לך\u0004 — \u0003אומרהו, ואם לאו,\u0004 אם אינו ברור לך כל כך — \u0003אל תאמרהו.\u0004 ועוד בענין דין ודיינים.","\u0003אמר ר' יהושע בן לוי: עשרה שיושבין בדין\u0004 — \u0003קולר\u0004 (שרשרת של אסירים), כלומר, האחריות \u0003תלוי בצואר כולן.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 שכולם אחראים! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא לתלמיד היושב לפני רבו,\u0004 שאף שאינו בין הדיינים, בכל זאת גם לו חלק באחריות.","ומסופר שבהתאם לרעיון זה \u0003רב הונא כי הוה אתי דינא לקמיה\u0004 \u0005[כאשר היה בא דין לפניו],\u0006 \u0003מיכניף ומייתי\u0004 \u0005[היה אוסף ומביא]\u0006 עוד \u0003עשרה רבנן מבי\u0004 \u0005[חכמים מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב.\u0004 \u0003אמר: כי היכי דלימטיין שיבא מכשורא\u0004 \u0005[כדי שיגיע לנו\u0006 רק \u0005שבב מן הקורה],\u0006 שתהא האחריות תלויה בכולם, ואשר על כן על כל אחד מהם רובץ רק חלק קטן ממנה, שלא רצה לקבל על עצמו בלבד את כל האחריות. ובדומה לזה, \u0003רב אשי, כי הוה אתי טריפתא לקמיה\u0004 \u0005[כאשר היתה באה\u0006 שאלה בדין \u0005טריפה לפניו],\u0006 \u0003מכניף ומייתי להו לכולהו טבחי\u0004 \u0005[היה אוסף ומביא אותם, את כל השוחטים]\u0006 של \u0003מתא מחסיא\u0004 עירו, \u0003אמר: כי היכי דלימטיין שיבא מכשורא\u0004 \u0005[כדי שיגיע לנו\u0006 רק \u0005שבב מן הקורה].\u0006","ועוד בענין דיינים: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר, דרש רב נחמן בר כהן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"מלך במשפט יעמיד ארץ ואיש תרומות יהרסנה\"\u0004 (משלי כט, ד) — \u0003אם\u0004 ה\u0003דיין דומה למלך, שאינו צריך לכלום\u0004 ואינו נזקק לממונם של אחרים, ואינו תלוי בהם — הוא \u0003יעמיד ארץ, ואם דומה לכהן שמחזר בבית הגרנות\u0004 לקבץ את התרומות — הוא \u0003יהרסנה,\u0004 שאינו יכול להיות תקיף כראוי.","מסופר: \u0003דבי נשיאה אוקמו דיינא\u0004 \u0005[בני בית הנשיא העמידו דיין]\u0006 ש\u0003לא הוה גמיר\u0004 \u0005[למד].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו דיין \u0003ליהודה בר נחמני\u0004 שהיה כרגיל \u0003מתורגמניה\u0004 \u0005[מתורגמנו],\u0006 האיש שהיה מסביר דבריו ברבים של \u0003ריש לקיש: קום עליה באמורא\u0004 \u0005[עמוד עליו,\u0006 עלי לשמש \u0005לו כמתורגמן,\u0006 והוא ידרוש\u0005].\u0006 \u0003קם, גחין עליה\u0004 \u0005[עמד, והתכופף לידו]\u0006 כמקובל, שהחכם יאמר דבר מה, והוא יתרגם ויסביר את הדברים לקהל, \u0003ולא\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר]\u0006 משום שלא ידע.","\u0003פתח ואמר\u0004 המתורגמן על הכתוב \u0003\"הוי אמר לעץ הקיצה עורי לאבן דומם הוא יורה הנה הוא תפוש זהב וכסף וכל רוח אין בקרבו\"\u0004 (חבקוק ב, יט), כך הוא דיין זה, שבשל כסף וזהב העמידוהו להיות מורה לרבים, ואינו אלא כעץ ואבן דומם. \u0003ו\u0004הוסיף עוד כי \u0003עתיד הקדוש ברוך הוא ליפרע מ\u0004אלה ה\u0003מעמידין\u0004 (הממנים) איש כזה, \u0003שנאמר: \"וה' בהיכל קדשו הס מפניו כל הארץ\"\u0004 (חבקוק ב, כ), שהוא עליון על הכל והוא ידון את האחראים לכך.","\u0003אמר ריש לקיש: כל המעמיד דיין על הציבור שאינו הגון\u0004 (ראוי) \u0003כאילו נוטע אשירה\u0004 (אילן של עבודה זרה) \u0003בישראל.\u0004 ורמז לדבר, ממה \u0003שנאמר: \"שפטים ושטרים תתן לך\"\u0004 (דברים טז, יח), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 לדין מינוי שופטים האיסור \u0003\"לא תטע לך אשרה כל עץ\u0004 אצל מזבח ה' אלהיך אשר תעשה לך\u0003\"\u0004 (דברים טז, כא). \u0003אמר רב אשי: ו\u0004הממנה דיין כזה \u0003במקום שיש\u0004 בו \u0003תלמידי חכמים, כאילו נטעו\u0004 לעץ האשרה \u0003אצל מזבח, שנאמר: \"אצל מזבח ה' אלהיך\".\u0004","\u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"לא תעשון אתי אלהי כסף ואלהי זהב\u0004 לא תעשו לכם\u0003\"\u0004 (שמות כ, כ). ויש לתמוה: וכי \u0003אלהי כסף ואלהי זהב הוא דלא עבדי\u0004 \u0005[שאין עושים],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 של \u0003עץ שרי\u0004 \u0005[מותר]?!\u0006 אלא \u0003אמר רב אשי,\u0004 יש להבין זאת כך: \u0003אלוה\u0004 — כלומר, דיין (הקרוי אלהים) \u0003הבא בשביל כסף, ואלוה הבא בשביל זהב.\u0004","ועוד בענין הדיינים, \u0003רב כי הוה אתי לבי דינא, אמר הכי\u0004 \u0005[כאשר היה בא לבית הדין, היה אומר כך]:\u0006 \u0003ברעות נפשיה לקטלא נפיק, וצבי ביתיה לית הוא עביד\u0004 \u0005[ברצון נפשו למיתה\u0006 הוא \u0005יוצא,\u0006 הולך, \u0005ולצרכי ביתו אינו עושה],\u0006 \u0003וריקן לביתיה עייל\u0004 \u0005[לביתו\u0006 הוא \u0005נכנס],\u0006 שהרי הדיין מסתכן בענשי שמים אם יטה את הדין, ואינו מקבל שכר על הדין, \u0003ולואי שתהא ביאה\u0004 לביתו \u0003כיציאה\u0004 מן הבית בלא חטא.","ועוד מספרים על רב \u0003כי הוי חזי אמבוהא דספרי אבתריה\u0004 \u0005[כאשר היה רואה שורה של סופרים הולכת אחריו]\u0006 לכבדו, \u0003אמר: \"אם יעלה לשמים שיאו\u0004 וראשו לעב יגיע. \u0003כגללו לנצח יאבד\u0004 רואיו יאמרו איו\u0003\"\u0004 (איוב כ, ו–ז), להזכיר לעצמו שלא להתגאות. וכן \u0003מר זוטרא חסידא\u0004 \u0005[החסיד]\u0006 \u0003כי הוו מכתפי ליה בשבתא דריגלא\u0004 \u0005[כאשר היו נושאים אותו על הכתפיים בשבת שברגל]\u0006 לצורך הדרשה, והיו עושים לו על ידי כך כבוד גדול, \u0003אמר הכי\u0004 \u0005[היה אומר כך]:\u0006 \u0003\"כי לא לעולם חסן ואם נזר לדור ודור\"\u0004 (משלי כז, כד).","\u0003דרש בר קפרא: מנא הא מילתא\u0004 \u0005[מנין דבר זה]\u0006 ש\u0003אמרו רבנן\u0004 \u0005[חכמים]:\u0006 \u0003הוו מתונין בדין\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ו \u0003לא תעלה במעלת\u0004 על מזבחי\" (שמות כ, כו), כלומר, בחפזון יתר, \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 הפסוק הבא אחריו \u0003\"ואלה המשפטים\u0004 אשר תשים לפניהם\u0003\"\u0004 (שמות כא, א). \u0003אמר ר' אליעזר: מניין לדיין שלא יפסע על ראשי עם קודש,\u0004 כלומר, שלא יהלך כשכולם יושבים, שלא יראה כפוסע על ראשיהם — \u0003שנאמר: \"\u0004ו\u0003לא תעלה במעלת\", וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 הכתוב \u0003\"ואלה המשפטים\"\u0004 שאף השופטים מוזהרים על כך.","כיון שהוזכר פסוק זה דורשים אותו לענייננו: נאמר שם \"ואלה המשפטים אשר תשים לפניהם\", ולכאורה הביטוי \u0003\"אשר תשים\"\u0004 אינו ראוי, ו\u0003\"אשר תלמדם\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אמר ר' ירמיה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' חייא בר אבא: אלו כלי הדיינין\u0004 שצריך לשים לפניו כדי להשתמש בהם. \u0003רב הונא, כי הוה נפק לדינא אמר הכי\u0004 \u0005[כאשר היה יוצא לדין היה אומר כך]:\u0006 \u0003אפיקו\u0004 \u0005[הוציאו]\u0006 \u0003לי מאני חנותאי\u0004 \u0005[\u0006את \u0005כלי החנות שלי],\u0006 כלומר, \u0003מקל ורצועה\u0004 להלקות בהם את העבריינים, \u0003ושופרא\u0004 \u0005[ושופר]\u0006 אם יצטרכו להשתמש בו להחרים מישהו, \u0003וסנדלא\u0004 \u0005[וסנדל]\u0006 לצורך חליצה.","ועוד בענין השופטים: נאמר \u0003\"ואצוה את שפטיכם בעת ההיא\u0004 לאמר שמוע בין אחיכם ושפטתם צדק בין איש ובין אחיו ובין גרו\u0003\"\u0004 (דברים א, טז), ו\"צוואה\" לשון זירוז היא, \u0003אמר ר' יוחנן:\u0004 כוונתו, \u0003כנגד מקל ורצועה תהא זריז,\u0004 שלא יחסוך הדיין בעונשים אם סבור הוא שיש בכך משום תועלת לציבור. על מה שנאמר \u0003\"שמע בין אחיכם ושפטתם\", אמר ר' חנינא:\u0004 מכאן \u0003אזהרה לבית דין שלא ישמע דברי בעל דין קודם שיבא בעל דין חבירו,\u0004 שהרי נאמר \"שמוע בין אחיכם\", בלשון רבים, כלומר, כששניהם מצויים יחד, \u0003ו\u0004אף יש כאן \u0003אזהרה לבעל דין שלא יטעים\u0004 (יסביר) \u0003דבריו לדיין קודם שיבא בעל דין חבירו.\u0004 כיצד: \u0003קרי ביה נמי\u0004 \u0005[קרא בו גם כן]\u0006 \u0003\"שמע בין אחיכם\",\u0004 כלומר, כאשר אתה משמיע מה שיש לדיין לשמוע עשה זאת כאשר נמצא גם בעל הדין השני.","\u0003רב כהנא אמר: מהכא\u0004 \u0005[מכאן]\u0006 ראיה לדבר, נאמר: \u0003\"לא תשא\u0004 שמע שוא\u0003\"\u0004 (שמות כג, א), ואנו מפרשים זאת כאילו נאמר \u0003\"לא תשיא\".\u0004","נאמר שם \u0003\"ושפטתם צדק\"\u0004 (דברים א, טז), \u0003אמר ריש לקיש: צדק את הדין,\u0004 כלומר, ברר אותו יפה יפה עד שתהא בטוח שהוא דין צדק, \u0003ואחר כך חתכהו.\u0004 עוד נאמר שם \u0003\"בין איש ובין אחיו ובין גרו\", אמר רב יהודה: אפילו בין בית לעלייה\u0004 (קומה שניה), שצריך לחלק \"בין איש ובין אחיו\" הבאים לחלק ירושת אביהם, מי יקבל את הבית ומי יקבל את העלייה.","\u0003\"ובין גרו\"\u0004 (המובן כאן כמשמעו מגורים), \u0003אמר רב יהודה: אפילו בין תנור לכירים\u0004 שאם צריכים שניים להתחלק, וזה אמור לקבל תנור וזה לקבל כיריים — דין רציני הוא, וצריך לדון בו.","על הכתוב שם \u0003\"לא תכירו פנים במשפט\u0004 כקטן כגדול תשמעון לא תגורו מפני איש, כי המשפט לאלהים הוא והדבר אשר יקשה מכם תקריבון אלי ושמעתיו\u0003\"\u0004 (דברים א, יז), \u0003ר' יהודה אומר: לא תכירהו\u0004 את האיש שהוא ידידך לשאת לו פנים בדין. \u0003ר' אלעזר אומר: לא תנכרהו\u0004 אם הוא שונאך, אלא תנהג כאילו לא הכרת אותו מעולם.","מסופר: \u0003אושפיזכניה\u0004 \u0005[בעל בית מלונו]\u0006 של \u0003רב אתא לקמיה לדינא\u0004 \u0005[בא לפניו לדין].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003לאו אושפיזכני את\u0004 \u0005[האם לא בעל בית מלוני אתה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם: \u0003דינא אית\u0004 \u0005[דין יש]\u0006 \u0003לי\u0004 ורצוני להידון בפניך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב:"],["\u0003פסילנא\u0004 \u0005[פסול אני]\u0006 \u0003לך לדינא\u0004 \u0005[לדין],\u0006 שהרי אני מכיר אותך ושמא תהא דעתי נוטה לצדד בך שלא כדין. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לרב כהנא\u0004 שהיה תלמיד חבר שלו: \u0003פוק דייניה\u0004 \u0005[צא\u0006 ו\u0005דון אותו]\u0006 אתה. \u0003חזייה דהוה קא גאיס ביה\u0004 \u0005[ראהו\u0006 רב כהנא \u0005שגסה רוחו בו]\u0006 כיון שהוא סומך על רב, וסבור שמשום כך יתייחס אליו רב כהנא באופן מיוחד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: \u0003אי צייתא\u0004 \u0005[אם תציית]\u0006 — \u0003צייתא\u0004 \u0005[תציית],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003מפיקנא\u0004 \u0005[אוציא]\u0006 \u0003לך\u0004 את \u0003רב מאונך\u0004 \u0005[מאוזניך],\u0006 כלומר, אדון אותך בעונש קשה ותדע שאין אתה יכול לסמוך עליו.","נאמר שם: \u0003\"כקטן כגדל תשמעון\"\u0004 (דברים א, יז), \u0003אמר ריש לקיש: שיהא חביב עליך דין של פרוטה כדין של מאה מנה.\u0004 שואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו הלכה\u0005]\u0006 נאמר דבר זה? \u0003אילימא לעיוני ביה ומיפסקיה\u0004 \u0005[אם תאמר\u0006 לענין \u0005לעיין בו ולפסוק בו],\u0006 \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 וכי עוול בפרוטה אינו עוול? \u0003אלא לאקדומיה\u0004 \u0005[להקדימו],\u0006 שאין הדיין יכול לומר שדין זה של פרוטה אינו חשוב וידחה דין זה בפרוטה, לאחר שידון בסכסוך בסכום גדול.","עוד נאמר שם \u0003\"לא תגורו מפני איש\", אמר ר' חנן:\u0004 מפסוק זה למדנו ש\u0003אל תכניס דבריך\u0004 (תשתוק) \u0003מפני איש\u0004 אלא אמור מה שהנך צריך לומר. על הנאמר \u0003\"כי המשפט לאלהים הוא\"\u0004 (דברים א, יז), \u0003אמר ר' חמא בר' חנינא,\u0004 כך יש להבין: \u0003אמר הקדוש ברוך הוא, לא דיין לרשעים ש\u0004הם דנים דין מעוות ו\u0003נוטלין מזה ממון ונותנים לזה שלא כדין, אלא שמטריחין אותי להחזיר ממון לבעליו,\u0004 והוא שנאמר \"כי המשפט לאלהים הוא\", שאם אין הדיינים פוסקים כראוי צריך הקדוש ברוך הוא לשנות את סדר העולם, עד שיוחזר הממון לבעליו.","על הנאמר \u0003\"והדבר אשר יקשה מכם\u0004 תקריבון אלי ושמעתיו\u0003\"\u0004 (דברים א, יז), \u0003אמר ר' חנינא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יאשיה: על דבר זה נענש משה,\u0004 שהיה בכך כעין יוהרה, ועונשו, \u0003שנאמר\u0004 כאשר באו אליו בנות צלפחד, ובוודאי לאחר ששאלו לכל בתי הדין האחרים: \u0003\"ויקרב משה את משפטן לפני ה' \"\u0004(במדבר כז, ה), שדבר שבא אליו לא ידע לענות בעצמו. \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הסברה זו, \u0003רב נחמן בר יצחק: מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"ואשמיעכם\"?\u0004 הרי לא אמר משה שהוא עצמו יפתור את כל הקשיים, אלא \u0003\"ושמעתיו\" כתיב\u0004 \u0005[נאמר],\u0006 והכוונה: \u0003אי גמירנא\u0004 \u0005[אם למדתי]\u0006 — \u0003גמירנא\u0004 \u0005[למדתי]\u0006 ואומר מה שאני יודע, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003אזלינא וגמירנא\u0004 \u0005[הולך אני ולומד]\u0006 מפי השכינה, ואין כאן איפוא כל יוהרה.","\u0003אלא\u0004 אם יש ללמוד הוראה מוסרית מדין בנות צלפחד, הרי היא \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003ראויה\u0004 היתה \u0003פרשת נחלות\u0004 (במדבר כז, א–יא) \u0003שתיכתב על ידי משה רבינו\u0004 בנוסח כל התורה (\"וידבר ה' אל משה\"), \u0003אלא שזכו בנות צלפחד ונכתב על ידן\u0004 בשל השאלה ששאלו ממשה. וכן \u0003ראויה היתה פרשת מקושש\u0004 (במדבר טו, לב–לג) \u0003שתיכתב על ידי משה רבינו, אלא שנתחייב מקושש ונכתבה על ידו, ללמדך שמגלגלין חובה על ידי חייב, וזכות על ידי זכאי.\u0004","ועוד נדרשים הפסוקים המדברים במינוי השופטים. \u0003כתיב\u0004 \u0005[נאמר]\u0006 שם: \u0003\"ואצוה את שפטיכם בעת ההיא\"\u0004 (דברים א, טז), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שם: \u0003\"ואצוה אתכם בעת ההוא\u0004 את כל הדברים אשר תעשון\u0003\"\u0004 (דברים א, יח), \u0003אמר ר' אלעזר אמר ר' שמלאי:\u0004 שני הפסוקים הללו משלימים זה את זה, מצד אחד \u0003אזהרה לציבור שתהא אימת דיין עליהן\u0004 ויקבלו מרותו, והוא הציווי לציבור, \u0003ואזהרה לדיין שיסבול את הציבור\u0004 ואת הטורח שהוא מטריח אותו. שאלו: \u0003עד כמה\u0004 חייב הדיין לסבול טרחת הכלל? \u0003אמר ר' חנן ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' שבתאי,\u0004 כפי שנאמר במשה: \u0003\"כאשר ישא האמן את הינק\"\u0004 (במדבר יא, יב).","אגב יישוב קושי זה, מביאים גם פתרון לסתירה אחרת בלשון הכתובים, \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד בדברי משה ליהושע: \u0003\"כי אתה תבוא\u0004 את העם הזה אל הארץ אשר נשבע ה' לאבותם לתת להם\u0003\"\u0004 (דברים לא, ז), והלשון \"תבוא\" מורה על כך שאתה תבוא עמהם כשווה להם, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 ליהושע גם כן \u0003\"כי אתה תביא\u0004 את בני ישראל אל הארץ אשר נשבעתי להם ואנוכי אהיה עמך\u0003\"\u0004 (דברים לא, כג), והלשון \"תביא\" מורה על כך שתנהוג בהם שררה! \u0003אמר ר' יוחנן:\u0004 כך יש להבין את ההבדל, \u0003אמר לו משה ליהושע: אתה והזקנים שבדור עמהם,\u0004 ועל זה נאמר \"אתה תבוא את העם\", במשמעות \"עם העם\", כלומר אתה תבוא לארץ כמנהיג, ועמך ראשי העם האחרים. \u0003אמר לו הקדוש ברוך הוא\u0004 ליהושע: לא כן, אלא \u0003טול מקל והך על קדקדם,\u0004 ואין אתה צריך להתחשב כלל בדעתם, כי צריך שיהא \u0003דבר\u0004 (מנהיג) \u0003אחד לדור, ואין שני דברין לדור,\u0004 ובסופו של דבר צריכה להיות סמכות עליונה בידי אדם אחד.","לאחר דברי האגדה המרובים שהיו אף הם מענין הדין והדיינים, שבים לבירור לשון המשנה והלכותיה. \u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003זימון בשלשה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"זימון\"\u0004 זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא ל\u0003ברכת זימון\u0004 שמברכים לפני ברכת המזון, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 ברייתא יותר מפורטת\u0005]\u0006 האומרת: \u0003זימון וברכת זימון בשלשה.\u0004 משמע שהם שני דברים נפרדים! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שבאותה ברייתא \u0003פרושי קמפרש\u0004 \u0005[מפרש הוא]\u0006 ומפרט דברי עצמו, וכי יש להבין בה כך: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"זימון\"?\u0004 — \u0003ברכת זימון, ו\u0004אולם \u0003התניא\u0004 \u0005[הרי שנינו\u0006 בברייתא נוספת\u0005]:\u0006 \u0003זימון בשלשה, ברכת זימון בשלשה.\u0004","\u0003אלא\u0004 יש לומר כי \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 \u0003\"זימון\"?\u0004 — \u0003אזמוני\u0004 \u0005[הזמנה]\u0006 \u0003לדין. כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר רבא:\u0004 \u0003הני בי תלתא דייני דיתבי\u0004 \u0005[שלושה דיינים היושבים]\u0006 ומכינים עצמם לדין, \u0003ואזיל שליחא דבי דינא\u0004 \u0005[והלך שליח בית הדין]\u0006 \u0003ו\u0004\u0003אמר\u0004 לאחד הצדדים \u0003מפומא דחד\u0004 \u0005[מפיו,\u0006 בשמו, \u0005של אחד\u0006 הדיינים שהוא מזמינו\u0005]\u0006 — \u0003לא\u0004 \u0003אמר כלום, עד ד\u0004\u0003אמר משמיה דכולהו\u0004 \u0005[שיאמר בשם כולם]\u0006 שכולם מזמינים אותו, והוא שאמרו כי אף ההזמנה לבית דין היא בשלושה. ומעירים: \u0003הני מילי\u0004 \u0005[הדברים הללו]\u0006 אמורים בזמן שנעשה הדבר ש\u0003לא יומא דדינא\u0004 \u0005[ביום\u0006 הקבוע \u0005לדין],\u0006 \u0003אבל\u0004 אם נשלח \u0003ביומא דדינא\u0004 \u0005[ביום\u0006 הקבוע \u0005לדין]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 כל הבדל. וגם אם מזמין בשם דיין אחד הכל יודעים שכוונתו למושב בית דין, וחייבים לבוא.","ועוד בביאור המשנה, שנינו כי \u0003תשלומי כפל\u0004 וקנסות אחרים נידונים בשלושה. \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר רב חסדא לרב נחמן בר יעקב\u0004 שאלה: \u0003ילמדנו רבינו, דיני קנסות בכמה\u0004 דיינים? ושואלים: \u0003מאי קמיבעיא ליה\u0004 \u0005[מה נסתפק לו]?\u0006 \u0003הא אנן תנן\u0004 \u0005[הרי אנחנו שנינו\u0006 במשנה מפורשת\u0005]\u0006 כי דיני קנסות נידונים \u0003בשלשה! אלא\u0004 בעיית \u0003יחיד מומחה קמיבעיא ליה\u0004 \u0005[נסתפקה לו]\u0006 האם \u0003דאין\u0004 \u0005[דן\u0006 הוא\u0005]\u0006 \u0003דיני קנסות, או לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 כבר \u0003תניתוה\u0004 \u0005[למדתם אותה],\u0006 ששנינו במשנה: \u0003תשלומי כפל ותשלומי ארבעה וחמשה בשלשה.\u0004 ונברר: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003\"שלשה\"\u0004 אלו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שלשה הדיוטות\u0004 — \u0003ה\u0004\u0003אמר אבוה דאבוך\u0004 \u0003משמיה\u0004 \u0005[הרי אמר אבי אביך משמו]\u0006 של \u0003רב:\u0004 \u0003אפילו עשרה והן הדיוטות\u0004 — \u0003פסולין לדיני קנסות, אלא\u0004 ודאי מדובר ב\u0003מומחין, ו\u0004בכל זאת \u0003קאמר\u0004 \u0005[אמר]\u0006 במשנה \u0003\"שלשה\"\u0004 — משמע שיחיד, אפילו הוא מומחה, פסול לדיני קנסות.","במשנה נחלקו ביחס לדינו של המוציא שם רע, והנה ברור שבעל המביא עדים שאשתו זנתה בהיותה מאורסת לו — מאשימה בזנות חמורה שעונשה סקילה, וגם אם יוזמו העדים ויתברר שהיתה זו עלילת שוא הבעל יידון בקנס ובמלקות, והעדים הזוממים ידונו למוות. ואולם בהכרח יש לומר שמדובר כאן בתביעה קטנה יותר, שהבעל טוען שאשתו לא היתה בתולה כשנשאה, והוא תובע פיצוי ממוני מסויים, שלדברי ר' מאיר דינו בשלושה, \u0003וחכמים אומרים מוציא שם רע בעשרים ושלשה\u0004 דיינים. וטעמם של החכמים, שכיון שיש בדין זה גם דיני נפשות — הרי הוא בעשרים ושלושה.","ושואלים: \u0003וכי יש בו דיני נפשות מאי הוי\u0004 \u0005[מה יש]?\u0006 שהרי במקרה שאנו דנים בו ודאי שבית הדין עוסק רק בתביעת ממון ולא עוד, ואם כן מה חשיבות יש לעובדה שיש בדין זה גם דיני נפשות?","\u0003אמר עולא: בחוששין ללעז קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 והשאלה היא: האם חוששים אנו שמתוך שבית הדין יושב לדין בטענת הבעל שהאשה שנשא לא היתה בתולה, מגיע אותו ענין לפרסום, ואולי יבואו עדים ויעידו כי אכן זנתה האשה בהיותה ארוסה, ואם כן יש כאן לא רק תביעת ממון אלא האשמה שבדיני נפשות. \u0003ר' מאיר סבר: אין חוששין ללעז,\u0004 וכיון שלבית הדין יש לדון בתביעת ממונות בלבד די בשלושה דיינים, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 \u0003חוששין ללעז\u0004 שמא יבואו עדים, ומכינים מראש בית דין של עשרים ושלושה.","\u0003רבא אמר\u0004 הסבר אחר למחלוקת: \u0003כולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003ללעז לא חיישינן\u0004 \u0005[חוששים אנו],\u0006 \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003חוששין לכבודן של ראשונים קמיפלגי\u0004 \u0005[חלוקים].\u0006 \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]?\u0006 — במקרה \u0003כגון דאיכניף בי עשרין ותלתא למידן\u0004 \u0005[שהתאספו עשרים ושלושה דיינים לדון]\u0006 \u0003דיני נפשות, ואיבדור\u0004 \u0005[והתפזרו],\u0006 משום שהתברר שאין ביד הבעל או האשה עדויות מכריעות לכאן או לכאן. \u0003ו\u0004\u0003אמר להו\u0004 \u0005[להם]\u0006 הבעל לדיינים הנותרים: \u0003דיינו\u0004 \u0005[דונו]\u0006 \u0003לי מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003דיני ממונות,\u0004 שהרי גם אם אינו יכול להוכיח שהאשה זנתה, מכל מקום הריהו טוען שלא היתה בתולה, והוא תובע תביעת ממון להוריד מסכום הכתובה הקבוע לבתולה שהוא מאתים דינר, ולהעמידו על מאה דינר שנותנים לאשה שנישאה כשאינה בתולה. חכמים אומרים שבמקרה כזה חוששים לכבודם של הדיינים הראשונים, ויש לאסוף מחדש את בית הדין שדן כבר בדבר. ולדעת ר' מאיר אפשר לדון בשלושה, ואין בכך פגיעה בכבוד שאר הדיינים שנתפזרו."],["\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על הסבר זה ממה ששנינו בתוספתא, \u0003וחכמים אומרים: תבעו ממון\u0004 בתביעה זו — דנים \u0003בשלשה, תבעו נפשות\u0004 — \u0003בעשרים ושלשה.\u0004 ומפרטים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבא,\u0004 אם \u0003תבעו ממון תחלה\u0004 — דנים הכל \u0003בשלשה,\u0004 שהרי לדעתו מתחילה היו רק שלושה דיינים, ואין איפוא חשש לפגיעה בכבודם של ראשונים, אם \u0003תבעו נפשות תחלה\u0004 ונתאספו לשם כך עשרים ושלושה, \u0003אפילו\u0004 אם דנים אחר כך בתביעת \u0003ממון\u0004 — הרי זה \u0003בעשרים ושלשה\u0004 מפני כבוד הראשונים. \u0003אלא ל\u0004שיטת \u0003עולא קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005],\u0006 שהרי הוא חושש ללעז!","\u0003אמר רבא: אני וארי שבחבורה תרגימנא\u0004 \u0005[הסברנו]\u0006 את הענין אף לשיטת עולא. ומעירים: \u0003ומנו\u0004 \u0005[ומיהו]\u0006 \"ארי שבחבורה\" זה? — \u0003רב חייא בר אבין.\u0004 ומהו ההסבר? — \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 כגון במקרה \u0003שהביא הבעל עדים שזינתה\u0004 האשה, והיתה זו איפוא תביעת נפשות הנידונה בעשרים ושלושה, \u0003והביא האב עדים והזימום לעדי הבעל,\u0004 ואם כן הבעל חייב לשלם קנס מאה כסף (ואף לוקה) והעדים נידונים למוות. ואם \u0003בא\u0004 האב \u0003לגבות ממון מבעל\u0004 — הרי הוא גובה \u0003בשלשה\u0004 דיינים, \u0003ובמקום נפשות\u0004 אם באים לתבוע את העדים הזוממים — הם נידונים \u0003בעשרים ושלשה,\u0004 וזהו איפוא הסבר הדברים שבתוספתא ואינו קשור למחלוקת שבמשנה.","\u0003אביי אמר\u0004 הסבר אחר למחלוקת ר' מאיר וחכמים. ברור לו כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 גם לר' מאיר וגם לחכמים \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003ללעז,\u0004 שיבואו אנשים וישמעו, ולכן גם אם פתח בתביעת ממון צריך לאסוף עשרים ושלושה. \u0003ו\u0004אף חוששים אנו \u0003משום כבודן של ראשונים\u0004 שאם התחילו בעשרים ושלושה, אין לפזרם גם אם התביעה הצטמצמה להיות תביעת ממון בלבד. אלא \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003כגון דאתרו\u0004 \u0005[שהתרו]\u0006 \u0003בה,\u0004 באשה, לפני שזנתה, התראה \u0003סתם,\u0004 ולא פירשו לה מה יהא ענשה בדיוק אם תעבור ותזנה.","\u0003והאי\u0004 \u0005[ו\u0006דבר \u0005זה]\u0006 כשיטת \u0003תנא\u0004 זה \u0003הוא,\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ושאר כל חייבי מיתות שבתורה\u0004 חוץ ממסית \u0003אין ממיתין אותם אלא בעדה\u0004 (בבית דין) \u0003ועדים, והתראה\u0004 מוקדמת לחטא, \u0003ועד שיודיעוהו\u0004 לפני המעשה \u0003שהוא חייב מיתה בבית דין.\u0004","\u0003ר' יהודה אומר: עד שיודיעוהו באיזה מיתה הוא נהרג.\u0004 ואם לא הודיעוהו באיזו מיתה ייהרג — אינו נהרג. ור' מאיר סבור כר' יהודה, שמי שלא היתרו בו באיזו מיתה ייהרג — אינו חייב מיתה עוד. ולכן אם התברר בתחילת הדין כי לא היתה התראה מלאה, ואם ישבו שם רק שלושה לעיין בדבר — אין צורך עוד לאסוף בית דין שלם, ואז יהא דין מוציא שם רע במקרה זה בשלושה. וחכמים שסבורים שגם אם לא אמרו לו באיזו מיתה נהרג הרי זו התראה ראויה, ולכן דינה של האשה בעשרים ושלושה.","\u0003רב פפא אמר\u0004 תירוץ שונה במקצת, שאף הוא מקבל את ביקורתו של אביי, אלא שלדעתו \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003באשה חבירה\u0004 (שיודעת תורה) \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003וקמיפלגי בפלוגתא\u0004 \u0005[והם חלוקים ב\u0006אותה \u0005מחלוקת]\u0006 של \u0003ר' יוסי בר יהודה ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי בר יהודה אומר: חבר\u0004 (תלמיד חכם) \u0003אין צריך התראה\u0004 לפני שהוא עובר עבירה, ואם העידו עדים שעבר עבירה הראויה לעונשי גוף — מענישים אותו אף בלא התראה מוקדמת, \u0003לפי שלא ניתנה\u0004 החובה של \u0003התראה אלא להבחין בין שוגג למזיד\u0004 שמא אותו אדם אינו יודע שעבירה היא בידו, ולכן תלמיד חכם אינו זקוק להתראה וחייב. ור' מאיר סבור כדברי חכמים, שאף חבר צריך התראה, וכיון שלא התרו באותה אשה, ממילא אין כאן מקום לדין נפשות אלא דין ממונות בלבד. וחכמים סבורים כר' יוסי בר' יהודה, שאף במקרה זה חייבת מיתה, ולכן יש צורך בעשרים ושלושה.","\u0003רב אשי אמר\u0004 הסבר אחר, שמדובר במקרה מיוחד, \u0003כגון\u0004"],["\u0003דאתרו ביה\u0004 \u0005[שהתרו בה]\u0006 שהיא חייבת \u0003מלקות, ולא אתרו ביה קטלא\u0004 \u0005[התרו בה\u0006 שהיא חייבת \u0005מיתה]\u0006 ובודאי אין דנים אותה למיתה, אלא במלקות.","\u0003וקמיפלגי בפלוגתא\u0004 \u0005[וחלוקים ב\u0006אותה \u0005מחלוקת]\u0006 של \u0003ר' ישמעאל ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003מכות בשלשה, משום\u0004 (בשם) \u0003ר' ישמעאל אמרו: בעשרים ושלשה,\u0004 והשאלה במקרה זה קשורה במחלוקת במכות בכלל, האם כדי לחייב בהן אדם די בשלושה דיינים (כחכמים וכדעת ר' מאיר), או בעשרים ושלושה כר' ישמעאל.","\u0003רבינא אמר:\u0004 כאן מדובר באופן אחר \u0003כגון שנמצא אחד מן העדים\u0004 שהעידו לרעתה \u0003קרוב או פסול,\u0004 והרי הוא פסול לעדות, אבל יש עוד שני עדים כשרים להעיד, \u0003וקמיפלגי בפלוגתא\u0004 \u0005[וחלוקים הם במחלוקת]\u0006 של \u0003ר' יוסי ורבי, אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' עקיבא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' עקיבא אומר:\u0004 מה שנאמר בתורה \"שנים עדים או שלושה עדים\", \u0003לא בא\u0004 העד ה\u0003שלישי\u0004 הזה \u0003אלא להחמיר עליו, לעשות\u0004 את \u0003דינו כיוצא באלו\u0004 כמו העדים האחרים, ואם היו העדים זוממים — כולם נהרגים, ואין העד השלישי יכול לומר שלא עשה בעצם דבר, שהרי העדות כבר נגמרה על ידי שני העדים הראשונים.","ומכאן למד ר' עקיבא הוראה כללית: \u0003אם כך ענש הכתוב את הניטפל לעוברי עבירה\u0004 שיהא דינו \u0003כעוברי עבירה\u0004 העיקריים, \u0003על אחת כמה וכמה שישלם שכר את הניטפל לעושה מצוה כעושה מצוה,\u0004 שהרי מידה טובה מרובה ממידת הפורענות.","ועוד יש ללמוד מהשוואה זו של שנים ושלושה: \u0003ומה שנים\u0004 אם \u0003נמצא אחד מהן קרוב או פסול\u0004 — הרי \u0003עדותן בטלה,\u0004 שהרי נותר רק עד כשר אחד. \u0003אף שלשה\u0004 עדים, אם \u0003נמצא אחד מהם קרוב או פסול\u0004 — \u0003עדותן בטלה\u0004 כולה, שכולם נחשבים כעדות אחת, ואם נפסלה מקצתה — נפסלה כולה. \u0003ומניין שאפילו\u0004 אם היו \u0003מאה\u0004 עדים כך דינם? — \u0003תלמוד לומר: \"עדים\",\u0004 בלי צמצום מספרם.","עד כאן שיטת ר' עקיבא, ובכך נחלקו תנאים, \u0003אמר ר' יוסי: במה דברים אמורים\u0004 שאם נמצא אחד העדים קרוב או פסול בטלה כל העדות — \u0003בדיני נפשות, אבל בדיני ממונות תתקיים\u0004 ה\u0003עדות בשאר\u0004 העדים הכשרים. \u0003רבי אומר: אחד דיני ממונות ואחד דיני נפשות,\u0004 אם אחד מהם היה קרוב או פסול — כל העדות פסולה. ומסייגים הלכה זו: \u0003ואימתי\u0004 אומרים שעד פסול אחד פוסל את כל שאר העדים הכשרים? \u0003בזמן שהתרו בהן\u0004 בעוברי העבירה גם העדים הפסולים, וגילו דעתם שהם מתכוונים להעיד, \u0003אבל בזמן שלא התרו בהן\u0004 העדים הפסולים,"],["\u0003מה יעשו שני אחים ו\u0004עוד אדם \u0003אחד, שראו באחד שהרג את הנפש,\u0004 שהרי אם עצם הראיה פוסלת אותם להעיד הרי שני האחים שהם קרובים זה לזה פסולים להעיד ובטלה כל העדות, אלא אחד מן האחים והאחר שאינו קרוב יתרו בעבריין, והאח השני שלא התרה איננו מצטרף. ולענין המחלוקת במוציא שם רע, מדובר באופן שהעידו שלושה עדים ואחד מהם היה פסול, ולא התרו בה אלא הכשרים, לדעת רבי — התראה היא זו, ויש לדונה בעשרים ושלושה, וכן סברו חכמים. ולדעת ר' יוסי, כיון שהיה שם עד פסול — בטלה העדות, ואין כאן אלא דין ממונות שבשלושה, וכן סבר ר' מאיר.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר למחלוקת ר' מאיר וחכמים, \u0003כגון שהתרו בה אחרים\u0004 שהיו במקום העבירה \u0003ולא התרו בה עדים\u0004 המעידים בה עצמם. \u0003וקמיפלגי בפלוגתא\u0004 \u0005[ונחלקו במחלוקת]\u0006 של \u0003ר' יוסי ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יוסי אומר: לעולם אינו נהרג עד שיהו פי שני עדיו\u0004 המעידים בפני בית דין הם ה\u0003מתרין בו, שנאמר: \"על פי שנים עדים\u0004 או שלושה עדים יומת המת","\u0003\"\u0004(דברים יז, ו), ר' מאיר סבור כר' יוסי, וכיון שלא התרו בו העדים יש כאן רק דין ממונות בשלושה. וחכמים במשנתנו סבורים כחכמים החולקים על ר' יוסי, ולכן יש כאן מקום לדיני נפשות. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר למחלוקת: מדובר כאן במקרה \u0003כגון דאיתכחוש\u0004 \u0005[שהוכחשו\u0006 העדים\u0005]\u0006 \u0003בבדיקות\u0004 לגבי פרטי המעשה \u0003ולא איתכחוש\u0004 \u0005[הוכחשו]\u0006 \u0003בחקירות\u0004 שהן השאלות היסודיות ביחס לזמן ומקום המעשה.","ונחלקו אם יש עוד מקום לדיני נפשות, \u0003וקמיפלגי בפלוגתא\u0004 \u0005[ונחלקו במחלוקתם]\u0006 של \u0003בן זכאי ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מעשה ובדק בן זכאי בעוקצי תאנים,\u0004 שחקר את העדים ביחס לעוקצים (הקצוות, חיבור התאנים לעץ) שהוזכרו תאנים בקשר למעשה שעליו מעידים, וכיון שמצא סתירה בדברי העדים בענין זה רצה לפסול את כל עדותם. לדעת ר' מאיר הלכה כבן זכאי, וכיון שנמצאה אף כאן בעדות על אשה זו סתירה כלשהי בין העדים — שוב אין כאן דיני נפשות. ולדעת חכמים אין סתירה כגון זו פוסלת עדות, ועדיין יש כאן דיני נפשות.","כיון שעסקנו בהלכה זו בענין מוציא שם רע על אשתו דנים בצדדים אחרים של אותה בעיה. \u0003אמר רב יוסף:\u0004 אם \u0003הביא הבעל עדים שזינתה\u0004 האשה, \u0003והביא האב עדים והזימום לעדי הבעל, עדי הבעל נהרגין\u0004 כדין עד זומם שעושים לו כאשר זמם לעשות. אבל \u0003אין משלמין ממון,\u0004 אף שבעדות זו היו גורמים גם כן שתפסיד האשה את דמי כתובתה. והטעם הוא, לפי הכלל שאין דנים אדם בשני עונשים, על אותה עבירה עצמה, וידון בעונש החמור יותר.","ואולם אם \u0003חזר והביא הבעל עדים והזימום לעדי האב\u0004 (אותם שבאו להזים את העדים הראשונים), הרי במקרה זה \u0003עדי האב נהרגין\u0004 שהרי התכוונו להרוג בעדותם את העדים הראשונים, \u0003ו\u0004גם \u0003משלמין ממון\u0004 לבעל, שאם היתה עדותם מתקבלת היה הבעל צריך לשלם קנס של מאה כסף. ומדוע נענשים אלה בשני עונשים, משום שהם משלמים \u0003ממון לזה\u0004 לבעל שנתחייבו לו מצד אחד, \u0003ונפשות לזה\u0004 לעדים. שכיון שחטאו כנגד שני אנשים שונים אין עונש שניתן עליהם בשל חטא אחד פוטרם מעונש על שרצו לפגוע גם באדם אחר. דברי רב יוסף אלה, שבהם הראה שיש הבדל בין שתי עדויות שהן כמעט זהות, מזכירים הלכה אחרת של רב יוסף בדיני עדות.","ש\u0003אמר רב יוסף:\u0004 העיד אדם ש\u0003פלוני רבעו\u0004 במשכב זכור \u0003לאונסו,\u0004 הרי \u0003הוא\u0004 הנאנס \u0003ו\u0004עוד עד \u0003אחר\u0004 שראה את הדבר \u0003מצטרפין\u0004 להעיד עליו בפני בית דין, כדי \u0003להרגו\u0004 לחוטא על־פי עדותן, כדין תורה המחייב מיתה על משכב זכור.","ואולם אם העיד אותו אדם שפלוני רבע אותו \u0003לרצונו,\u0004 שגם הוא השתתף בדבר מרצונו, גם אם עד אחר מעיד על המעשה, הרי השותף לעבירה \u0003רשע הוא,\u0004 שהרי העיד על עצמו שעבר עבירה חמורה זו מרצונו, \u0003והתורה אמרה \"אל תשת... רשע... עד\"\u0004 (בשינוי קצת מלשון הכתוב \"אל תשת ידך עם רשע להיות עד חמס\". שמות כג, א). ואילו \u0003רבא אמר:\u0004 לענין עדות הרי \u0003אדם קרוב אצל עצמו,\u0004 וכשם שאין מקבלים עדותם של שאר קרובים, כך אין ערך לעדות שאדם מעיד על עצמו. \u0003ו\u0004משום כך \u0003אין אדם משים עצמו רשע,\u0004 שאין אדם יכול להעיד כנגד עצמו, כשם שאינו יכול להעיד לטובת עצמו, ואין עדותו מענין זה נחשבת. ומשום כך העדות שהעיד שפלוני רבע אותו, כיון שמעיד באחר — עדות היא, ומתקבלת. אבל אותו חלק בעדות שהוא טוען שעשה זאת מרצונו, כיון שעל כך אין עדים — אין עדות זו מתקבלת, ואין פוסלים אותו בהודאת פיו.","בדומה לכך \u0003אמר רבא,\u0004 האומר:"],["\u0003פלוני בא על אשתי, הוא ו\u0004עוד עד \u0003אחר מצטרפין להורגו,\u0004 את אותו פלוני, \u0003אבל לא\u0004 מצטרפים \u0003להורגה\u0004 את האשה, אף שהם מעידים שגם האשה עברה מרצונה. שהרי כיון שהוא קרוב של אשתו איננו יכול להעיד עליה, לא לטוב ולא לרע.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בהלכה אחרונה זו? — \u0003דמפלגינן בדיבורא\u0004 \u0005[שאנו מחלקים ב\u0006תוך \u0005הדיבור]\u0006 ואומרים שבמקרים מסויימים אנו מקבלים רק חלק מן הדיבור (העדות) ולא את העדות כולה. ולענייננו איננו מקבלים חלק העדות שבו אדם מפליל את עצמו, ואולם \u0003היינו הך\u0004 \u0005[זהו זה\u0006 אותו דבר\u0005]\u0006 שכבר אמר רבא הלכה זו באדם המעיד על עצמו! ומשיבים: יש מקום לחלק, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003אדם קרוב אצל עצמו\u0004 — \u0003אמרינן\u0004 \u0005[אומרים אנו],\u0006 ואיננו מקבלים את עדותו, ולכן מחלקים בתוך דיבורו בין החלק שהוא מעיד על עצמו ובין החלק שהוא מעיד על אחרים, אבל שנאמר שאדם קרוב \u0003אצל אשתו,\u0004 עד כדי כך — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 ולא נחלק בתוך דיבורו, אלא נקבל הכל או לא נקבל העדות כלל, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף בזה מחלקים בדיבור.","\u0003ו\u0004עוד \u0003אמר רבא:\u0004 העידו שנים ש\u0003פלוני בא על נערה המאורסה\u0004 ולא העידו מי היתה אותה נערה, \u0003והוזמו\u0004 עדים אלה — הרי הם \u0003נהרגין\u0004 משום שביקשו לחייבו מיתה, \u0003ו\u0004אולם \u0003אין משלמין ממון,\u0004 אף שנערה שהעידו עליה שזנתה הפסידה את כתובתה, ואולם מאחר שלא הזכירו שם אשה מסויימת, ממילא אין עדות זו נוגעת בה, ולא הפסידוה. ואולם אם אמרו: שפלוני בא על נערה המאורסה שהיא \u0003בתו של פלוני, והוזמו\u0004 — הרי הם \u0003נהרגין, ומשלמין ממון. ממון לזה,\u0004 לנערה שרצו להפסידה כתובתה, \u0003ונפשות לזה,\u0004 לאיש שהאשימו אותו בעבירה שעונשה מיתה.","\u0003ו\u0004עוד \u0003אמר רבא:\u0004 אם באו עדים והעידו כי \u0003פלוני רבע השור,\u0004 וכיון שכך הרי הוא חייב מיתה משום \"כל שוכב עם בהמה\" (שמות כב, יח), ואף את השור הורגים, \u0003והוזמו\u0004 — \u0003נהרגין\u0004 על שזממו להרוג את האיש, אבל \u0003אין משלמין ממון,\u0004 שהרי לא אמרו של מי היה שור זה. ואולם אם אמרו שהיה זה \u0003שורו של\u0004 אדם \u0003פלוני, והוזמו\u0004 — \u0003נהרגין ומשלמין ממון, ממון לזה,\u0004 לבעל השור, \u0003ונפשות לזה.\u0004","ושואלים: \u0003הא תו\u0004 \u0005[זה עוד]\u0006 \u0003למה לי? היינו הך\u0004 \u0005[זהו זה\u0006 אותו דבר\u0005]\u0006 כענין עדות נערה המאורסה. ומשיבים: \u0003משום דקא בעי בעיא עילויה\u0004 \u0005[שהוא שואל שאלה עליה],\u0006 שאמנם בדברים אלה אין חידוש, ואולם הם משמשים לו בסיס לשאלה מורכבת יותר. \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רבא:\u0004 אם העיד אדם \u0003\"פלוני רבע שורי\" מהו?\u0004 האם מקבלים את עדותו במלואה? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003אדם קרוב אצל עצמו, ואין אדם קרוב אצל ממונו,\u0004 ומשום כך נקבל את העדות לא רק לגבי האיש שרבע את השור אלא גם לגבי הבהמה, \u0003או דילמא אמרינן\u0004 \u0005[שמא אומרים אנו]:\u0006 \u0003אדם קרוב\u0004 גם \u0003אצל ממונו\u0004 וחלק זה של עדותו אינו מתקבל? \u0003בתר דבעיא הדר פשטה\u0004 \u0005[אחרי ששאל\u0006 את השאלה הזו \u0005חזר\u0006 ו\u0005פתרה]:\u0006 \u0003אדם קרוב אצל עצמו, ואין אדם קרוב אצל ממונו,\u0004 ויכול אדם להעיד כנגד בהמתו, ואינו אלא כדיני ממונות.","במשנתנו שנינו כי דיני \u0003מכות בשלשה.\u0004 ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003אמר רב הונא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"כי יהיה ריב בין אנשים ונגשו אל המשפט ושפטום והצדיקו את הצדיק והרשיעו את הרשע. והיה אם בן הכות הרשע והפילו השופט והכהו לפניו כדי רשעתו במספר\" (דברים כה, א–ב), \u0003\"ושפטום\"\u0004 — \u0003שנים,\u0004 משמע מלשון הרבים שיש כאן לפחות שני שופטים, \u0003ו\u0004כיון ש\u0003אין בית דין שקול, מוסיפין עליהם עוד אחד\u0004 — \u0003הרי כאן שלשה.\u0004","ושואלים: \u0003אלא מעתה,\u0004 אם מונה אתה כמנין כנויי הרבים הכתובים שם, נוסיף גם \u0003\"והצדיקו\u0004 את הצדיק \u0003\"\u0004— הרי \u0003שנים, \"והרשיעו\u0004 את הרשע\" — עוד \u0003שנים,\u0004 הרי כאן שישה דיינים, ועוד אחד להכריע ביניהם — \u0003הרי כאן שבעה!\u0004 ודוחים: הכתוב \u0003ההוא\u0004 \"והצדיקו\" \"והרשיעו\" \u0003מיבעי ליה\u0004 \u0005[נצרך לו\u0006 ללימוד אחר\u0005],\u0006 \u0003כ\u0004שיטת \u0003עולא.\u0004 ש\u0003אמר עולא: רמז לעדים זוממין מן התורה מנין.\u0004","לפני שמסיימים דברי עולא תוהים על עצם השאלה: מה משמע \u0003\"רמז לעדים זוממין\"?!\u0004 וכי לרמז צריכים אנו? \u0003והא כתיב\u0004 \u0005[והלא נאמר]\u0006 במפורש ביחס לעד שקר \"ועשיתם לו \u0003כאשר זמם\u0004 לעשות לאחיו\" (דברים יט, יט)! \u0003אלא\u0004 כך יש להבין את דברי עולא: \u0003רמז לעדים זוממין שלוקין מניין?\u0004 כי כאשר זממו העדים בדבר שאי אפשר להענישם בדיוק באותו עונש, כגון שהעידו שיש פסול במשפחתו של אדם מסויים, שאין מקום להעניש את משפחתם שלהם בכגון זה, במקרה כזה, מלקים אותם על עוון עדות שקר. רמז להלכה זו מנין? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והצדיקו את הצדיק והרשיעו את הרשע\u0004 והיה אם בן הכות הרשע","\u0003\"\u0004(דברים כה א–ב), וכך יש לשאול: ו\u0003משום\u0004 ש\u0003\"הצדיקו את הצדיק והרשיעו את הרשע\"\u0004 יבוא ההמשך \u0003\"והיה אם בן הכות הרשע\"?!\u0004 שאם מבינים את הכתוב כאן כפשוטו, בדין בין שני אנשים המתדיינים זה עם זה, הרי גם אם אחד מהם צודק אין מקום להלקות את הצד שנתחייב! \u0003אלא\u0004 יש לומר שכאן ממשיך הכתוב לדבר בעדים ולא בבעלי הדין, כיצד? \u0003עדים שהרשיעו את הצדיק\u0004 בעדות שקר, \u0003ואתו עדי אחריני\u0004 \u0005[ובאו עדים אחרים]\u0006 \u0003והצדיקו את הצדיק דמעיקרא\u0004 \u0005[שמתחילה],\u0006 \u0003ושוינהו להנך\u0004 \u0005[ו\u0006ממילא \u0005עשו את אלה]\u0006 העדים ל\u0003רשעים,\u0004 ואז \u0003\"והיה אם בן הכות הרשע\"\u0004 (העד שהורשע בעדות שקר). ומכאן ראיה שפעמים לוקים העדים הזוממים בשל עצם עדותם.","ושואלים: ולשם מה רמז זה? \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 הלכה זו \u0003מ\u0004כתוב מפורש, הלא אחת מעשרת הדברות היא \u0003\"לא תענה\u0004 ברעך עד שקר\u0003\"\u0004 (שמות כ, יג), והעובר על מצות לא תעשה לוקה! ומשיבים: על \"לא תענה\" אין לוקים, \u0003משום דהוה ליה\u0004 \u0005[שהינו]\u0006 \u0003לאו שאין בו מעשה\u0004 שהרי אינו עושה כלום אלא מדבר, \u0003ו\u0004כלל הוא: \u0003כל לאו שאין בו מעשה\u0004 — \u0003אין לוקין עליו,\u0004 ולכן הוצרכו לדברי עולא.","שנינו במשנה: \u0003משום\u0004 (בשם) \u0003ר' ישמעאל אמרו\u0004 כי אף חיוב מלקות נידון \u0003בעשרים ושלשה\u0004 דיינים. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' ישמעאל?\u0004 \u0003אמר אביי: אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה של המילים \u0003\"רשע\" \"רשע\" מ\u0004דין \u0003חייבי מיתות.\u0004 כיצד? — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בדיני מלקות \u0003\"והיה אם בן הכות הרשע\"\u0004 (דברים כה, ב), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בדיני רוצח \u0003\"אשר הוא רשע למות\"\u0004 (במדבר לה, לא), \u0003מה להלן\u0004 דין רוצח \u0003בעשרים ושלשה\u0004 — \u0003אף כאן\u0004 במלקות \u0003בעשרים ושלשה.\u0004","\u0003רבא אמר\u0004 שיש להסביר את הדבר באופן אחר: \u0003מלקות במקום מיתה עומדת\u0004 שעונש מלקות הוא כתחליף לעונש המוות, והוא כאחד מדיני מיתה שבתורה, ומשום כך אף הוא צריך להידון בעשרים ושלושה. \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: אי הכי\u0004 \u0005[אם כך]\u0006 שהמלקות הן במקום מיתה \u0003אומדנא למה לי?\u0004 ששנינו בדיני מלקות שלפני שמלקים אדם מביאים רופאים מומחים ואומדים כמה מכות יוכל ללקות בלא למות מהן, ומלקים אותו פחות מכשיעור המביאו לידי מיתה. ואם המלקות הן במקום מיתה לשם מה אומדנא זו? \u0003למחייה\u0004 \u0005[שיכוהו],\u0006 \u0003ואי מאית\u0004 \u0005[ואם ימות\u0006 במלקות\u0005]\u0006 — \u0003לימות\u0004 \u0005[שימות]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ארבעים יכנו לא יוסיף פן יוסיף להכותו על אלה מכה רבה \u0003ונקלה אחיך לעיניך\"\u0004 (דברים כה, ג), ומכאן נלמד: \u0003כי מחית\u0004 \u0005[כאשר אתה מכה]\u0006 — \u0003אגבא דחיי מחית\u0004 \u0005[על גבו של\u0006 אדם \u0005חי הכה]\u0006 ולא על גבו של מת, שאינו קרוי עוד \"אחיך\". ומקשים עוד: \u0003אלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמדוהו\u0004 את הנידון למלקות \u0003לקבל עשרים\u0004 שאינו יכול לקבל יותר מזה — \u0003אין מכין אותו אלא מכות הראויות להשתלש,\u0004 כלומר, להחלק לשלושה חלקים, שסדר המלקות הוא שהיו מלקים את הרשע לפי סדר קבוע: שתי מלקות מאחוריו ואחת מלפניו. \u0003ו\u0004אם כן באדם זה שאמדוהו לעשרים, \u0003כמה הן\u0004 מלקות שמלקים אותו שהם במספר המתחלק לשלוש? — \u0003תמני סרי\u0004 \u0005[שמונה עשרה],\u0006"],["ואם מלקות הן במקום מיתה, \u0003למחייה\u0004 \u0005[שיכוהו]\u0006 \u0003עשרים וחדא\u0004 \u0005[ואחת]\u0006 מכות, שהרי אמדוהו שיכול להחזיק מעמד בעשרים, \u0003וכי מיית בהך חדא\u0004 \u0005[וכאשר ימות בזו האחת\u0006 היתירה\u0005]\u0006 — \u0003לימות\u0004 \u0005[שימות],\u0006 \u0003דהא כי מחית, אגבא דחייא קא מחית\u0004 \u0005[שהרי כאשר מכה אתה, על גבו של\u0006 אדם \u0005חי אתה מכה]\u0006 ולא ימות אלא במכה העשרים ואחת! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 שם: \u0003\"ונקלה אחיך לעיניך\",\u0004 וכוונתו גם \u0003אחר שלקה \"אחיך\" בעינא\u0004 \u0005[צריכים אנו],\u0006 שאפשר לומר שיהא נקלה על ידי המלקות \u0003וליכא\u0004 \u0005[ואין כאן]\u0006 אם מת מתוך מלקות.","במשנה שנינו כי \u0003עיבור החדש בשלשה.\u0004 ומדייקים בלשון: \u0003\"חישוב\u0004 החודש \u0003\"\u0004אם ראוי לעברו \u0003לא קתני\u0004 \u0005[שנה],\u0006 \u0003\"קידוש\u0004 החודש \u0003\",\u0004 כלומר, קביעת והכרזת בית הדין שהיום ראש חודש גם כן \u0003לא קתני\u0004 \u0005[שנה],\u0006 \u0003אלא\u0004 שנה \u0003\"עיבור\u0004 החודש \u0003\".\u0004 ודיוק הלשון \"עיבור החודש\" הוא כאשר מוסיפים לחודש (שסתמו עשרים ותשעה יום) עוד יום אחד, יום השלושים. ויש לשאול: לשם מה יש צורך בבית דין לצורך זה? ש\u0003לא ליקדשא\u0004 \u0005[יקדשו]\u0006 את החודש ביום השלושים לחודש הקודם, \u0003וממילא לעבר\u0004 \u0005[יתעבר],\u0006 שהרי אם לא קידשו את ראש החודש נמשך החודש הקודם, ויהא ראש החודש ביום שלאחריו. בתשובה לקושי זה הציעו אמוראים שונים כמה אופנים, שיש בכולם מעין תיקון של הסגנון.","\u0003אמר אביי: תני\u0004 \u0005[שנה]\u0006 שם בלשון אחרת \u0003\"קידוש החדש\u0004 בשלושה \u0003\",\u0004 שכאשר קובעים את יום ראש החודש, עושים זאת בבית דין של שלושה. ואכן, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003קידוש החדש ועיבור השנה בשלשה,\u0004 אלו \u0003דברי ר' מאיר. אמר רבא\u0004 על תירוץ זה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"עיבור\u0004 החודש \u0003\"\u0004\u0003קתני\u0004 \u0005[שנינו]\u0006 במשנתנו, ולא קידוש? \u0003אלא אמר רבא:\u0004 כך יש לתקן את סגנון המשנה \u0003\"קידוש ביום עיבור\",\u0004 אם מקדשים את החודש ביום שהוא עשוי להיות מעובר בו, כלומר, ביום שלושים לחודש הקודם, עושים קידוש זה \u0003בשלשה,\u0004 ואילו ביום ש\u0003אחר\u0004 ה\u0003עיבור\u0004 שוב \u0003ליכא\u0004 \u0005[אין]\u0006 \u0003קידוש,\u0004 שהחודש מתקדש מעצמו,","\u0003ומני\u0004 \u0005[ו\u0006כשיטת \u0005מי היא\u0006 משנתנו\u0005]\u0006 לפי הסבר זה? — כשיטת \u0003ר' אלעזר בן צדוק היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אלעזר בן צדוק אומר: אם לא נראה\u0004 הירח \u0003בזמנו,\u0004 ביום שלושים לחודש הקודם, \u0003אין מקדשין אותו\u0004 ביום שלאחריו, \u0003שכבר קידשוהו בשמים\u0004 ואינו צריך קידוש נוסף.","\u0003רב נחמן אמר\u0004 להיפך: \u0003קידוש אחר עיבור\u0004 הוא שצריך \u0003שלשה\u0004 דיינים, ואילו \u0003ביום עיבור\u0004 אם רוצים שיהא זה ראש חודש, אין צורך אז בקביעה מיוחדת, אלא ממילא הוא מתקדש ו\u0003ליכא\u0004 \u0005[אין]\u0006 \u0003קידוש,\u0004 שזהו זמן הרגיל לראש החודש, ורק כשיש שינוי צריך דיון והכרזה. \u0003ומני\u0004 \u0005[ו\u0006כשיטת \u0005מי היא\u0006 משנתנו\u0005]\u0006 לפי הסבר זה? — כשיטת החכם \u0003פלימו היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003פלימו אומר:\u0004 אם העידו עדים שראו את מולד הירח \u0003בזמנו,\u0004 כלומר, ביום שלושים לחודש הקודם — \u0003אין מקדשין אותו, שלא בזמנו\u0004 — \u0003מקדשין אותו\u0004 משום שעשו שינוי.","\u0003רב אשי\u0004 \u0003אמר: לעולם \"חישוב\" קתני\u0004 \u0005[שנה],\u0006 וכך יש להבין: \u0003ומאי\u0004 \u0005[ומה\u0006 פירושו\u0005]\u0006 של \u0003\"עיבור\u0004 החודש \u0003\"\u0004שנאמר במשנה? — ה\u0003חישוב\u0004 של \u0003עיבור\u0004 החודש, שיש חודשים בהם יש צורך בחישוב מיוחד האם ראוי לקבוע את ראש החודש ביום שלושים או בשלושים ואחד. \u0003ואיידי דקבעי למיתני\u0004 \u0005[ומתוך שרצה לשנות]\u0006 אחר כך \u0003\"עבור שנה\", תנא נמי\u0004 \u0005[שנה גם כן]\u0006 בלשון \u0003\"עיבור חודש\",\u0004 אבל כוונתו היתה לחישוב של עיבור החודש.","ומעירים: לשיטה זו, \u0003חישוב חודש\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 צריך לעשותו בבית דין, אבל \u0003קידוש חודש\u0004 להודיע שראש חודש חל ביום זה, ולהכריז על כך — \u0003לא\u0004 צריך כלל בבית דין, \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא\u0006 משנה זו\u0005]?\u0006 — כשיטת \u0003ר' אליעזר היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: בין\u0004 שקבעו את ראש החודש \u0003בזמנו,\u0004 ביום שלושים, \u0003בין שלא בזמנו\u0004 — \u0003אין מקדשין אותו, שנאמר: \"וקדשתם את שנת החמשים שנה\u0004 וקראתם דרור בארץ לכל יושביה יובל היא תהיה לכם\u0003\"\u0004 (ויקרא כה, י), ויש לדייק: \u0003שנים אתה מקדש, ואי\u0004 (אין) \u0003אתה מקדש חדשים,\u0004 שהם מתקדשים מעצמם. ואולם אם יש צורך בחישוב, שינוי הקביעה צריך להיעשות בידי דיינים.","שנינו במשנה ש\u0003רבן שמעון בן גמליאל אומר\u0004 שעיבור השנה נעשה בשלבים — \u0003בשלשה,\u0004 חמישה ושבעה דיינים. \u0003תניא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003כיצד אמר רבן שמעון בן גמליאל?\u0004 — \u0003בשלשה מתחילין\u0004 את הדיון, \u0003ובחמשה נושאין ונותנין, וגומרין בשבעה.\u0004 כיצד? — יושבים שלושה דיינים ומעיינים אם יש מקום לדון בשאלה זו, אם \u0003אחד\u0004 מהם \u0003אומר\u0004 שצריך \u0003לישב\u0004 ולדון בנושא, \u0003ושנים אומרים שלא לישב\u0004 — הרי \u0003בטל יחיד במיעוטו,\u0004 ואין ממשיכים בנושא זה, ואם","\u0003שנים\u0004 מן הדיינים \u0003אומרים לישב\u0004 ולדון, \u0003ואחד אומר שלא לישב\u0004 — הרי מתקבלת ההחלטה לדון, ולשם כך \u0003מוסיפין עליהם עוד שנים, ו\u0004כל החמישה \u0003נושאין ונותנין בדבר\u0004 אם צריכה השנה עיבור או אם אינה צריכה. אם רק \u0003שנים\u0004 מחמישה אלה \u0003אומרים צריכה ושלשה אומרים אינה צריכה\u0004 — \u0003בטלו שנים במיעוטן\u0004 ואין מעברים. \u0003שלשה אומרים צריכה ושנים אומרים אינה צריכה\u0004 עיבור, כיון שהגיעו לכך \u0003מוסיפין עליהם עוד שנים, שאין המנין\u0004 של המחליטים לבסוף על עיבור השנה \u0003פחות משבעה.\u0004","ושואלים: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003שלשה חמשה ושבעה כנגד מי\u0004 תיקנו חכמים דווקא מספרים אלה לצורך הדיון? \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בענין זה \u0003ר' יצחק בר נחמני וחד דעימיה\u0004 \u0005[ו\u0006חכם \u0005אחד ש\u0006היה \u0005עמו],\u0006 \u0003ומנו\u0004 \u0005[ומיהו\u0006 חכם זה\u0005]?\u0006 — \u0003ר' שמעון בן פזי. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שכך היתה המסורת: שאמרו את הדבר \u0003ר' שמעון בן פזי וחד דעימיה\u0004 \u0005[ו\u0006חכם \u0005אחד ש\u0006היה \u0005עמו],\u0006 \u0003ומנו\u0004 \u0005[ומיהו]?\u0006 — \u0003ר' יצחק בר נחמני. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003כנגד ברכת כהנים,\u0004 שבשלושת פסוקיה פסוק ראשון הוא בן שלוש מילים, שני בן חמש, ושלישי בן שבע מילים. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003שלשה\u0004 — \u0003כנגד שומרי הסף\u0004 (הנזכרים במלכים ב' כה יח), \u0003חמשה\u0004 — כנגד \u0003\"מרואי פני המלך\"\u0004 (מלכים ב' כה, יט), \u0003שבעה\u0004 — \u0003רואי פני המלך\u0004 שהוגלו בבלה (\"ומן העיר לקח... ושבעה אנשים מרואי פני המלך אשר נמצאו בעיר. ויקח אותם נבוזראדן רב טבחים ויולך אותם אל מלך בבל רבלתה\". ירמיה נב, כה–כו), וכיון שמספרים אלה שלושה חמישה ושבעה הם מניינם של מינויים חשובים שונים, עשו כן גם בבית הדין.","וכן \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 בברייתא שמסר: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003שלשה וחמשה ושבעה\u0004 דיינים הריהם, \u0003שלשה\u0004 — \u0003כנגד שומרי הסף, חמשה\u0004 — \u0003\"מרואי פני המלך\", שבעה\u0004 — \u0003\"רואי פני המלך\".\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: עד האידנא מאי טעמא\u0004 \u0005[עכשיו מה טעם]\u0006 \u0003לא פריש לן מר הכי\u0004 \u0005[פירש לנו אדוני כך],\u0006 ולא שמענו הסבר זה אף שלמדנו מסכת סנהדרין פעמים אחדות? \u0003אמר להו\u0004 \u0005[להם]\u0006 לשואלים: \u0003לא הוה ידענא דצריכיתו\u0004 \u0005[הייתי יודע,\u0006 ידעתי \u0005שאתם נזקקים\u0006 לפירוש זה\u0005],\u0006 שחשבתי שאתם יודעים אותו, \u0003מי בעיתו מנאי מילתא\u0004 \u0005[וכי שאלתם ממני דבר]\u0006 \u0003ולא\u0004 \u0003אמרי לכו\u0004 \u0005[אמרתי לכם]?\u0006 ולכן לא אמרתי את זאת עד עתה, כאשר נזדמן לומר את הדבר.","לענין של עיבור השנה מביאים עוד מקורות שונים, ונתנו להם סימן: \u0003זמן, נשיא, צריך, גדי. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003אין מעברין את השנה אלא ד\u0004"],["\u0003במזומנין לה\u0004 (באלה שהזמינם) הנשיא מתחילה לצורך זה. \u0003מעשה ברבן גמליאל שאמר\u0004 לחכמים: \u0003השכימו לי שבעה לעלייה\u0004 כדי לעשות בית דין לעיבור השנה, \u0003השכים ומצא\u0004 בה \u0003שמונה. אמר: מי הוא שעלה שלא ברשות\u0004 — \u0003ירד!\u0004","\u0003עמד שמואל הקטן ואמר: אני הוא שעליתי שלא ברשות, ולא לעבר השנה עליתי\u0004 להשתתף בין הדיינים, \u0003אלא ללמוד הלכה למעשה הוצרכתי\u0004 ובאתי רק כצופה לראות כיצד נעשה הדבר, \u0003אמר לו\u0004 רבן גמליאל: \u0003שב בני, שב.\u0004 באמת \u0003ראויות כל השנים כולן להתעבר על ידך,\u0004 ואין לי כל טענה כלפי השתתפותך בבית הדין, שוודאי ראוי אתה להיות בו, \u0003אלא\u0004 בכל זאת הרי \u0003אמרו חכמים: אין מעברין את השנה אלא במזומנין לה\u0004 ולא באחרים. ומעירים: \u0003ו\u0004אותו אדם שעלה שלא ברשות \u0003לא שמואל הקטן הוה\u0004 \u0005[היה],\u0006 \u0003אלא איניש אחרינא\u0004 \u0005[אדם אחר]\u0006 היה, ו\u0003מחמת כיסופא\u0004 \u0005[בושה]\u0006 של אותו אדם \u0003הוא דעבד\u0004 \u0005[שעשה]\u0006 שמואל הקטן מה שעשה, כדי שלא יבוייש אותו אדם ברבים.","אגב מעשה זה בשמואל הקטן מספרים שאירע דבר מעין זה אצל רבי. \u0003כי הא דיתיב\u0004 \u0005[כמו\u0006 מעשה \u0005זה שהיה יושב]\u0006 \u0003רבי וקא דריש\u0004 \u0005[והיה דורש],\u0006 \u0003והריח ריח שום,\u0004 וכיון שהיה איסטניס לא יכול היה לסבול זאת, \u0003אמר: מי שאכל שום\u0004 — \u0003יצא. עמד ר' חייא ויצא, עמדו כולן\u0004 מפני כבודו של ר' חייא \u0003ויצאו. בשחר\u0004 (למחרת בבוקר) \u0003מצאו ר' שמעון ברבי לר' חייא,\u0004 ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אתה הוא שציערת לאבא\u0004 כשבאת לאחר אכילת שום לבית המדרש? \u0003אמר לו: לא תהא כזאת בישראל!\u0004 ודאי שלא אני עשיתי זאת, אלא קיבל על עצמו אשמתו של אחר כדי שלא יבוייש אותו אדם.","ושואלים: \u0003ור' חייא מהיכא גמיר לה\u0004 \u0005[מהיכן למד אותה\u0006 דרך\u0005]\u0006 שראוי לחסיד שבישראל לקבל על עצמו אשמתו של אחר כדי שלא לביישו? ומשיבים: \u0003מר' מאיר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה באשה אחת שבאתה לבית מדרשו של ר' מאיר. אמרה לו: רבי, אחד מכם,\u0004 מבני בית מדרשך, \u0003קדשני בביאה,\u0004 כלומר, בא עלי ואמר שהוא עושה זאת לשם נישואין, ואיני יודעת מי היה, ורצונה שישאנה או שיפטרנה בגט. \u0003עמד ר' מאיר וכתב לה גט כריתות, ונתן לה,\u0004 שאמר שאף הוא בכלל בני בית המדרש. משראו זאת שאר התלמידים, \u0003עמדו\u0004 כולם ו\u0003כתבו כולם\u0004 גט \u0003ונתנו לה,\u0004 וממילא אותו תלמיד שעשה המעשה גם נתן לה גיטה, והריהי איפוא מותרת להינשא.","ושואלים: \u0003ור' מאיר מהיכא גמיר לה\u0004 \u0005[מהיכן למד\u0006 דבר \u0005זה]\u0006 לעשותו? ומשיבים: \u0003משמואל הקטן,\u0004 שכבר הזכרנו אותו. \u0003ושמואל הקטן מהיכא גמיר לה\u0004 \u0005[מהיכן למד\u0006 דבר \u0005זה]?\u0006 ומשיבים: \u0003משכניה בן יחיאל, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויען שכניה בן יחיאל מבני עילם ויאמר לעזרא אנחנו מעלנו באלהינו ונשב נשים נכריות מעמי הארץ ועתה יש מקוה לישראל על זאת\"\u0004 (עזרא י, ב), ואילו ברשימת האנשים שנשאו נשים נכריות (עזרא י, יח–מד) אין מופיע שמו של שכניה בן יחיאל, משמע שהתוודה על עוונותיהם של אחרים.","ושואלים: \u0003ושכניה בן יחיאל מהיכא גמר לה\u0004 \u0005[מהיכן למד\u0006 דבר \u0005זה]?\u0006 ומשיבים: \u0003מיהושע, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ויאמר ה' אל יהושע קם לך למה זה אתה נפל על פניך, חטא ישראל...\u0004 וגם לקחו מן החרם\u0003\"\u0004 (יהושע ז, י–יא), \u0003אמר לפניו: רבונו של עולם, מי\u0004 זה ש\u0003חטא? אמר לו: וכי דילטור\u0004 \u0005[מלשין]\u0006 \u0003אני לך? הטל גורלות\u0004 כדי לדעת מיהו זה שחטא. הרי שאף הקדוש ברוך הוא אינו רוצה לפרסם ולגלות מי הוא החוטא. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ששכניה בן יחיאל למד דרך זו \u0003ממשה\u0004 רבינו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ויאמר ה' אל משה \u0003עד אנה מאנתם\u0004 לשמור מצוותי ותורותי\" (שמות טז, כח), שנאמר לכל קהל ישראל, אף כי החוטאים היו רק אנשים בודדים בקהל.","כיון שהוזכר המעשה בשמואל הקטן ומנהג החסידות שלו, מביאים דברים שיש בהם הארה נוספת על אישיותו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003משמתו נביאים האחרונים חגי זכריה ומלאכי נסתלקה רוח הקודש\u0004 של נבואה ממש \u0003מישראל, ואף על פי כן היו משתמשין בבת קול,\u0004 שמזמן לזמן היו שומעים קול מאחוריהם כעין הד, ובו היו כדברי נבואה. מספרים: \u0003פעם אחת היו מסובין\u0004 חכמים \u0003בעליית בית גוריה ביריחו ונתנה עליהם בת קול מן השמים\u0004 שאמרה: \u0003יש כאן אחד שראוי שתשרה עליו שכינה כמשה רבינו, אלא שאין דורו זכאי לכך,\u0004 שאין הדורות הללו ראויים לגילוי של נבואה. \u0003נתנו חכמים את עיניהם בהלל הזקן\u0004 שסברו שבודאי הוא שנתכוונה לו בת הקול, \u0003וכשמת אמרו עליו\u0004 בהספד בנוסח זה: \u0003הי חסיד, הי עניו, תלמידו\u0004 \u0003של עזרא!\u0004","\u0003שוב פעם אחת\u0004 לאחר זמן \u0003היו מסובין בעליה ביבנה, ונתנה עליהם בת קול מן השמים\u0004 שאמרה: \u0003יש כאן אחד שראוי שתשרה עליו שכינה, אלא שאין דורו זכאי לכך, נתנו חכמים את עיניהם בשמואל הקטן, וכשמת אמרו עליו: הי חסיד, הי עניו, תלמידו של הלל. אף הוא אמר בשעת מיתתו\u0004 דברי נבואה והוכיח שאף שפסקה נבואה, מכל מקום רוח הקודש היתה בו. וכך אמר: \u0003שמעון וישמעאל\u0004 (רבן שמעון בן גמליאל נשיא ישראל, ור' ישמעאל הכהן הגדול) עתידים למות ב\u0003חרבא\u0004 \u0005[חרב],\u0006 \u0003וחברוהי\u0004 \u0005[וחבריהם]\u0006 \u0003לקטלא\u0004 \u0005[למיתה]\u0006 במיתות אחרות, \u0003ושאר עמא לביזא\u0004 \u0005[העם לבז],\u0006 \u0003ועקן סגיאן עתידן למיתי על עלמא\u0004 \u0005[וצרות גדולות עתידות לבוא על העולם],\u0006 וכן היה.","\u0003ו\u0004גם \u0003על יהודה בן בבא בקשו לומר כן\u0004 בנוסח \"הי חסיד הי עניו\", \u0003אלא שנטרפה שעה\u0004 ולא יכלו לעשות זאת לפי \u0003שאין מספידין על הרוגי מלכות.\u0004 שהוא נהרג בידי המלכות, כאשר יבואר.","ושוב חוזרים אנו לענין העיבור, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מעברין את השנה אלא אם כן ירצה נשיא\u0004 שבו תלוי העיבור. \u0003ומעשה ברבן גמליאל שהלך ליטול רשות\u0004 לנושא מסויים \u0003אצל הגמון אחד שבסוריא, ושהה לבוא\u0004 לאחר הזמן שאפשר לעבר בו, ולא אמר להם מה רצונו. \u0003ועיברו את השנה\u0004 על תנאי, \u0003על מנת שירצה רבן גמליאל. וכשבא רבן גמליאל ואמר \"רוצה אני\"\u0004 — \u0003נמצאת שנה מעוברת\u0004 למפרע.","עוד בענין עיבור \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003אין מעברין את השנה אלא אם כן היתה צריכה\u0004 לעיבור \u0003מפני הדרכים\u0004 שנתקלקלו בגשם ואין להגיע לירושלים, \u0003ומפני הגשרים\u0004 שנתקלקלו, \u0003ומפני תנורי פסחים\u0004 שנתקלקלו במי הגשמים ואינם ראויים לצלות בהם, \u0003ומפני גליות ישראל שנעקרו ממקומן\u0004 ללכת להקריב את קרבן הפסח, ובגלל קשיי התנועה התעכבו בדרכם \u0003ועדיין לא הגיעו,\u0004 ולא יוכלו לבוא בזמן להקרבת הקרבן. \u0003אבל לא\u0004 מעברין \u0003מפני השלג\u0004 שאינו מפריע עד כדי כך, \u0003ולא מפני הצינה, ולא מפני גליות ישראל שלא עקרו ממקומן,\u0004 אף שיתכן שלא יספיקו להגיע כשיצאו לדרך.","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מעברין את השנה לא מפני הגדיים ולא מפני הטלאים\u0004 שנולדו באיחור ולא גדלו עדיין, \u0003ולא מפני הגוזלות\u0004 של יונים \u0003שלא פירחו\u0004 (הצמיחו כנפים), ולא יהיו גוזלות מספיקים בשביל הבאים להקריב קרבן עוף, \u0003אבל עושין אותן סעד לשנה,\u0004 שאם יש צורך לעבר את השנה מפני טעמים אחרים, מוסיפים גם את הטעם שהגדיים והגוזלות הם קטנים מדי. ושואלים: \u0003כיצד,\u0004 מהו הנוסח לזה? \u0003ר' ינאי אומר משום\u0004 (בשם) \u0003רבן שמעון בן גמליאל,\u0004 כך היה נוסח אגרתו של רבן שמעון בן גמליאל: \u0003מהודעין אנחנא לכון\u0004 \u0005[מודיעים אנו לכם]\u0006 \u0003דגוזלייא רכיכין ואימריא דערקין ד\u0004\u0005[שהגוזלים רכים והטלאים דקים],\u0006 \u0003וזימנא דאביבא\u0004 \u0005[וזמן האביב]\u0006 \u0003לא מטא\u0004 \u0005[הגיע],\u0006 \u0003ושפרת מילתא באנפאי, ואוסיפית על שתא דא תלתין יומין\u0004 \u0005[ויפה,\u0006 נראה, \u0005הדבר בעיני, והוספתי על שנה זו שלושים יום].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 וכי רבן שמעון בן גמליאל סבור שחודש העיבור הוא בן שלושים יום? והלא נחלקו: \u0003כמה\u0004 ימים נוספים ב\u0003עיבור השנה?\u0004 אמרו חכמים: \u0003שלשים יום. רבן שמעון בן גמליאל אומר: חדש\u0004 סתם שהוא עשרים ותשעה ימים! ובאגרתו אומר שהוסיף שלושים יום! \u0003אמר רב פפא:\u0004 מה שאמר רבן שמעון בן גמליאל \"חודש\", לא היתה כוונתו חודש דווקא, אלא אם \u0003רצו\u0004 — עושים \u0003חדש,\u0004 אם \u0003רצו\u0004 — עושים \u0003שלשים יום.\u0004","על נוסח אגרתו של רבן שמעון בן גמליאל מעירים: \u0003תא חזי מאי איכא\u0004 \u0005[בוא וראה מה\u0006 הבדל \u0005יש]\u0006 \u0003בין\u0004"],["\u0003תקיפאי קדמאי לעינוותני בתראי\u0004 \u0005[התקיפים הראשונים לענוותנים האחרונים],\u0006 שתקיפי דורות הראשונים היו ענווים יותר מאשר הענווים שבדורות מאוחרים. שרבן שמעון בן גמליאל היה מפורסם כעניו, ורבן גמליאל היה איש תקיף ביותר, ובכל זאת לשון התקיפים הקדומים צנועה יותר.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003מעשה ברבן גמליאל שהיה יושב על גב מעלה\u0004 (מדרגה) \u0003בהר הבית, והיה יוחנן סופר הלז\u0004 \u0005[הזה]\u0006 \u0003עומד לפניו\u0004 ומתכונן לכתוב את האגרות השייכות לדבר, \u0003ושלש איגרות\u0004 קלף היו \u0003חתוכות לפניו מונחות\u0004 ומוכנות כבר ליכתב,","ו\u0003אמר לו: טול איגרתא חדא\u0004 \u0005[אגרת אחת]\u0006 \u0003וכתוב: לאחנא\u0004 \u0005[לאחינו]\u0006 \u0003בני גלילאה עילאה\u0004 \u0005[הגליל העליון],\u0006 \u0003ולאחנא\u0004 \u0005[ולאחינו]\u0006 \u0003בני גלילאה תתאה\u0004 \u0005[הגליל התחתון],\u0006 \u0003שלומכון יסגא\u0004 \u0005[שלומכם ירבה]!\u0006 \u0003מהודעין אנחנא לכון\u0004 \u0005[מודיעים אנו לכם]\u0006 ש\u0003זמן ביעורא מטא\u0004 \u0005[הביעור\u0006 בשנה השלישית או השישית לשמיטה \u0005הגיע],\u0006 \u0003לאפרושי מעשרא ממעטנא דזיתא\u0004 \u0005[להפריש\u0006 את \u0005המעשר ממעטן הזיתים].\u0006 והוסף \u0003וטול איגרתא חדא\u0004 \u0005[וטול אגרת אחת]\u0006 \u0003וכתוב: לאחנא\u0004 \u0005[לאחינו]\u0006 \u0003בני דרומא\u0004 \u0005[הדרום],\u0006 יהודה וסביבתה, \u0003שלומכון יסגא\u0004 \u0005[שלומכם ירבה]!\u0006 \u0003מהודעין אנחנא לכון\u0004 \u0005[מודיעים אנו לכם]\u0006 ש\u0003זמן ביעורא מטא\u0004 \u0005[הביעור הגיע],\u0006 \u0003לאפרושי מעשרא\u0004 \u0005[להפריש\u0006 את \u0005המעשר]\u0006 \u0003מעומרי שיבליא\u0004 \u0005[השבלים],\u0006 כי רוב זיתי הארץ היו גדלים בגליל, ורוב דגני הארץ היו גדלים ביהודה.","\u0003וטול איגרתא חדא\u0004 \u0005[וטול אגרת אחת]\u0006 \u0003וכתוב\u0004 בה: \u0003לאחנא\u0004 \u0005[לאחינו]\u0006 \u0003בני גלוותא\u0004 \u0005[הגלויות]\u0006 \u0003בבבל, ולאחנא\u0004 \u0005[ולאחינו]\u0006 ש\u0003במדי, ולשאר כל גלוותא\u0004 \u0005[גלויות]\u0006 \u0003ישראל, שלומכון יסגא לעלם\u0004 \u0005[שלומכם ירבה לעולם]!\u0006 \u0003מהודעין אנחנא לכון דגוזליא רכיכין, ואימריא ערקין, וזמנא דאביבא לא מטא\u0004 \u0005[מודיעים אנו לכם שהגוזלים רכים, והטלאים דקים, וזמן האביב לא הגיע\u0006 עדיין\u0005],\u0006 \u0003ושפרא מילתא באנפאי ובאנפי חביריי, ואוסיפית על שתא דא יומין תלתין\u0004 \u0005[ויפה היה הדבר בפני ובפני חברי, והוספתי על שנה זו שלושים ימים],\u0006 על כל פנים רואים אנו שרבן גמליאל התקיף אומר שלא הוא עצמו החליט אלא צירף גם את חבריו עמו. ודוחים: \u0003דילמא בתר דעברוהו\u0004 \u0005[שמא\u0006 מדובר כאן \u0005לאחר\u0006 הזמן \u0005שהעבירוהו]\u0006 מנשיאותו, ועשו לו חבר בנשיאות את ר' אלעזר בן עזריה, ומשום כך היה צריך לכתוב בשמו ובשם חבירו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003על שלשה דברים מעברין את השנה: על האביב,\u0004 שלא הגיע עדיין זמן הבשלת השעורים, \u0003ועל פירות האילן\u0004 שלא הבשילו עדיין, \u0003ועל התקופה\u0004 שלא הגיעה התקופה (זמן שויון היום והלילה האביבי) לפני פסח (מאירי). ומעירים: \u0003על שנים מהן\u0004 אם הגיעו — \u0003מעברין\u0004 גם אם לא היה השלישי, \u0003ועל אחד מהן\u0004 — \u0003אין מעברין,\u0004","\u0003ובזמן שאביב אחד מהן\u0004 — \u0003הכל שמחין,\u0004 כי בפעמים אחרות שכבר הבשילה התבואה ועושים בכל זאת חודש נוסף, הרי אסורה התבואה באכילה מפני איסור חדש, ואילו כשמתחשבים באביב אין חשש כזה. \u0003רבן שמעון בן גמליאל אומר: על התקופה.\u0004 דבר זה לא היה ברור כל צרכו, \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם היתה כוונתו לומר כי \u0003על התקופה שמחין, או\u0004 רצה לומר כי \u0003על התקופה\u0004 לבדה \u0003מעברין,\u0004 שלא כדברי התנא הראשון? שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003על שלשה ארצות מעברין את השנה,\u0004 כלומר, בודקים את המצב בשלושה חלקים של ארץ ישראל: על \u0003יהודה, ועבר הירדן, והגליל. על שתים מהן\u0004 — \u0003מעברין, ועל אחת מהן\u0004 בלבד — \u0003אין מעברין. ובזמן שיהודה אחת מהן\u0004 — \u0003הכל שמחין, שאין עומר בא אלא מיהודה,\u0004 ואם ידאגו שיגיע זמן הבשלת התבואה ביהודה סמוך לעומר, ודאי שכבר הבשילה התבואה במקומות אחרים, ולא יהיו קשיים בענין התבואה החדשה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003אין מעברין את השנים אלא ביהודה, ואם עיברוה בגליל\u0004 — \u0003מעוברת.\u0004 ו\u0003העיד חנניה איש אונו: אם עיברוה בגליל\u0004 — \u0003אינה מעוברת. אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003חנניה איש אונו?\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004כי אם אל המקום אשר יבחר ה' אלהיכם מכל שבטיכם לשום את שמו שם \u0003לשכנו תדרשו ובאת שמה\"\u0004 (דברים יב, ה), וכוונתו: \u0003כל דרישה שאתה דורש\u0004 בכל דבר שאתה צריך לעשותו בעיקר בהלכה, \u0003לא יהיו אלא בשכנו\u0004 (בשכנותו) \u0003של מקום,\u0004 כלומר, בארץ יהודה, הסמוכה לירושלים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מעברין את השנה אלא ביום, ואם עיברוה בלילה\u0004 — \u0003אינה מעוברת. ואין מקדשין את החדש אלא ביום, ואם קידשוהו בלילה\u0004 — \u0003אינו מקודש. אמר ר' אבא: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך? — \u0003\"תקעו בחדש שופר בכסה ליום חגנו\"\u0004 (תהלים פא, ד), \u0003איזהו חג שהחדש,\u0004 כלומר, הירח החדש \u0003מתכסה בו\u0004 (\"כסה\"), שהרי רוב חגי ישראל הם באמצע החודש או סמוך לו, ורואים בהם את הירח? — \u0003הוי אומר: זה ראש השנה\u0004 שהוא בראשית החודש, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בו \u0003\"כי חק לישראל הוא משפט לאלהי יעקב\"\u0004 (תהלים פא, ה), ונלמד: \u0003מה משפט\u0004 נעשה רק \u0003ביום\u0004 כפי שלמדנו בהלכות דיינים, \u0003אף קידוש החדש\u0004 נעשה רק \u0003ביום,\u0004 שקביעת ראש השנה הריהי כשאר ראשי החודשים, ונעשית משום כך ביום בלבד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003אין מעברין את השנה\u0004"],["\u0003בשני\u0004 (בשנות) \u0003רעבון\u0004 כשאין התבואה מצויה, כדי שאפשר יהיה להקדים ולאכול את יבול התבואה החדש, שעל ידי עיבור השנה הרי מוסיפים עוד חודש אחד של איסור (עד לזמן העומר, במוצאי יום טוב ראשון של פסח).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003רבי אומר\u0004 על הכתוב: \u0003\"ואיש בא מבעל שלישה ויבא לאיש האלהים לחם בכורים עשרים לחם שערים\u0004 וכרמל בצקלונו ויאמר תן לעם ויאכלו\u0003\"\u0004 (מלכים ב' ד, מב),","\u0003ואין לך\u0004 סביבה \u0003קלה בכל ארץ ישראל לבשל פירותיה יותר מבעל שלישה, ואף על פי כן לא בכרה אלא מין אחד\u0004 באותו זמן. \u0003שמא תאמר: חטים\u0004 היו אלה שמתבשלות סמוך לשבועות — \u0003תלמוד לומר: \"שעורים\". שמא תאמר:\u0004 הביא את השעורים בזמן מוקדם עוד \u0003לפני העומר\u0004 — \u0003תלמוד לומר: \"תן לעם ויאכלו\",\u0004 וכיון שמותר היה לאכול משמע ש\u0003אחר העומר היה.\u0004","\u0003אמור מעתה\u0004 שלאחר העומר בניסן אי אפשר היה להביא ביכורי יבול מן המקום המבכיר ביותר בארץ אלא שעורים בלבד. הרי ש\u0003ראויה היתה אותה שנה שתתעבר,\u0004 שברור שהחיטים לא הבשילו בזמנן, שהרי לא יכלו להביא אלא שעורים, \u0003ומפני מה לא עיברה אלישע?\u0004 — מפני \u0003ששנת בצורת היתה\u0004 (כמסופר שם), \u0003והיו הכל רצין לבית הגרנות\u0004 ואם היו מעברים היה קשה עוד יותר למצוא תבואה לאכול.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003אין מעברין את השנה\u0004 הבאה \u0003לפני ראש השנה, ואם עיברוה\u0004 — \u0003אינה מעוברת, אבל מפני הדחק מעברין אותה אחר ראש השנה מיד\u0004 ואין ממתינים סמוך לפסח, \u0003ואף על פי כן אין מעברין\u0004 ומוסיפים \u0003אלא\u0004 את חודש \u0003אדר,\u0004 ולא חודש אחר.","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]\u0006 שאין מעברים בחדשים אחרים? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שלחו ליה\u0004 \u0005[לו]\u0006 \u0003לרבא\u0004 אגרת זו בלשון סתרים: \u0003זוג בא מרקת,\u0004 כלומר, זוג של תלמידי חכמים באו מרקת, היא טבריה, מקום מושב הסנהדרין אז, ששמה במקרא הוא \"רקת\" (ראה יהושע יט, לה), \u0003ותפשו נשר,\u0004 כלומר, אנשי צבא רומיים שסמלם היה הנשר, \u0003ובידם\u0004 של השליחים היו \u0003דברים הנעשה בלוז.\u0004 ומסבירים: \u0003ומאי ניהו\u0004 \u0005[ומה הם]?\u0006 — \u0003תכלת,\u0004 שאגב שליחותם לבבל לקחו איתם גם תכלת כדי לספק לאנשי בבל. \u0003בזכות הרחמים ובזכותם יצאו בשלום,\u0004 ולא נידונו למוות, ואולם לא הצליחו להעביר את ההודעה לגולה.","\u0003ועמוסי יריכי נחשון\u0004 צאצאיו של נחשון, נשיא יהודה, והוא רמז לנשיא הסנהדרין, \u0003בקשו לקבוע נציב אחד,\u0004 שבקשו לקבוע חודש נוסף לשנה, \u0003ולא הניחן אדומי הלז\u0004 המושל הרומאי בארץ. \u0003אבל בעלי אסופות,\u0004 כלומר, תלמידי החכמים שהיו בארץ (ראה קהלת יב, יא) \u0003נאספו, וקבעו לו נציב אחד בירח שמת בו אהרן הכהן\u0004 הוא חודש אב. משמע שעוסקים בעיבור השנה אפילו לפני ראש השנה! ומשיבים: \u0003חשובי\u0004 \u0005[לחשב]\u0006 — \u0003מחשבי\u0004 \u0005[מחשבים]\u0006 לפעמים קודם, אבל \u0003גלויי\u0004 \u0005[לגלות]\u0006 — \u0003לא מגלו\u0004 \u0005[מגלים]\u0006 ומפרסמים לציבור, אלא בתחילת השנה החדשה.","דרך אגב שואלים: \u0003מאי משמע\u0004 \u0005[מה משמעו\u0006 של דבר\u0005]\u0006 \u0003דהאי\u0004 \u0005[ש\u0006לשון \u0005זה]\u0006 של \u0003\"נציב\" לישנא דירחא\u0004 \u0005[לשון ירח,\u0006 חודש\u0005]\u0006 \u0003הוא?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולשלמה שנים עשר נצבים על כל ישראל וכלכלו את המלך ואת אנשיו חדש בשנה\u0004 יהיה על האחד לכלכל\u0003\"\u0004 (מלכים א' ד, ז), משמע שכל נציב שייך לחודש מסויים. \u0003ו\u0004כיון שהובא ענין זה שואלים: לאחר מניית שנים עשר הנציבים \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"ונציב אחד אשר בארץ\"\u0004 (מלכים א' ד, יט), משמע שיותר משנים עשר היו! בפירושו של דבר זה נחלקו \u0003רב יהודה ורב נחמן, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהיה עוד נציב \u0003אחד ממונה על כולם, וחד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהיה נציב אחר \u0003כנגד חדש העיבור,\u0004 שכשעיברו את השנה היה עליו לפרנס את בית המלך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003אין מעברין את השנה לא משנה\u0004 אחת \u0003לחברתה,\u0004 שאם רואים שלפי הצורך יש לעבר את השנה הבאה, אין לעבר שנה זו מפני צרכי השנה הבאה, אלא מעברים את הבאה, \u0003ולא\u0004 מעברין גם \u0003שלש שנים זו אחר זו. אמר ר' שמעון מעשה בר' עקיבא שהיה חבוש בבית האסורים, ועיבר שלש שנים זו אחר זו! אמרו לו\u0004 לר' שמעון: וכי \u0003משם\u0004 מביא אתה \u0003ראיה?\u0004 לא כך היה, אמנם ר' עקיבא חישב את הזמנים והשנים הראויות לעיבור, ואולם \u0003בית דין\u0004 מיוחד \u0003ישבו וקבעו\u0004 בפועל עיבורי שנים אלה \u0003אחת אחת בזמנה.\u0004","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מעברין את השנה לא ב\u0004שנת ה\u0003שביעית\u0004 (השמיטה), משום שעל ידי כך מאריכים את זמן איסור השמיטה ומכבידים על הבריות, \u0003ולא במוצאי שביעית\u0004 מאותו טעם, כדי שלא ידחקו במזונותיהם להתיר לאכול מן התבואה החדשה. \u0003אימתי רגילין לעבר?\u0004 — \u0003ערב שביעית,\u0004 שזהו זמן נוח לכל ואין איש נמצא נפסד בו, ואולם מסופר: חכמים \u0003של בית רבן גמליאל היו מעברין\u0004 אף \u0003במוצאי שביעית. ו\u0004הדבר קשור","\u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקתם של תנאים אלה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מביאין ירק מחוצה לארץ, ורבותינו התירו,\u0004 ואותם חכמים שהתירו להביא ירקות מחוץ לארץ לא חששו כל כך לדוחק העם במוצאי שביעית, משום שאפשר ליבא ירקות מן הארצות הסמוכות ואין חשש לרעב, ולכן התירו לעבר במוצאי שביעית. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם],\u0006 מהו יסוד המחלוקת? \u0003אמר ר' ירמיה:\u0004 בשאלה אם \u0003חוששין לגושיהן,\u0004 לגושי העפר הדבוקים בירקות, \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 שעפר מחוץ לארץ מטמא, והשאלה היתה אם מותר לכתחילה להביא אדמה טמאה לתוך ארץ ישראל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003אין מעברין את השנה מפני הטומאה,\u0004 שאם היו רוב ישראל טמאים כשהגיע הפסח, אין רשאים לעבר את השנה כדי שיספיקו להיטהר עד לחודש הבא.","\u0003ר' יהודה אומר: מעברין. אמר ר' יהודה: מעשה בחזקיה מלך יהודה ש\u0004אכן \u0003עיבר את השנה מפני הטומאה,\u0004 כאמור \"ויועץ המלך ושריו וכל הקהל בירושלים לעשות הפסח בחודש השני\" (דברי הימים ב' ל, ב), \u0003ובקש רחמים על עצמו\u0004 שיימחל לו עוון זה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"כי מרבית העם רבת מאפרים ומנשה יששכר וזבלון לא הטהרו\u0004"],["\u0003כי אכלו את הפסח בלא ככתוב כי התפלל\u0004 י \u0003חזקיהו עליהם לאמר ה' הטוב יכפר בעד\"\u0004 (דברי הימים ב' ל, יח).","\u0003ר' שמעון אומר: אם מפני הטומאה עיברוה\u0004 לשנה — \u0003מעוברת. אלא מפני מה ביקש\u0004 חזקיהו \u0003רחמים על עצמו?\u0004 — מטעם אחר: \u0003שאין מעברין אלא\u0004 חודש \u0003אדר, והוא עיבר ניסן ב\u0004תוך חודש \u0003ניסן\u0004 עצמו. \u0003ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון: מפני שהשיא\u0004 (יעץ, גרם) \u0003את ישראל לעשות פסח שני,\u0004 שלדעתו לא דובר שם כלל בעיבור השנה, אלא בהחלטה שכל ישראל יעשו פסח שני. עד כאן לשון התוספתא, ומכאן באים לבירור פרטים שונים בה.","\u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003ר' יהודה אומר: מעברין\u0004 את השנה כדי שלא לעשות פסח בטומאה. ומעירים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 \u0003ר' יהודה\u0004 את השיטה ש\u0003טומאה דחויה היא בציבור,\u0004 שאף על פי שאם רוב הציבור טמא מקריבים קרבנות בטומאה, מכל מקום אין זה היתר גמור וטוב למצוא דרך לעשותו בטהרה.","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 המוכיחה שיטה הפוכה: \u0003ציץ\u0004 הזהב, של הכהן הגדול שנאמר בו שהוא מרצה על טומאות ישראל \u0003בין שישנו על מצחו\u0004 של הכהן הגדול \u0003ובין שאינו על מצחו\u0004 — הריהו \u0003מרצה,\u0004 אלו \u0003דברי ר' שמעון. ר' יהודה אומר:\u0004 אם הציץ \u0003עודו על מצחו\u0004 — \u0003מרצה, אין עודו על מצחו\u0004 — \u0003אינו מרצה.\u0004","\u0003אמר לו ר' שמעון: כהן גדול ביום הכיפורים יוכיח, שאינו על מצחו,\u0004 לפי שברוב היום לובש הכהן הגדול רק בגדי לבן, ואין הציץ בכללם \u0003ו\u0004בכל זאת \u0003מרצה\u0004 על הטומאה! \u0003אמר לו ר' יהודה: הנח ליום הכיפורים שטומאה הותרה בציבור\u0004 היתר גמור, וממילא אין צורך לרצות על הטומאה על ידי הציץ. ואם דעתו שהותרה טומאה בציבור, מה טעם לעבר את השנה מפני הטומאה? שהרי הותר להם היתר גמור לעשות את הפסח בטומאה!","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מבין את התוספתא כלשונה, \u0003תיקשי\u0004 \u0005[תקשה]\u0006 \u0003לך היא גופה\u0004 \u0005[עצמה],\u0006 שיש בה סתירה פנימית. שהרי מצד אחד \u0003ר' יהודה אומר\u0004 ש\u0003מעברין\u0004 את השנה מפני הטומאה, \u0003ואמר ר' יהודה: מעשה בחזקיה מלך יהודה שעיבר את השנה\u0004 וביקש רחמים על עצמו, ואם לדעתו מעברים לכתחילה \u0003מפני הטומאה,\u0004 מדוע \u0003ביקש רחמים על עצמו? אלא\u0004 לכל הדעות יש לומר כי \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 התוספתא \u0005וכך היא שנויה]:\u0006 \u0003אין מעברין את השנה מפני הטומאה, ואם עיברוה\u0004 — \u0003מעוברת.\u0004 ואילו \u0003ר' יהודה אומר:\u0004 אם עיברוה \u0003אינה מעוברת. ו\u0004על זה \u0003אמר ר' יהודה\u0004 שחזקיה עיבר את השנה מטעם זה, ולכן ביקש רחמים על עצמו, לפי שעשה שלא כדין.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שזו שיטת ר' יהודה, אם כן מה שנאמר שם ש\u0003ר' שמעון אומר: אם מפני הטומאה עיברוה\u0004 — \u0003מעוברת,\u0004 הרי \u0003היינו\u0004 \u0005[זוהי\u0006 שיטתו\u0005]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 שאף הוא אומר שלכתחילה אין מעברים, ואם עיברוה מעוברת! \u0003אמר רבא: לכתחילה איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005],\u0006 כלומר, לדעת התנא הראשון אין מעברים את השנה לכתחילה מפני הטומאה, ואולם אם עשו כן הרי היא בדיעבד מעוברת. ואילו ר' שמעון אומר: אם מפני הטומאה רוצים לעבר אותה, הרי זה טעם מספיק וראוי לעבר בשבילו את השנה, אפילו לכתחילה. ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 עוד ברייתא \u0005גם כן כך]:\u0006 \u0003אין מעברין את השנה מפני הטומאה לכתחילה, ר' שמעון אומר: מעברין\u0004 אפילו לכתחילה. \u0003אלא\u0004 לשיטה זו \u0003מפני מה בקש\u0004 חזקיהו \u0003רחמים על עצמו?\u0004 — מטעם אחר: \u0003שאין מעברין אלא\u0004 חודש \u0003אדר, והוא עיבר ניסן בניסן.\u0004","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003שאין מעברין אלא אדר, והוא,\u0004 חזקיהו, \u0003עיבר ניסן בניסן.\u0004 על הסבר זה תוהים: אמרנו שחזקיהו עיבר ניסן בניסן, \u0003ולית ליה\u0004 \u0005[ו\u0006כי \u0005אין לו]\u0006 \u0003לחזקיה,\u0004 האם אינו מקבל את ההלכה הזו? והרי היא נדרשת במישרין מן הכתוב האומר \u0003\"החדש הזה לכם\u0004 ראש חדשים ראשון הוא לכם לחדשי השנה\u0003\"\u0004 (שמות יב, ב), ללמוד ממנו: שהחודש ה\u0003זה\u0004 — \u0003ניסן, ואין אחר ניסן,\u0004 ולכן אין עושים שני ניסן. ומשיבים: לא שחזקיהו עיבר ממש ניסן בניסן, אלא \u0003טעה ב\u0004אותה הלכה שלאחר דורות ניסח אותה \u0003שמואל.\u0004 ש\u0003אמר שמואל: אין מעברין את השנה ביום שלשים של אדר\u0004 אף שהוא שייך לחודש אדר, ובאדר מותר לעבר את השנה, מכל מקום יום זה \u0003הואיל וראוי לקובעו ניסן,\u0004 שהרי יתכן שיום שלושים לאדר יקבע כראש חדש ניסן, וכיון שהוא ראוי לקובעו כניסן אין מעברים בו כמו שאין מעברים בניסן.","ומסבירים: \u0003ואיהו\u0004 \u0005[והוא,\u0006 חזקיהו\u0005]\u0006 \u0003סבר: \"הואיל וראוי\" לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 וכיון שעדיין יום שלושים זה היה בתוך חודש אדר מותר לעבר בו את השנה. ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אין מעברין את השנה ביום שלשים של אדר, הואיל וראוי לקובעו ניסן\u0004 כשיטת שמואל.","שנינו בתוספתא כי \u0003ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון:\u0004 חזקיה ביקש רחמים על עצמו \u0003מפני שהשיא את ישראל לעשות פסח שני.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד היה הדבר בדיוק]\u0006 שהרי לא יעלה על הדעת שיעשה המלך הצדיק חזקיהו בניגוד לדברי התורה המפורשים! \u0003אמר רב אשי:\u0004 מעשה שהיה \u0003כגון שהיו ישראל מחצה טמאים ומחצה טהורים\u0004 בדיוק, \u0003ונשים\u0004 שהיו ביניהם היו \u0003משלימות לטהורים ועודפות עליהם,\u0004 כלומר, רוב הגברים שבין הציבור היו טמאים, ולעומתם, רוב הנשים היו טהורות, ומשהצטרפו אותן נשים טהורות למיעוט הגברים הטהורים נמצא שרוב ציבור היה טהור, והבעיה היא האם מחשיבים את הנשים להצטרף לענין רוב זה, או לא.","\u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003סבר\u0004 חזקיה כי \u0003נשים ב\u0004פסח ה\u0003ראשון\u0004 הקרבת הפסח לגביהן \u0003חובה,\u0004 ולפיכך \u0003הוו\u0004 \u0005[הרי]\u0006 \u0003מיעוטן\u0004 בלבד של ישראל \u0003טמאים,\u0004 \u0003ו\u0004לפי ההלכה \u0003מיעוטן מידחו\u0004 \u0005[נדחים]\u0006 \u0003לפסח שני,\u0004 ובו עושים את הפסח. \u0003ו\u0004אילו \u0003לבסוף סבר\u0004 חזקיה כי \u0003נשים\u0004 אפילו \u0003ב\u0004פסח ה\u0003ראשון,\u0004 הקרבת הפסח לגביהן הינה \u0003רשות\u0004 בלבד, \u0003דהוו להו\u0004 \u0005[שהיו להם]\u0006 איפוא ה\u0003טמאים רובא\u0004 \u0005[רוב\u0006 הקהל\u0005],\u0006 \u0003ורובא לא מדחו\u0004 \u0005[ורוב\u0006 הקהל \u0005אינו נדחה]\u0006 \u0003לפסח שני\u0004 על פי הדין, והיו צריכים להקריב את הפסח בטומאה בפסח הראשון. ומשום כך ביקש רחמים על עצמו, על שטעה בהלכה זו.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה בענין עיבור השנה, שנינו כי \u0003אמר שמואל: אין מעברין את השנה ביום שלשים של אדר, הואיל וראוי לקובעו ניסן.\u0004 ושואלים: ואם \u0003עיברוה מאי\u0004 \u0005[מה\u0006 יהא הדין\u0005]?\u0006 האם חל העיבור, או אינו חל? \u0003אמר עולא: אין מקדשין את החדש,\u0004 כלומר, משאירים את יום שלושים זה בחודש אדר, ונמצא שעיברו אדר באדר (רמ\"ה). ושואלים: ואם בכל זאת \u0003קידשו\u0004 בבית דין אחר יום זה כראש חודש, \u0003מאי\u0004 \u0005[מה\u0006 יהא אז הדין\u0005]?\u0006 \u0003אמר רבא: בטל העיבור,\u0004 כיון שהתברר שעכשיו הוא ניסן, ולדעת הכל אי אפשר לעבר את השנה בחודש ניסן. \u0003רב נחמן אמר: מעובר ומקודש,\u0004 שכיון שכל בית דין עושה כהוגן — הרי אלה שקידשו כהוגן עשו, ומקודש. ואלו שעיברו וחשבו שהוא אדר — כהוגן עשו, והשנה מעוברת, אף שעל פי האמת נתעברה השנה בניסן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן:\u0004 הרי יש קושי בשיטתו, \u0003מכדי מפוריא לפיסחא תלתין יומין הוו\u0004 \u0005[הרי מפורים לפסח שלושים יום הם],\u0006 \u0003ומפוריא דרשינן\u0004 \u0005[ומ\u0006זמן ה\u0005פורים דורשים אנו\u0006 לציבור\u0005]\u0006 \u0003בהלכות הפסח, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שואלין בהלכות הפסח קודם לפסח שלשים יום, רבן שמעון בן גמליאל אומר: שתי שבתות\u0004 בלבד לפני הפסח, ואם כן העם כבר יודע שבעוד חודש ימים יהיה חג הפסח, \u0003וכי מטי ריש ירחא מרחקין ליה\u0004 \u0005[וכאשר יבוא ראש החודש\u0006 שוב \u0005ירחיקו אותו,\u0006 את הפסח\u0005]\u0006 בחודש שלם, אם כן \u0003אתי לזלזולי\u0004 \u0005[יבואו לזלזל]\u0006 \u0003ב\u0004איסור \u0003חמץ,\u0004 שיגידו שחכמים קובעים את הפסח כטוב בעיניהם!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מידע ידיעי דשתא מעברתא בחושבנא תליא מילתא\u0004 \u0005[ידוע\u0006 הוא \u0005להם ששנה מעוברת בחשבון תלוי הדבר],\u0006 והוא חישוב מסובך וממושך. \u0003אמרי\u0004 \u0005[אומרים\u0006 הם\u0005]:\u0006 \u0003חושבנא\u0004 \u0005[החשבון]\u0006 \u0003הוא\u0004 ש\u0003לא סליק להו לרבנן\u0004 \u0005[עלה\u0006 ולא נגמר \u0005להם לחכמים]\u0006 \u0003עד השתא\u0004 \u0005[עכשיו],\u0006 שהם סבורים שבאמת כבר מקודם היה צורך לקבוע את השנה כמעוברת, ולא הספיקו חכמים לגמור את חשבונותיהם עד ראש חודש ניסן.","ובענין זה של קביעת העיבור על פי קנה המידה של התקופה, \u0003אמר רב יהודה אמר שמואל: אין מעברין את השנה אלא אם כן היתה תקופה\u0004 (וכאן מדובר בתקופת תמוז) \u0003חסירה\u0004 מהשלמת תשעים ואחד ימיה \u0003רובה של חודש\u0004 תשרי, ויתברר איפוא שתקופת תשרי (יום שוויון היום והלילה הסתווי) מתחילה לאחר שעבר רובו של חודש תשרי. ומאחר ועל חג הסוכות לחול בתוך תקופת תשרי, ולחשבון זה הוא לא יחול אלא לאחר מכן, הרי יש צורך להוסיף חודש לשנה הקודמת ולעבר את חודש אדר, ובכך יחול חג הסוכות בתוך תקופת תשרי. ושואלים: \u0003וכמה רובה של חודש\u0004 שבמקרה כזה מעברים את השנה? ומשיבים: שתקופת תמוז נכנסת \u0003ששה עשר יום,\u0004 אלו \u0003דברי ר' יהודה.\u0004"],["\u0003ר' יוסי אומר:\u0004 רק אם היתה תקופת תמוז עודפת ונכנסת בחודש תשרי \u0003אחד ועשרים יום,\u0004 מעברים. ומסבירים: \u0003ושניהם מקרא אחד דרשו,\u0004 והוא: \u0003\"\u0004ו\u0003חג האסיף תקופת השנה\"\u0004 (שמות לד, כב), שהבינו שחג האסיף (חג הסוכות) צריך להיות בתקופה חדשה של השנה. \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יהודה, \u0005סבר]:\u0006 \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003חג בעינן\u0004 \u0005[אנו צריכים]\u0006 שיהא \u0003בתקופה חדשה,\u0004 שחג האסיף (מתחילת חול המועד של סוכות) צריך להיות כולו לאחר תקופת תשרי (יום שוויון היום והלילה הסתווי). \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוסי, \u0005סבר]\u0006 כי לפחות \u0003מקצת חג בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה \u0003בתקופה חדשה,\u0004 ודי גם ביום אחד, ורק אם כל החג (עד עשרים ושנים בתשרי) הוא עדיין בתקופת תמוז יש לעבר את השנה.","ושואלים: \u0003מאי קא סברי\u0004 \u0005[מה סברו]\u0006 שני חכמים אלה? \u0003אי קסברי\u0004 \u0005[אם סבורים הם]\u0006 ש\u0003יום\u0004 ה\u0003תקופה\u0004 \u0003גומר\u0004 את התקופה, ויום זה נחשב לתקופה הקודמת, \u0003בלאו הכי נמי\u0004 \u0005[בלא זה גם כן],\u0006 \u0003לא למאן ד\u0004\u0003אמר כוליה\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר\u0006 כי \u0005כל]\u0006 ה\u0003חג\u0004 צריך להיות בתקופה החדשה, \u0003איכא\u0004 \u0005[יש כאן],\u0006 שהרי אם היום האחרון שייך עוד לתקופה הקודמת הרי ששישה עשר בתשרי (תחילת חג האסיף) שייך עדיין לתקופה הישנה. \u0003ולא למאן ד\u0004\u0003אמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי לפחות \u0003מקצת חג\u0004 צריך שיהיה בתקופה חדשה \u0003איכא\u0004 \u0005[יש],\u0006 שאם חלה התקופה בעשרים ואחד בתשרי, לא החלה התקופה החדשה אלא בעשרים ושנים בו, לאחר שנגמר חג האסיף! \u0003אלא\u0004 ודאי \u0003קסברי\u0004 \u0005[סבורים הם]\u0006 שניהם כי \u0003יום תקופה מתחיל\u0004 את התקופה החדשה.","ועל מסקנה זו \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא אחרת: \u0003יום תקופה גומר,\u0004 אלו \u0003דברי ר' יהודה, ר' יוסי אומר: יום תקופה מתחיל,\u0004 הרי שהם חולקים בבעיה זו, ואין לפרש את הברייתא הקודמת לפי שיטות אלה.","\u0003ועוד, תניא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003אין מעברין את השנה אלא אם כן היתה תקופה חסירה רובו של חודש, וכמה\u0004 הוא \u0003רובו של חדש? ששה עשר יום,\u0004 \u0003ר' יהודה אומר: שתי ידות בחודש\u0004 (שני שלישים מן החודש). \u0003וכמה שתי ידות בחדש?\u0004 — \u0003עשרים יום.\u0004","\u0003ר' יוסי אומר: מחשבין,\u0004 אם היה בחודש ניסן כבר \u0003ששה עשר\u0004 יום בתוך התקופה ש\u0003לפני הפסח\u0004 (תקופת טבת) — \u0003מעברין\u0004 את השנה, כך שיחול הפסח בתוך תקופת ניסן, אבל אם חל חודש תשרי באופן שהיו בו \u0003ששה עשר\u0004 יום בתקופה ש\u0003לפני החג\u0004 (תקופת תמוז) — \u0003אין מעברין. ר' שמעון אומר: אף\u0004 באופן שהיו בו \u0003ששה עשר\u0004 יום בתקופה ש\u0003לפני החג\u0004 — \u0003מעברין. אחרים אומרים:\u0004 מעברים אפילו על \u0003מיעוטו\u0004 של חודש, \u0003וכמה מיעוטו? ארבעה עשר יום.\u0004 ומסכמים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מברייתא אחת לשניה, שאין דברי חכמים בהן שווים אלה לאלה.","ודנים באותה תוספתא לגופה: \u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003ר' יהודה אומר: שתי ידות בחודש,\u0004 שהן \u0003עשרים יום. ר' יוסי אומר: מחשבין, ששה עשר יום לפני הפסח\u0004 — \u0003מעברין.\u0004 ומקשים: הלא \u0003היינו\u0004 \u0005[זוהי\u0006 שיטת\u0005]\u0006 \u0003ר' יהודה!\u0004 שאם נערוך חשבון נמצא כי עיבור השנה בשל התקופה שישה עשר יום לפני פסח זהה לעיבורה בשל תקופת תשרי עשרים יום לפני החג!","ומשיבים: \u0003יום תקופה גומר ויום תקופה מתחיל איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005],\u0006 ונחלקו בשאלה זו, האם מצרפים את היום האחרון לתקופה הישנה או החדשה.","בהמשך דברי ר' יוסי \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ששה עשר\u0004 יום \u0003לפני החג אין מעברין.\u0004 ומדקדקים, \u0003אלא ל\u0004שיטת \u0003ר' יוסי\u0004 תאמר כי \u0003ששה עשר\u0004 יום \u0003לפני החג הוא\u0004 ש\u0003לא\u0004 מעברים, \u0003הא שיבסר ותמניסר\u0004 \u0005[הרי\u0006 אם היה זה \u0005שבעה עשר ושמונה עשר\u0006 יום לפני החג\u0005]\u0006 — \u0003מעברין?\u0004","\u0003והאמר\u0004 \u0005[והרי אמר]:\u0006 \u0003ששה עשר לפני הפסח,\u0004 ומכאן נדייק: דווקא שישה עשר — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בציר\u0004 \u0005[בפחות]\u0006 — \u0003לא,\u0004 והרי סתירה בין הדברים!","ומשיבים: \u0003לא,\u0004 אין לדייק כך, אלא \u0003אידי ואידי\u0004 \u0005[זה וזה],\u0006 בשני המקרים \u0003אין מעברין, ואיידי דתנא רישא\u0004 \u0005[ומתוך ששנה בתחילה]\u0006 \u0003\"ששה עשר לפני הפסח\", תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003\"ששה עשר לפני החג\",\u0004 ואין לדקדק מכאן ששישה עשר ולא יותר.","עוד שנינו ש\u0003ר' שמעון אומר: אף ששה עשר לפני החג מעברין.\u0004 ומקשים: אם כן, \u0003היינו\u0004 \u0005[זהו]\u0006 בדיוק כשיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]!\u0006"],["ומשיבים: אף כאן \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לגבי \u0003יום תקופה מתחיל, ויום תקופה גומר. ו\u0004אולם \u0003לא מסיימי\u0004 \u0005[אינם מוגדרים],\u0006 שנראה לנו שבענין זה הם חולקים, אך לא ברור מדבריהם מה דעתו של כל אחד מהם.","\u0003אחרים אומרים: מיעוטו\u0004 של חודש מעברים, \u0003וכמה מיעוטו? ארבעה עשר יום.\u0004 ושואלים: \u0003מאי קסברי\u0004 \u0005[מה סבורים]\u0006 אחרים, מהו יסוד סברתם? \u0003אי קסברי\u0004 \u0005[אם סבורים הם]\u0006 כי \u0003יום תקופה גומר, ו\u0004גם \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003חג\u0004 יהיה בתקופה חדשה \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003האיכא\u0004 \u0005[הרי יש]\u0006 מילוי תנאי זה אף בחמישה עשר! \u0003אמר רב שמואל בר רב יצחק: אחרים בתקופת ניסן קיימי\u0004 \u0005[עומדים,\u0006 דנים\u0005],\u0006 שדברי אחרים אינם מתייחסים לתקופת תשרי אלא לתקופת ניסן, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שמור את חדש האביב\u0004 ועשית פסח לה' אלהיך\u0003\"\u0004 (דברים טז, א), והם מבינים: \u0003שמור אביב של תקופה\u0004 (כלומר, יום תקופת האביב, יום שוויון היום והלילה) \u0003שיהא בחדש ניסן.\u0004 שיש לדאוג שתקופת ניסן תהא עם תחילת חודש ניסן, ותחילת החודש היא לכל היותר ארבעה עשר יום בו.","ושואלים: ובמקרה כגון זה, מדוע עיברו את השנה? \u0003וליעבריה\u0004 \u0005[ושיעברו]\u0006 את חודש \u0003אדר\u0004 ויוסיפו לו יום אחד, וממילא יהיה אביב של תקופה בניסן! ומשיבים, \u0003אמר רב אחא בר יעקב:\u0004 ה\u0003תנא,\u0004 אחרים, \u0003מלמעלה למטה קחשיב\u0004 \u0005[חשב],\u0006 כלומר, אין להבין ארבעה עשר יום דווקא אלא \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: \u0003עד מיעוטו מעברין,\u0004 כלומר, אם התקופה היא באחד מימי סוף חודש ניסן מעברים, וכן מעברים עד שיגיע למיעוטו, \u0003וכמה מיעוטו? ארבעה עשר יום,\u0004 אבל אם חלה התקופה בארבעה עשר עצמו אין מעברים אלא מוסיפים יום לחודש אדר.","\u0003רבינא אמר: לעולם\u0004 אפשר לפרש כפי שהבינו את הדברים מתחילה, כי \u0003אחרים בתשרי קיימי\u0004 \u0005[עומדים,\u0006 דנים\u0005].\u0006 \u0003וקסברי\u0004 \u0005[וסבורים]\u0006 \u0003אחרים\u0004 כי \u0003כוליה\u0004 \u0005[\u0006את \u0005כל]\u0006 ה\u0003חג בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה בתקופה החדשה, אלא שלדעת אחרים נכלל בתוך זה גם \u0003יום טוב ראשון\u0004 של חג הסוכות. ומקשים: איך אפשר לומר שגם \u0003יום טוב ראשון?\u0004 הלא \u0003\"חג האסף\"\u0004 (שמות כג, טז) \u0003כתיב\u0004 \u0005[נאמר]!\u0006 משמע שחג שבו אוספים את התבואה, וביום טוב הרי אסור לאסוף את התבואה! ומשיבים: שלדעת אחרים אין פירוש \"וחג האסיף\" שבו עושים את פעולת האסיפה ממש, אלא \u0003חג הבא בזמן אסיפה,\u0004 הזמן שאוספים בו כרגיל את התבואות, בעונת הסתיו.","שנינו במשנה כי \u0003סמיכת זקנים\u0004 בשלושה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא מדרש הלכה זה, נאמר בכתוב: \u0003\"וסמכו זקני\u0004 העדה את ידיהם על ראש הפר לפני ה'\u0003\"\u0004 (ויקרא ד, טו), ומי הם זקנים אלה לא נתפרש בכתוב, ושמא תאמר: \u0003יכול\u0004 אלו \u0003זקני השוק,\u0004 כלומר, סתם זקנים — \u0003תלמוד לומר: \"עדה\",\u0004 כלומר, מראשי העם ושופטיו.","\u0003אי\u0004 \u0005[אם]\u0006 היה נאמר רק \u0003\"עדה\", יכול\u0004 אתה לומר שיהו אלו \u0003קטני עדה,\u0004 כלומר, חברי סנהדרין קטנה — \u0003תלמוד לומר: \"העדה\"\u0004 וכוונתו — \u0003מיוחדין שבעדה.\u0004 הרי למדנו שזקני סנהדרין גדולה הם הסומכים. \u0003וכמה הן?\u0004 נאמר \u0003\"וסמכו\"\u0004 לשון רבים — הרי \u0003שנים, \"זקני\"\u0004 לשון רבים — עוד \u0003שנים, ואין בית דין שקול\u0004 — \u0003מוסיפין עליהם עוד אחד, הרי כאן חמשה\u0004 זקנים. אלו \u0003דברי ר' יהודה. ר' שמעון אומר:\u0004 אין לדרוש כן, אלא \u0003\"זקני\"\u0004 — \u0003שנים, ואין בית דין שקול,\u0004 לכן \u0003מוסיפין עליהן עוד אחד, הרי כאן שלשה\u0004 בלבד.","ושואלים: \u0003ור' שמעון הכתיב\u0004 \u0005[הלא נאמר]\u0006 \u0003\"וסמכו\",\u0004 ובודאי בא הדבר ללמד ולרבות עוד דבר מה! ומשיבים: \"וסמכו\" \u0003ההוא מיבעי ליה לגופיה\u0004 \u0005[נצרך לו לגופו\u0006 של ענין\u0005],\u0006 להודיע שזקני העדה יסמכו ידיהם על הפר. ושואלים: \u0003ור' יהודה,\u0004 מה אומר הוא על כך? ומסבירים: לדעתו \u0003לגופיה\u0004 \u0005[לגופו\u0006 של הדין\u0005]\u0006 \u0003לא צריך\u0004 כלל להיאמר, ש\u0003אם\u0004 תאמר \u0003כן,\u0004 ש\u0003לא אתי\u0004 \u0005[באה]\u0006 המלה \u0003\"וסמכו\" לדרשה,\u0004 די לו \u0003ליכתוב \"זקני העדה ידיהם על ראש הפר\",\u0004 ונבין כי ישימו הזקנים ויסמכו ידיהם על ראש הפר.","ושואלים: \u0003ור' שמעון\u0004 מה משיב הוא על טענה זו? ומשיבים: \u0003אי כתיב הכי\u0004 \u0005[אילו היה כתוב כך],\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"על\u0004 ראש הפר \u0003\"?\u0004 כוונתו \u0003בסמוך\u0004 לראש הפר, שהרבה פעמים לשון \"על\" משמעה \"ליד\", בסמוך ולא עליו ממש. ושואלים: \u0003ור' יהודה,\u0004 מה הוא משיב על טענה זו? \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"ראש\" \"ראש\" מעולה.\u0004 שנאמרה הנחת ידים על ראש העולה, והכוונה שם להנחה על הראש ממש ובכח, כך סמיכה על שאר קרבנות. \u0003ור' שמעון לא גמר\u0004 \u0005[למד]\u0006 גזירה שווה זו, ולא קיבל מרבותיו לימוד זה של \u0003\"ראש\" \"ראש\" מעולה.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003סמיכה וסמיכת זקנים\u0004 צריכים להיות \u0003בשלשה.\u0004 ושואלים \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003\"סמיכה\", ומאי\u0004 \u0005[ומה\u0006 היא\u0005]\u0006 \u0003\"סמיכת זקנים\",\u0004 שאחד מאלה פירושו לסמוך על פר העלם דבר של ציבור, אך מה משמעות הביטוי השני? \u0003אמר ר' יוחנן: מיסמך סבי\u0004 \u0005[סמיכת הזקנים],\u0006 כלומר, למנות את החכמים ולהכתירם בתואר \"רבי\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מיסמך סבי\u0004 \u0005[סמיכת הזקנים]\u0006 \u0003בשלשה מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אילימא מדכתיב\u0004 \u0005[אם תאמר ממה שנאמר]\u0006 במשה כאשר מינה את יהושע \u0003\"ויסמך את ידיו עליו\u0004 ויצוהו\u0003\"\u0004 (במדבר כז, כג), \u0003אי הכי תסגי בחד\u0004 \u0005[אם כך שיהיה די\u0006 באדם \u0005אחד]\u0006 שיסמוך. \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003משה במקום שבעים וחד קאי\u0004 \u0005[ואחד עומד],\u0006 שאין חכם בודד ממלא את מקומו של משה לדורות, אלא רק הסנהדרי הגדולה היא במקום משה. \u0003אי הכי ליבעי\u0004 \u0005[אם כך שיצטרכו]\u0006 בכל סמיכה \u0003שבעים וחד\u0004 \u0005[ואחד]!\u0006 ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר, ואין לנו ראיה ברורה לכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 האם \u0003בידא\u0004 \u0005[ביד]\u0006 \u0003ממש סמכין ליה\u0004 \u0005[סומכים אותו]\u0006 את האיש שרוצים למנותו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סמכין ליה בשמא\u0004 \u0005[סומכים אותו בשם]\u0006 שממנים אותו בציבור, \u0003קרי ליה\u0004 \u0005[קוראים לו]\u0006 \u0003\"רבי\", ויהבי ליה רשותא למידן\u0004 \u0005[ונותנים לו רשות לדון]\u0006 \u0003דיני קנסות.\u0004","ומקשים: \u0003וחד לא סמיך\u0004 \u0005[ו\u0006כי אדם \u0005אחד\u0006 בלבד \u0005אינו\u0006 יכול \u0005לסמוך]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יהודה אמר רב: ברם\u0004 \u0005[אמנם]\u0006 \u0003זכור אותו האיש לטוב, ור' יהודה בן בבא שמו, שאילמלא הוא נשתכחו דיני קנסות מישראל.\u0004 את המשך סיפור הדברים קוטעים בתמיהה: \u0003נשתכחו?! נגרוסינהו\u0004 \u0005[שנלמד אותן]\u0006 וממילא לא ישתכחו? \u0003אלא\u0004 היתה הכוונה לומר"]]};
